SELECT * FROM jsonb_to_recordset('[{"level":"SSS2","term":3,"seq":1,"name":"Dramatic Acts and Scene Transitions","intro":"Detailed drama reading follows how acts and scenes organise conflict and change what the audience knows. A play does not have to contain a fixed number of acts. Locate a transition by changes of time, space, characters or dramatic pressure.","passage":"ACT I, SCENE II. (The school hall. An empty chair stands beside a notice.) ZARA: We begin without the chairperson. IFE: The votes are not counted. (The lights dim.) ACT II, SCENE I. (The next morning. The notice has been taken down.) ZARA: Someone made a decision in the night.","worked":"The transition withholds the decision from the audience and shifts time to the next morning. The changed notice is concrete evidence that an event occurred between scenes, but it does not identify who removed it.","concepts":[["Act division","A broad structural segment of a play containing dramatic developments","Act II begins on the next morning"],["Scene transition","A change of setting time or people between units of action","The hall shifts from evening to morning"],["Offstage action","An important event occurs outside the audience''s direct view","The notice is removed between scenes"],["Exposition","Information introduces the dramatic situation and relationships","The first scene reveals an uncounted vote"],["Dramatic suspense","Unresolved information encourages expectation","The audience does not know who moved the notice"]],"slug":"lit-sss2-t3-dramatic-acts-and-scene-transitions","code":"G26LITSSS2T3U1","body":"# Dramatic Acts and Scene Transitions — SSS2 Literature in English, Third Term\n\n## What you should achieve\nDefine and accurately apply five central literary concepts; use exact evidence from a new passage to support an interpretation; connect technique to its effect; and identify the limits of what the passage permits you to infer.\n\n## Conceptual foundation\nDetailed drama reading follows how acts and scenes organise conflict and change what the audience knows. A play does not have to contain a fixed number of acts. Locate a transition by changes of time, space, characters or dramatic pressure.\n\n**Source note:** The passage and exercises below are original THE GUIDE teaching examples. They are not passages from a historical WAEC, NECO or JAMB paper, and are not represented as quotations from copyrighted prescribed books. Read the school-approved books in full for set-text analysis.\n\n## New worked passage\n> ACT I, SCENE II. (The school hall. An empty chair stands beside a notice.) ZARA: We begin without the chairperson. IFE: The votes are not counted. (The lights dim.) ACT II, SCENE I. (The next morning. The notice has been taken down.) ZARA: Someone made a decision in the night.\n\n## Interpretation: a model response\nThe transition withholds the decision from the audience and shifts time to the next morning. The changed notice is concrete evidence that an event occurred between scenes, but it does not identify who removed it.\n\nRead the passage once for literal information, again to notice diction, structure, dialogue, imagery or action, and a third time to test a thesis against a precise textual clue. A justified interpretation is not simply a personal opinion: it has a claim, evidence and reasoning. Different careful readers may make different claims, but they must account for the same details.\n\n## Five important concepts\n### 1. Act division\n**Meaning:** A broad structural segment of a play containing dramatic developments.\n**Original illustration:** Act II begins on the next morning.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 2. Scene transition\n**Meaning:** A change of setting time or people between units of action.\n**Original illustration:** The hall shifts from evening to morning.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 3. Offstage action\n**Meaning:** An important event occurs outside the audience''s direct view.\n**Original illustration:** The notice is removed between scenes.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 4. Exposition\n**Meaning:** Information introduces the dramatic situation and relationships.\n**Original illustration:** The first scene reveals an uncounted vote.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 5. Dramatic suspense\n**Meaning:** Unresolved information encourages expectation.\n**Original illustration:** The audience does not know who moved the notice.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n## Method: move from detail to interpretation\n1. **Observe:** Identify who is speaking, what physically happens and which important detail stands out.\n2. **Classify:** Choose one relevant literary term. Do not force every device into the passage.\n3. **Evidence:** Quote a brief original phrase or describe a stage action exactly.\n4. **Reason:** Explain how that evidence affects characterisation, atmosphere, conflict, theme or audience knowledge.\n5. **Qualify:** Distinguish a well-supported reading from an assumption that the passage does not prove.\n\n## Guided application\nReturn to the original passage. State the central conflict or problem in one sentence. Choose two of the five concepts and write a separate evidence-based explanation for each. What does a careful audience know that a character may not know? If this question does not apply, explain why instead of inventing hidden facts.\n\n## Independent practice and rubric\nCreate a short original extract on a related situation, then write a 150–200 word close reading. For a ten-mark analytical paragraph, allocate 2 marks to a clear claim, 2 to accurate terminology, 3 to appropriate textual evidence and explanation, 2 to weighing a plausible alternative or limitation, and 1 to clear organisation. Your score should reward justified reasoning, not memorising one interpretation.\n\n## Common misconceptions\nAn original model excerpt is not a prescribed examination extract. A character''s words are not automatically an objective truth. A stage direction is not spoken dialogue. A metaphor is not literal proof of an event. A detailed explanation should show how the device works instead of merely naming it.\n\n## Check your own progress\nExplain each concept without looking at your flashcards. Attempt the accompanying ten original multiple-choice questions; review the reasoning after every incorrect answer. Compare your written response with the rubric rather than relying only on an MCQ score.","objectives":["Use accurate literary concepts in close reading","Ground arguments in exact words or stage actions","Evaluate alternative explanations responsibly"],"points":["Act division: A broad structural segment of a play containing dramatic developments","Scene transition: A change of setting time or people between units of action","Offstage action: An important event occurs outside the audience''s direct view","Exposition: Information introduces the dramatic situation and relationships","Dramatic suspense: Unresolved information encourages expectation"],"cards":[{"front":"Define Act division in Dramatic Acts and Scene Transitions.","back":"A broad structural segment of a play containing dramatic developments. Original illustration: Act II begins on the next morning.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Scene transition in Dramatic Acts and Scene Transitions.","back":"A change of setting time or people between units of action. Original illustration: The hall shifts from evening to morning.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Offstage action in Dramatic Acts and Scene Transitions.","back":"An important event occurs outside the audience''s direct view. Original illustration: The notice is removed between scenes.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Exposition in Dramatic Acts and Scene Transitions.","back":"Information introduces the dramatic situation and relationships. Original illustration: The first scene reveals an uncounted vote.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Dramatic suspense in Dramatic Acts and Scene Transitions.","back":"Unresolved information encourages expectation. Original illustration: The audience does not know who moved the notice.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"How do you build a convincing interpretation of dramatic acts and scene transitions?","back":"State a focused claim, cite an exact textual detail, explain the effect, and separate solid evidence from plausible inference.","sourceKind":"original-literature-skills","difficulty":"medium"}],"questions":[{"question":"In \"Dramatic Acts and Scene Transitions\" at SSS2, which concept is defined as: A broad structural segment of a play containing dramatic developments?","options":[{"id":"A","text":"Scene transition"},{"id":"B","text":"Act division"},{"id":"C","text":"Offstage action"},{"id":"D","text":"Exposition"}],"answer":"B","explanation":"The concept is Act division. It means A broad structural segment of a play containing dramatic developments. An original example is: Act II begins on the next morning. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Dramatic Acts and Scene Transitions\": Act II begins on the next morning?","options":[{"id":"A","text":"Act division"},{"id":"B","text":"Scene transition"},{"id":"C","text":"Offstage action"},{"id":"D","text":"Exposition"}],"answer":"A","explanation":"The best answer is Act division because A broad structural segment of a play containing dramatic developments. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Dramatic Acts and Scene Transitions\" at SSS2, which concept is defined as: A change of setting time or people between units of action?","options":[{"id":"A","text":"Act division"},{"id":"B","text":"Offstage action"},{"id":"C","text":"Exposition"},{"id":"D","text":"Scene transition"}],"answer":"D","explanation":"The concept is Scene transition. It means A change of setting time or people between units of action. An original example is: The hall shifts from evening to morning. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Dramatic Acts and Scene Transitions\": The hall shifts from evening to morning?","options":[{"id":"A","text":"Act division"},{"id":"B","text":"Offstage action"},{"id":"C","text":"Scene transition"},{"id":"D","text":"Exposition"}],"answer":"C","explanation":"The best answer is Scene transition because A change of setting time or people between units of action. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Dramatic Acts and Scene Transitions\" at SSS2, which concept is defined as: An important event occurs outside the audience''s direct view?","options":[{"id":"A","text":"Act division"},{"id":"B","text":"Offstage action"},{"id":"C","text":"Scene transition"},{"id":"D","text":"Exposition"}],"answer":"B","explanation":"The concept is Offstage action. It means An important event occurs outside the audience''s direct view. An original example is: The notice is removed between scenes. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Dramatic Acts and Scene Transitions\": The notice is removed between scenes?","options":[{"id":"A","text":"Offstage action"},{"id":"B","text":"Act division"},{"id":"C","text":"Scene transition"},{"id":"D","text":"Exposition"}],"answer":"A","explanation":"The best answer is Offstage action because An important event occurs outside the audience''s direct view. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Dramatic Acts and Scene Transitions\" at SSS2, which concept is defined as: Information introduces the dramatic situation and relationships?","options":[{"id":"A","text":"Act division"},{"id":"B","text":"Scene transition"},{"id":"C","text":"Offstage action"},{"id":"D","text":"Exposition"}],"answer":"D","explanation":"The concept is Exposition. It means Information introduces the dramatic situation and relationships. An original example is: The first scene reveals an uncounted vote. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Dramatic Acts and Scene Transitions\": The first scene reveals an uncounted vote?","options":[{"id":"A","text":"Act division"},{"id":"B","text":"Scene transition"},{"id":"C","text":"Exposition"},{"id":"D","text":"Offstage action"}],"answer":"C","explanation":"The best answer is Exposition because Information introduces the dramatic situation and relationships. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Dramatic Acts and Scene Transitions\" at SSS2, which concept is defined as: Unresolved information encourages expectation?","options":[{"id":"A","text":"Act division"},{"id":"B","text":"Dramatic suspense"},{"id":"C","text":"Scene transition"},{"id":"D","text":"Offstage action"}],"answer":"B","explanation":"The concept is Dramatic suspense. It means Unresolved information encourages expectation. An original example is: The audience does not know who moved the notice. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Dramatic Acts and Scene Transitions\": The audience does not know who moved the notice?","options":[{"id":"A","text":"Dramatic suspense"},{"id":"B","text":"Act division"},{"id":"C","text":"Scene transition"},{"id":"D","text":"Offstage action"}],"answer":"A","explanation":"The best answer is Dramatic suspense because Unresolved information encourages expectation. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."}]},{"level":"SSS2","term":3,"seq":2,"name":"Power and Subtext in Dialogue","intro":"Words in a play express status as well as information. A command, evasion or interruption can reveal power relations. Subtext describes implied intentions, but the interpreter must not pretend to read an unshown private mind.","passage":"DIRECTOR: The meeting begins at six. AMAKA: Most workers leave at five. DIRECTOR: Then they should make arrangements. (Amaka folds the petition.) AMAKA: We will send our response in writing.","worked":"The director controls timing; Amaka identifies its practical consequences. Her folded petition can suggest frustration, not proof that she has surrendered. The written response offers an alternative form of participation.","concepts":[["Status","Relative standing or authority shaping an exchange","The director schedules the meeting"],["Subtext","Meaning suggested beneath literal dialogue","Amaka''s clipped reply may convey resistance"],["Interruption","Speech broken by another voice can reveal conflict","The director cuts off a worker''s explanation"],["Gesture","Movement provides non-verbal dramatic evidence","Amaka folds her petition before speaking"],["Negotiation","Characters attempt to alter terms of a dispute","Amaka proposes a written response to the meeting"]],"slug":"lit-sss2-t3-power-and-subtext-in-dialogue","code":"G26LITSSS2T3U2","body":"# Power and Subtext in Dialogue — SSS2 Literature in English, Third Term\n\n## What you should achieve\nDefine and accurately apply five central literary concepts; use exact evidence from a new passage to support an interpretation; connect technique to its effect; and identify the limits of what the passage permits you to infer.\n\n## Conceptual foundation\nWords in a play express status as well as information. A command, evasion or interruption can reveal power relations. Subtext describes implied intentions, but the interpreter must not pretend to read an unshown private mind.\n\n**Source note:** The passage and exercises below are original THE GUIDE teaching examples. They are not passages from a historical WAEC, NECO or JAMB paper, and are not represented as quotations from copyrighted prescribed books. Read the school-approved books in full for set-text analysis.\n\n## New worked passage\n> DIRECTOR: The meeting begins at six. AMAKA: Most workers leave at five. DIRECTOR: Then they should make arrangements. (Amaka folds the petition.) AMAKA: We will send our response in writing.\n\n## Interpretation: a model response\nThe director controls timing; Amaka identifies its practical consequences. Her folded petition can suggest frustration, not proof that she has surrendered. The written response offers an alternative form of participation.\n\nRead the passage once for literal information, again to notice diction, structure, dialogue, imagery or action, and a third time to test a thesis against a precise textual clue. A justified interpretation is not simply a personal opinion: it has a claim, evidence and reasoning. Different careful readers may make different claims, but they must account for the same details.\n\n## Five important concepts\n### 1. Status\n**Meaning:** Relative standing or authority shaping an exchange.\n**Original illustration:** The director schedules the meeting.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 2. Subtext\n**Meaning:** Meaning suggested beneath literal dialogue.\n**Original illustration:** Amaka''s clipped reply may convey resistance.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 3. Interruption\n**Meaning:** Speech broken by another voice can reveal conflict.\n**Original illustration:** The director cuts off a worker''s explanation.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 4. Gesture\n**Meaning:** Movement provides non-verbal dramatic evidence.\n**Original illustration:** Amaka folds her petition before speaking.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 5. Negotiation\n**Meaning:** Characters attempt to alter terms of a dispute.\n**Original illustration:** Amaka proposes a written response to the meeting.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n## Method: move from detail to interpretation\n1. **Observe:** Identify who is speaking, what physically happens and which important detail stands out.\n2. **Classify:** Choose one relevant literary term. Do not force every device into the passage.\n3. **Evidence:** Quote a brief original phrase or describe a stage action exactly.\n4. **Reason:** Explain how that evidence affects characterisation, atmosphere, conflict, theme or audience knowledge.\n5. **Qualify:** Distinguish a well-supported reading from an assumption that the passage does not prove.\n\n## Guided application\nReturn to the original passage. State the central conflict or problem in one sentence. Choose two of the five concepts and write a separate evidence-based explanation for each. What does a careful audience know that a character may not know? If this question does not apply, explain why instead of inventing hidden facts.\n\n## Independent practice and rubric\nCreate a short original extract on a related situation, then write a 150–200 word close reading. For a ten-mark analytical paragraph, allocate 2 marks to a clear claim, 2 to accurate terminology, 3 to appropriate textual evidence and explanation, 2 to weighing a plausible alternative or limitation, and 1 to clear organisation. Your score should reward justified reasoning, not memorising one interpretation.\n\n## Common misconceptions\nAn original model excerpt is not a prescribed examination extract. A character''s words are not automatically an objective truth. A stage direction is not spoken dialogue. A metaphor is not literal proof of an event. A detailed explanation should show how the device works instead of merely naming it.\n\n## Check your own progress\nExplain each concept without looking at your flashcards. Attempt the accompanying ten original multiple-choice questions; review the reasoning after every incorrect answer. Compare your written response with the rubric rather than relying only on an MCQ score.","objectives":["Use accurate literary concepts in close reading","Ground arguments in exact words or stage actions","Evaluate alternative explanations responsibly"],"points":["Status: Relative standing or authority shaping an exchange","Subtext: Meaning suggested beneath literal dialogue","Interruption: Speech broken by another voice can reveal conflict","Gesture: Movement provides non-verbal dramatic evidence","Negotiation: Characters attempt to alter terms of a dispute"],"cards":[{"front":"Define Status in Power and Subtext in Dialogue.","back":"Relative standing or authority shaping an exchange. Original illustration: The director schedules the meeting.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Subtext in Power and Subtext in Dialogue.","back":"Meaning suggested beneath literal dialogue. Original illustration: Amaka''s clipped reply may convey resistance.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Interruption in Power and Subtext in Dialogue.","back":"Speech broken by another voice can reveal conflict. Original illustration: The director cuts off a worker''s explanation.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Gesture in Power and Subtext in Dialogue.","back":"Movement provides non-verbal dramatic evidence. Original illustration: Amaka folds her petition before speaking.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Negotiation in Power and Subtext in Dialogue.","back":"Characters attempt to alter terms of a dispute. Original illustration: Amaka proposes a written response to the meeting.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"How do you build a convincing interpretation of power and subtext in dialogue?","back":"State a focused claim, cite an exact textual detail, explain the effect, and separate solid evidence from plausible inference.","sourceKind":"original-literature-skills","difficulty":"medium"}],"questions":[{"question":"In \"Power and Subtext in Dialogue\" at SSS2, which concept is defined as: Relative standing or authority shaping an exchange?","options":[{"id":"A","text":"Subtext"},{"id":"B","text":"Interruption"},{"id":"C","text":"Gesture"},{"id":"D","text":"Status"}],"answer":"D","explanation":"The concept is Status. It means Relative standing or authority shaping an exchange. An original example is: The director schedules the meeting. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Power and Subtext in Dialogue\": The director schedules the meeting?","options":[{"id":"A","text":"Subtext"},{"id":"B","text":"Interruption"},{"id":"C","text":"Status"},{"id":"D","text":"Gesture"}],"answer":"C","explanation":"The best answer is Status because Relative standing or authority shaping an exchange. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Power and Subtext in Dialogue\" at SSS2, which concept is defined as: Meaning suggested beneath literal dialogue?","options":[{"id":"A","text":"Status"},{"id":"B","text":"Subtext"},{"id":"C","text":"Interruption"},{"id":"D","text":"Gesture"}],"answer":"B","explanation":"The concept is Subtext. It means Meaning suggested beneath literal dialogue. An original example is: Amaka''s clipped reply may convey resistance. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Power and Subtext in Dialogue\": Amaka''s clipped reply may convey resistance?","options":[{"id":"A","text":"Subtext"},{"id":"B","text":"Status"},{"id":"C","text":"Interruption"},{"id":"D","text":"Gesture"}],"answer":"A","explanation":"The best answer is Subtext because Meaning suggested beneath literal dialogue. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Power and Subtext in Dialogue\" at SSS2, which concept is defined as: Speech broken by another voice can reveal conflict?","options":[{"id":"A","text":"Status"},{"id":"B","text":"Subtext"},{"id":"C","text":"Gesture"},{"id":"D","text":"Interruption"}],"answer":"D","explanation":"The concept is Interruption. It means Speech broken by another voice can reveal conflict. An original example is: The director cuts off a worker''s explanation. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Power and Subtext in Dialogue\": The director cuts off a worker''s explanation?","options":[{"id":"A","text":"Status"},{"id":"B","text":"Subtext"},{"id":"C","text":"Interruption"},{"id":"D","text":"Gesture"}],"answer":"C","explanation":"The best answer is Interruption because Speech broken by another voice can reveal conflict. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Power and Subtext in Dialogue\" at SSS2, which concept is defined as: Movement provides non-verbal dramatic evidence?","options":[{"id":"A","text":"Status"},{"id":"B","text":"Gesture"},{"id":"C","text":"Subtext"},{"id":"D","text":"Interruption"}],"answer":"B","explanation":"The concept is Gesture. It means Movement provides non-verbal dramatic evidence. An original example is: Amaka folds her petition before speaking. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Power and Subtext in Dialogue\": Amaka folds her petition before speaking?","options":[{"id":"A","text":"Gesture"},{"id":"B","text":"Status"},{"id":"C","text":"Subtext"},{"id":"D","text":"Interruption"}],"answer":"A","explanation":"The best answer is Gesture because Movement provides non-verbal dramatic evidence. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Power and Subtext in Dialogue\" at SSS2, which concept is defined as: Characters attempt to alter terms of a dispute?","options":[{"id":"A","text":"Status"},{"id":"B","text":"Subtext"},{"id":"C","text":"Interruption"},{"id":"D","text":"Negotiation"}],"answer":"D","explanation":"The concept is Negotiation. It means Characters attempt to alter terms of a dispute. An original example is: Amaka proposes a written response to the meeting. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Power and Subtext in Dialogue\": Amaka proposes a written response to the meeting?","options":[{"id":"A","text":"Status"},{"id":"B","text":"Subtext"},{"id":"C","text":"Negotiation"},{"id":"D","text":"Interruption"}],"answer":"C","explanation":"The best answer is Negotiation because Characters attempt to alter terms of a dispute. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."}]},{"level":"SSS2","term":3,"seq":3,"name":"Dramatic Irony and Audience Knowledge","intro":"Dramatic irony occurs when the audience knows information that a character lacks and that knowledge matters to the action. Contrast it with verbal irony, where an utterance may mean the opposite of its literal words.","passage":"(Behind the curtain, Fola places the repaired trophy on a table.) CHIMA: The trophy has been stolen! ADA: Call the police. (Fola enters carrying a cloth.) FOLA: I have something to show you. CHIMA: The thief always returns.","worked":"The audience witnessed the placement and therefore knows something Chima does not. His hasty accusation generates ironic tension. Nothing yet proves that Chima is malicious; his inference may simply be premature.","concepts":[["Dramatic irony","Audience knowledge differs crucially from a character''s knowledge","Viewers see Fola put the trophy behind the curtain"],["Verbal irony","A speaker intentionally means something other than literal wording","Wonderful security is said sarcastically after a loss"],["Situational irony","An outcome conflicts with ordinary expectation","A security lesson fails because its speaker misplaces the key"],["Foreshadowing","A hint prepares audience expectations about later action","A warning about the trophy precedes its disappearance"],["Revelation","New information changes interpretation of prior events","Fola explains he was repairing the trophy"]],"slug":"lit-sss2-t3-dramatic-irony-and-audience-knowledge","code":"G26LITSSS2T3U3","body":"# Dramatic Irony and Audience Knowledge — SSS2 Literature in English, Third Term\n\n## What you should achieve\nDefine and accurately apply five central literary concepts; use exact evidence from a new passage to support an interpretation; connect technique to its effect; and identify the limits of what the passage permits you to infer.\n\n## Conceptual foundation\nDramatic irony occurs when the audience knows information that a character lacks and that knowledge matters to the action. Contrast it with verbal irony, where an utterance may mean the opposite of its literal words.\n\n**Source note:** The passage and exercises below are original THE GUIDE teaching examples. They are not passages from a historical WAEC, NECO or JAMB paper, and are not represented as quotations from copyrighted prescribed books. Read the school-approved books in full for set-text analysis.\n\n## New worked passage\n> (Behind the curtain, Fola places the repaired trophy on a table.) CHIMA: The trophy has been stolen! ADA: Call the police. (Fola enters carrying a cloth.) FOLA: I have something to show you. CHIMA: The thief always returns.\n\n## Interpretation: a model response\nThe audience witnessed the placement and therefore knows something Chima does not. His hasty accusation generates ironic tension. Nothing yet proves that Chima is malicious; his inference may simply be premature.\n\nRead the passage once for literal information, again to notice diction, structure, dialogue, imagery or action, and a third time to test a thesis against a precise textual clue. A justified interpretation is not simply a personal opinion: it has a claim, evidence and reasoning. Different careful readers may make different claims, but they must account for the same details.\n\n## Five important concepts\n### 1. Dramatic irony\n**Meaning:** Audience knowledge differs crucially from a character''s knowledge.\n**Original illustration:** Viewers see Fola put the trophy behind the curtain.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 2. Verbal irony\n**Meaning:** A speaker intentionally means something other than literal wording.\n**Original illustration:** Wonderful security is said sarcastically after a loss.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 3. Situational irony\n**Meaning:** An outcome conflicts with ordinary expectation.\n**Original illustration:** A security lesson fails because its speaker misplaces the key.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 4. Foreshadowing\n**Meaning:** A hint prepares audience expectations about later action.\n**Original illustration:** A warning about the trophy precedes its disappearance.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 5. Revelation\n**Meaning:** New information changes interpretation of prior events.\n**Original illustration:** Fola explains he was repairing the trophy.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n## Method: move from detail to interpretation\n1. **Observe:** Identify who is speaking, what physically happens and which important detail stands out.\n2. **Classify:** Choose one relevant literary term. Do not force every device into the passage.\n3. **Evidence:** Quote a brief original phrase or describe a stage action exactly.\n4. **Reason:** Explain how that evidence affects characterisation, atmosphere, conflict, theme or audience knowledge.\n5. **Qualify:** Distinguish a well-supported reading from an assumption that the passage does not prove.\n\n## Guided application\nReturn to the original passage. State the central conflict or problem in one sentence. Choose two of the five concepts and write a separate evidence-based explanation for each. What does a careful audience know that a character may not know? If this question does not apply, explain why instead of inventing hidden facts.\n\n## Independent practice and rubric\nCreate a short original extract on a related situation, then write a 150–200 word close reading. For a ten-mark analytical paragraph, allocate 2 marks to a clear claim, 2 to accurate terminology, 3 to appropriate textual evidence and explanation, 2 to weighing a plausible alternative or limitation, and 1 to clear organisation. Your score should reward justified reasoning, not memorising one interpretation.\n\n## Common misconceptions\nAn original model excerpt is not a prescribed examination extract. A character''s words are not automatically an objective truth. A stage direction is not spoken dialogue. A metaphor is not literal proof of an event. A detailed explanation should show how the device works instead of merely naming it.\n\n## Check your own progress\nExplain each concept without looking at your flashcards. Attempt the accompanying ten original multiple-choice questions; review the reasoning after every incorrect answer. Compare your written response with the rubric rather than relying only on an MCQ score.","objectives":["Use accurate literary concepts in close reading","Ground arguments in exact words or stage actions","Evaluate alternative explanations responsibly"],"points":["Dramatic irony: Audience knowledge differs crucially from a character''s knowledge","Verbal irony: A speaker intentionally means something other than literal wording","Situational irony: An outcome conflicts with ordinary expectation","Foreshadowing: A hint prepares audience expectations about later action","Revelation: New information changes interpretation of prior events"],"cards":[{"front":"Define Dramatic irony in Dramatic Irony and Audience Knowledge.","back":"Audience knowledge differs crucially from a character''s knowledge. Original illustration: Viewers see Fola put the trophy behind the curtain.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Verbal irony in Dramatic Irony and Audience Knowledge.","back":"A speaker intentionally means something other than literal wording. Original illustration: Wonderful security is said sarcastically after a loss.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Situational irony in Dramatic Irony and Audience Knowledge.","back":"An outcome conflicts with ordinary expectation. Original illustration: A security lesson fails because its speaker misplaces the key.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Foreshadowing in Dramatic Irony and Audience Knowledge.","back":"A hint prepares audience expectations about later action. Original illustration: A warning about the trophy precedes its disappearance.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Revelation in Dramatic Irony and Audience Knowledge.","back":"New information changes interpretation of prior events. Original illustration: Fola explains he was repairing the trophy.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"How do you build a convincing interpretation of dramatic irony and audience knowledge?","back":"State a focused claim, cite an exact textual detail, explain the effect, and separate solid evidence from plausible inference.","sourceKind":"original-literature-skills","difficulty":"medium"}],"questions":[{"question":"In \"Dramatic Irony and Audience Knowledge\" at SSS2, which concept is defined as: Audience knowledge differs crucially from a character''s knowledge?","options":[{"id":"A","text":"Verbal irony"},{"id":"B","text":"Dramatic irony"},{"id":"C","text":"Situational irony"},{"id":"D","text":"Foreshadowing"}],"answer":"B","explanation":"The concept is Dramatic irony. It means Audience knowledge differs crucially from a character''s knowledge. An original example is: Viewers see Fola put the trophy behind the curtain. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Dramatic Irony and Audience Knowledge\": Viewers see Fola put the trophy behind the curtain?","options":[{"id":"A","text":"Dramatic irony"},{"id":"B","text":"Verbal irony"},{"id":"C","text":"Situational irony"},{"id":"D","text":"Foreshadowing"}],"answer":"A","explanation":"The best answer is Dramatic irony because Audience knowledge differs crucially from a character''s knowledge. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Dramatic Irony and Audience Knowledge\" at SSS2, which concept is defined as: A speaker intentionally means something other than literal wording?","options":[{"id":"A","text":"Dramatic irony"},{"id":"B","text":"Situational irony"},{"id":"C","text":"Foreshadowing"},{"id":"D","text":"Verbal irony"}],"answer":"D","explanation":"The concept is Verbal irony. It means A speaker intentionally means something other than literal wording. An original example is: Wonderful security is said sarcastically after a loss. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Dramatic Irony and Audience Knowledge\": Wonderful security is said sarcastically after a loss?","options":[{"id":"A","text":"Dramatic irony"},{"id":"B","text":"Situational irony"},{"id":"C","text":"Verbal irony"},{"id":"D","text":"Foreshadowing"}],"answer":"C","explanation":"The best answer is Verbal irony because A speaker intentionally means something other than literal wording. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Dramatic Irony and Audience Knowledge\" at SSS2, which concept is defined as: An outcome conflicts with ordinary expectation?","options":[{"id":"A","text":"Dramatic irony"},{"id":"B","text":"Situational irony"},{"id":"C","text":"Verbal irony"},{"id":"D","text":"Foreshadowing"}],"answer":"B","explanation":"The concept is Situational irony. It means An outcome conflicts with ordinary expectation. An original example is: A security lesson fails because its speaker misplaces the key. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Dramatic Irony and Audience Knowledge\": A security lesson fails because its speaker misplaces the key?","options":[{"id":"A","text":"Situational irony"},{"id":"B","text":"Dramatic irony"},{"id":"C","text":"Verbal irony"},{"id":"D","text":"Foreshadowing"}],"answer":"A","explanation":"The best answer is Situational irony because An outcome conflicts with ordinary expectation. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Dramatic Irony and Audience Knowledge\" at SSS2, which concept is defined as: A hint prepares audience expectations about later action?","options":[{"id":"A","text":"Dramatic irony"},{"id":"B","text":"Verbal irony"},{"id":"C","text":"Situational irony"},{"id":"D","text":"Foreshadowing"}],"answer":"D","explanation":"The concept is Foreshadowing. It means A hint prepares audience expectations about later action. An original example is: A warning about the trophy precedes its disappearance. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Dramatic Irony and Audience Knowledge\": A warning about the trophy precedes its disappearance?","options":[{"id":"A","text":"Dramatic irony"},{"id":"B","text":"Verbal irony"},{"id":"C","text":"Foreshadowing"},{"id":"D","text":"Situational irony"}],"answer":"C","explanation":"The best answer is Foreshadowing because A hint prepares audience expectations about later action. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Dramatic Irony and Audience Knowledge\" at SSS2, which concept is defined as: New information changes interpretation of prior events?","options":[{"id":"A","text":"Dramatic irony"},{"id":"B","text":"Revelation"},{"id":"C","text":"Verbal irony"},{"id":"D","text":"Situational irony"}],"answer":"B","explanation":"The concept is Revelation. It means New information changes interpretation of prior events. An original example is: Fola explains he was repairing the trophy. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Dramatic Irony and Audience Knowledge\": Fola explains he was repairing the trophy?","options":[{"id":"A","text":"Revelation"},{"id":"B","text":"Dramatic irony"},{"id":"C","text":"Verbal irony"},{"id":"D","text":"Situational irony"}],"answer":"A","explanation":"The best answer is Revelation because New information changes interpretation of prior events. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."}]},{"level":"SSS2","term":3,"seq":4,"name":"Stagecraft, Lighting and Symbolic Props","intro":"A script''s dialogue is only one component of drama. Lighting, props, sound and blocking can create emphasis and communicate spatial relationships. Analyse what stage directions actually require and how plausible performances might differ.","passage":"(A single lantern lights the committee table. Members sit apart. Outside, a slow knock repeats.) CHAIR: We have enough light to continue. (The lantern flickers.) MEMBER: Then let us examine the papers before it goes out.","worked":"The lantern is practically useful but can also suggest uncertainty or fragile authority. The repeated knock adds suspense. The seating arrangement reveals separation; it does not on its own prove political hostility.","concepts":[["Lighting cue","A direction about illumination that shapes visibility and mood","The lantern dims during the committee debate"],["Prop","An object handled or placed for dramatic action","Members pass a folder around the table"],["Sound cue","A staged noise supports action or atmosphere","A knock repeats outside the door"],["Blocking","Actors'' planned positions and movements convey relationships","Members sit far apart during an argument"],["Symbolic prop","A physical object acquires meaning beyond practical use","The fragile lantern mirrors uncertainty about the decision"]],"slug":"lit-sss2-t3-stagecraft-lighting-and-symbolic-props","code":"G26LITSSS2T3U4","body":"# Stagecraft, Lighting and Symbolic Props — SSS2 Literature in English, Third Term\n\n## What you should achieve\nDefine and accurately apply five central literary concepts; use exact evidence from a new passage to support an interpretation; connect technique to its effect; and identify the limits of what the passage permits you to infer.\n\n## Conceptual foundation\nA script''s dialogue is only one component of drama. Lighting, props, sound and blocking can create emphasis and communicate spatial relationships. Analyse what stage directions actually require and how plausible performances might differ.\n\n**Source note:** The passage and exercises below are original THE GUIDE teaching examples. They are not passages from a historical WAEC, NECO or JAMB paper, and are not represented as quotations from copyrighted prescribed books. Read the school-approved books in full for set-text analysis.\n\n## New worked passage\n> (A single lantern lights the committee table. Members sit apart. Outside, a slow knock repeats.) CHAIR: We have enough light to continue. (The lantern flickers.) MEMBER: Then let us examine the papers before it goes out.\n\n## Interpretation: a model response\nThe lantern is practically useful but can also suggest uncertainty or fragile authority. The repeated knock adds suspense. The seating arrangement reveals separation; it does not on its own prove political hostility.\n\nRead the passage once for literal information, again to notice diction, structure, dialogue, imagery or action, and a third time to test a thesis against a precise textual clue. A justified interpretation is not simply a personal opinion: it has a claim, evidence and reasoning. Different careful readers may make different claims, but they must account for the same details.\n\n## Five important concepts\n### 1. Lighting cue\n**Meaning:** A direction about illumination that shapes visibility and mood.\n**Original illustration:** The lantern dims during the committee debate.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 2. Prop\n**Meaning:** An object handled or placed for dramatic action.\n**Original illustration:** Members pass a folder around the table.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 3. Sound cue\n**Meaning:** A staged noise supports action or atmosphere.\n**Original illustration:** A knock repeats outside the door.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 4. Blocking\n**Meaning:** Actors'' planned positions and movements convey relationships.\n**Original illustration:** Members sit far apart during an argument.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 5. Symbolic prop\n**Meaning:** A physical object acquires meaning beyond practical use.\n**Original illustration:** The fragile lantern mirrors uncertainty about the decision.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n## Method: move from detail to interpretation\n1. **Observe:** Identify who is speaking, what physically happens and which important detail stands out.\n2. **Classify:** Choose one relevant literary term. Do not force every device into the passage.\n3. **Evidence:** Quote a brief original phrase or describe a stage action exactly.\n4. **Reason:** Explain how that evidence affects characterisation, atmosphere, conflict, theme or audience knowledge.\n5. **Qualify:** Distinguish a well-supported reading from an assumption that the passage does not prove.\n\n## Guided application\nReturn to the original passage. State the central conflict or problem in one sentence. Choose two of the five concepts and write a separate evidence-based explanation for each. What does a careful audience know that a character may not know? If this question does not apply, explain why instead of inventing hidden facts.\n\n## Independent practice and rubric\nCreate a short original extract on a related situation, then write a 150–200 word close reading. For a ten-mark analytical paragraph, allocate 2 marks to a clear claim, 2 to accurate terminology, 3 to appropriate textual evidence and explanation, 2 to weighing a plausible alternative or limitation, and 1 to clear organisation. Your score should reward justified reasoning, not memorising one interpretation.\n\n## Common misconceptions\nAn original model excerpt is not a prescribed examination extract. A character''s words are not automatically an objective truth. A stage direction is not spoken dialogue. A metaphor is not literal proof of an event. A detailed explanation should show how the device works instead of merely naming it.\n\n## Check your own progress\nExplain each concept without looking at your flashcards. Attempt the accompanying ten original multiple-choice questions; review the reasoning after every incorrect answer. Compare your written response with the rubric rather than relying only on an MCQ score.","objectives":["Use accurate literary concepts in close reading","Ground arguments in exact words or stage actions","Evaluate alternative explanations responsibly"],"points":["Lighting cue: A direction about illumination that shapes visibility and mood","Prop: An object handled or placed for dramatic action","Sound cue: A staged noise supports action or atmosphere","Blocking: Actors'' planned positions and movements convey relationships","Symbolic prop: A physical object acquires meaning beyond practical use"],"cards":[{"front":"Define Lighting cue in Stagecraft, Lighting and Symbolic Props.","back":"A direction about illumination that shapes visibility and mood. Original illustration: The lantern dims during the committee debate.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Prop in Stagecraft, Lighting and Symbolic Props.","back":"An object handled or placed for dramatic action. Original illustration: Members pass a folder around the table.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Sound cue in Stagecraft, Lighting and Symbolic Props.","back":"A staged noise supports action or atmosphere. Original illustration: A knock repeats outside the door.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Blocking in Stagecraft, Lighting and Symbolic Props.","back":"Actors'' planned positions and movements convey relationships. Original illustration: Members sit far apart during an argument.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Symbolic prop in Stagecraft, Lighting and Symbolic Props.","back":"A physical object acquires meaning beyond practical use. Original illustration: The fragile lantern mirrors uncertainty about the decision.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"How do you build a convincing interpretation of stagecraft, lighting and symbolic props?","back":"State a focused claim, cite an exact textual detail, explain the effect, and separate solid evidence from plausible inference.","sourceKind":"original-literature-skills","difficulty":"medium"}],"questions":[{"question":"In \"Stagecraft, Lighting and Symbolic Props\" at SSS2, which concept is defined as: A direction about illumination that shapes visibility and mood?","options":[{"id":"A","text":"Prop"},{"id":"B","text":"Sound cue"},{"id":"C","text":"Blocking"},{"id":"D","text":"Lighting cue"}],"answer":"D","explanation":"The concept is Lighting cue. It means A direction about illumination that shapes visibility and mood. An original example is: The lantern dims during the committee debate. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Stagecraft, Lighting and Symbolic Props\": The lantern dims during the committee debate?","options":[{"id":"A","text":"Prop"},{"id":"B","text":"Sound cue"},{"id":"C","text":"Lighting cue"},{"id":"D","text":"Blocking"}],"answer":"C","explanation":"The best answer is Lighting cue because A direction about illumination that shapes visibility and mood. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Stagecraft, Lighting and Symbolic Props\" at SSS2, which concept is defined as: An object handled or placed for dramatic action?","options":[{"id":"A","text":"Lighting cue"},{"id":"B","text":"Prop"},{"id":"C","text":"Sound cue"},{"id":"D","text":"Blocking"}],"answer":"B","explanation":"The concept is Prop. It means An object handled or placed for dramatic action. An original example is: Members pass a folder around the table. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Stagecraft, Lighting and Symbolic Props\": Members pass a folder around the table?","options":[{"id":"A","text":"Prop"},{"id":"B","text":"Lighting cue"},{"id":"C","text":"Sound cue"},{"id":"D","text":"Blocking"}],"answer":"A","explanation":"The best answer is Prop because An object handled or placed for dramatic action. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Stagecraft, Lighting and Symbolic Props\" at SSS2, which concept is defined as: A staged noise supports action or atmosphere?","options":[{"id":"A","text":"Lighting cue"},{"id":"B","text":"Prop"},{"id":"C","text":"Blocking"},{"id":"D","text":"Sound cue"}],"answer":"D","explanation":"The concept is Sound cue. It means A staged noise supports action or atmosphere. An original example is: A knock repeats outside the door. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Stagecraft, Lighting and Symbolic Props\": A knock repeats outside the door?","options":[{"id":"A","text":"Lighting cue"},{"id":"B","text":"Prop"},{"id":"C","text":"Sound cue"},{"id":"D","text":"Blocking"}],"answer":"C","explanation":"The best answer is Sound cue because A staged noise supports action or atmosphere. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Stagecraft, Lighting and Symbolic Props\" at SSS2, which concept is defined as: Actors'' planned positions and movements convey relationships?","options":[{"id":"A","text":"Lighting cue"},{"id":"B","text":"Blocking"},{"id":"C","text":"Prop"},{"id":"D","text":"Sound cue"}],"answer":"B","explanation":"The concept is Blocking. It means Actors'' planned positions and movements convey relationships. An original example is: Members sit far apart during an argument. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Stagecraft, Lighting and Symbolic Props\": Members sit far apart during an argument?","options":[{"id":"A","text":"Blocking"},{"id":"B","text":"Lighting cue"},{"id":"C","text":"Prop"},{"id":"D","text":"Sound cue"}],"answer":"A","explanation":"The best answer is Blocking because Actors'' planned positions and movements convey relationships. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Stagecraft, Lighting and Symbolic Props\" at SSS2, which concept is defined as: A physical object acquires meaning beyond practical use?","options":[{"id":"A","text":"Lighting cue"},{"id":"B","text":"Prop"},{"id":"C","text":"Sound cue"},{"id":"D","text":"Symbolic prop"}],"answer":"D","explanation":"The concept is Symbolic prop. It means A physical object acquires meaning beyond practical use. An original example is: The fragile lantern mirrors uncertainty about the decision. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Stagecraft, Lighting and Symbolic Props\": The fragile lantern mirrors uncertainty about the decision?","options":[{"id":"A","text":"Lighting cue"},{"id":"B","text":"Prop"},{"id":"C","text":"Symbolic prop"},{"id":"D","text":"Sound cue"}],"answer":"C","explanation":"The best answer is Symbolic prop because A physical object acquires meaning beyond practical use. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."}]},{"level":"SSS2","term":3,"seq":5,"name":"Comparing Drama and Poetry for Meaning","intro":"Drama and poetry often share imagery, rhythm and themes, but their evidence operates differently. A dramatic action can reveal motive without explanation; a lyric poem may express uncertainty through an imagined voice. Comparisons should explain both similarity and difference.","passage":"Poem: ''The empty table waited through the rain.'' Play: (An empty table stands at the centre.) TAYO: No one has signed the agreement. AMINA: Then why are the chairs still arranged?","worked":"Both texts use an empty table to suggest absence or unresolved agreement. The poem personifies the table; the play relies on a visible prop and spoken disagreement. Do not claim that one text is more honest merely because it uses dialogue.","concepts":[["Cross-genre image","A similar concrete feature supports meaning in different forms","The empty table appears in verse and on stage"],["Personification","Non-human things receive human actions or feelings","The table waited during the rain"],["Stage symbol","An object on stage represents an additional theme or tension","The table suggests negotiations not yet completed"],["Lyric voice","A poetic speaker communicates attitude or reflection","The poem''s observer describes waiting"],["Comparative claim","A focused statement explains a shared effect and formal difference","Both show absence but the play stages an unresolved dispute"]],"slug":"lit-sss2-t3-comparing-drama-and-poetry-for-meaning","code":"G26LITSSS2T3U5","body":"# Comparing Drama and Poetry for Meaning — SSS2 Literature in English, Third Term\n\n## What you should achieve\nDefine and accurately apply five central literary concepts; use exact evidence from a new passage to support an interpretation; connect technique to its effect; and identify the limits of what the passage permits you to infer.\n\n## Conceptual foundation\nDrama and poetry often share imagery, rhythm and themes, but their evidence operates differently. A dramatic action can reveal motive without explanation; a lyric poem may express uncertainty through an imagined voice. Comparisons should explain both similarity and difference.\n\n**Source note:** The passage and exercises below are original THE GUIDE teaching examples. They are not passages from a historical WAEC, NECO or JAMB paper, and are not represented as quotations from copyrighted prescribed books. Read the school-approved books in full for set-text analysis.\n\n## New worked passage\n> Poem: ''The empty table waited through the rain.'' Play: (An empty table stands at the centre.) TAYO: No one has signed the agreement. AMINA: Then why are the chairs still arranged?\n\n## Interpretation: a model response\nBoth texts use an empty table to suggest absence or unresolved agreement. The poem personifies the table; the play relies on a visible prop and spoken disagreement. Do not claim that one text is more honest merely because it uses dialogue.\n\nRead the passage once for literal information, again to notice diction, structure, dialogue, imagery or action, and a third time to test a thesis against a precise textual clue. A justified interpretation is not simply a personal opinion: it has a claim, evidence and reasoning. Different careful readers may make different claims, but they must account for the same details.\n\n## Five important concepts\n### 1. Cross-genre image\n**Meaning:** A similar concrete feature supports meaning in different forms.\n**Original illustration:** The empty table appears in verse and on stage.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 2. Personification\n**Meaning:** Non-human things receive human actions or feelings.\n**Original illustration:** The table waited during the rain.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 3. Stage symbol\n**Meaning:** An object on stage represents an additional theme or tension.\n**Original illustration:** The table suggests negotiations not yet completed.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 4. Lyric voice\n**Meaning:** A poetic speaker communicates attitude or reflection.\n**Original illustration:** The poem''s observer describes waiting.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 5. Comparative claim\n**Meaning:** A focused statement explains a shared effect and formal difference.\n**Original illustration:** Both show absence but the play stages an unresolved dispute.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n## Method: move from detail to interpretation\n1. **Observe:** Identify who is speaking, what physically happens and which important detail stands out.\n2. **Classify:** Choose one relevant literary term. Do not force every device into the passage.\n3. **Evidence:** Quote a brief original phrase or describe a stage action exactly.\n4. **Reason:** Explain how that evidence affects characterisation, atmosphere, conflict, theme or audience knowledge.\n5. **Qualify:** Distinguish a well-supported reading from an assumption that the passage does not prove.\n\n## Guided application\nReturn to the original passage. State the central conflict or problem in one sentence. Choose two of the five concepts and write a separate evidence-based explanation for each. What does a careful audience know that a character may not know? If this question does not apply, explain why instead of inventing hidden facts.\n\n## Independent practice and rubric\nCreate a short original extract on a related situation, then write a 150–200 word close reading. For a ten-mark analytical paragraph, allocate 2 marks to a clear claim, 2 to accurate terminology, 3 to appropriate textual evidence and explanation, 2 to weighing a plausible alternative or limitation, and 1 to clear organisation. Your score should reward justified reasoning, not memorising one interpretation.\n\n## Common misconceptions\nAn original model excerpt is not a prescribed examination extract. A character''s words are not automatically an objective truth. A stage direction is not spoken dialogue. A metaphor is not literal proof of an event. A detailed explanation should show how the device works instead of merely naming it.\n\n## Check your own progress\nExplain each concept without looking at your flashcards. Attempt the accompanying ten original multiple-choice questions; review the reasoning after every incorrect answer. Compare your written response with the rubric rather than relying only on an MCQ score.","objectives":["Use accurate literary concepts in close reading","Ground arguments in exact words or stage actions","Evaluate alternative explanations responsibly"],"points":["Cross-genre image: A similar concrete feature supports meaning in different forms","Personification: Non-human things receive human actions or feelings","Stage symbol: An object on stage represents an additional theme or tension","Lyric voice: A poetic speaker communicates attitude or reflection","Comparative claim: A focused statement explains a shared effect and formal difference"],"cards":[{"front":"Define Cross-genre image in Comparing Drama and Poetry for Meaning.","back":"A similar concrete feature supports meaning in different forms. Original illustration: The empty table appears in verse and on stage.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Personification in Comparing Drama and Poetry for Meaning.","back":"Non-human things receive human actions or feelings. Original illustration: The table waited during the rain.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Stage symbol in Comparing Drama and Poetry for Meaning.","back":"An object on stage represents an additional theme or tension. Original illustration: The table suggests negotiations not yet completed.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Lyric voice in Comparing Drama and Poetry for Meaning.","back":"A poetic speaker communicates attitude or reflection. Original illustration: The poem''s observer describes waiting.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Comparative claim in Comparing Drama and Poetry for Meaning.","back":"A focused statement explains a shared effect and formal difference. Original illustration: Both show absence but the play stages an unresolved dispute.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"How do you build a convincing interpretation of comparing drama and poetry for meaning?","back":"State a focused claim, cite an exact textual detail, explain the effect, and separate solid evidence from plausible inference.","sourceKind":"original-literature-skills","difficulty":"medium"}],"questions":[{"question":"In \"Comparing Drama and Poetry for Meaning\" at SSS2, which concept is defined as: A similar concrete feature supports meaning in different forms?","options":[{"id":"A","text":"Personification"},{"id":"B","text":"Cross-genre image"},{"id":"C","text":"Stage symbol"},{"id":"D","text":"Lyric voice"}],"answer":"B","explanation":"The concept is Cross-genre image. It means A similar concrete feature supports meaning in different forms. An original example is: The empty table appears in verse and on stage. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Comparing Drama and Poetry for Meaning\": The empty table appears in verse and on stage?","options":[{"id":"A","text":"Cross-genre image"},{"id":"B","text":"Personification"},{"id":"C","text":"Stage symbol"},{"id":"D","text":"Lyric voice"}],"answer":"A","explanation":"The best answer is Cross-genre image because A similar concrete feature supports meaning in different forms. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Comparing Drama and Poetry for Meaning\" at SSS2, which concept is defined as: Non-human things receive human actions or feelings?","options":[{"id":"A","text":"Cross-genre image"},{"id":"B","text":"Stage symbol"},{"id":"C","text":"Lyric voice"},{"id":"D","text":"Personification"}],"answer":"D","explanation":"The concept is Personification. It means Non-human things receive human actions or feelings. An original example is: The table waited during the rain. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Comparing Drama and Poetry for Meaning\": The table waited during the rain?","options":[{"id":"A","text":"Cross-genre image"},{"id":"B","text":"Stage symbol"},{"id":"C","text":"Personification"},{"id":"D","text":"Lyric voice"}],"answer":"C","explanation":"The best answer is Personification because Non-human things receive human actions or feelings. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Comparing Drama and Poetry for Meaning\" at SSS2, which concept is defined as: An object on stage represents an additional theme or tension?","options":[{"id":"A","text":"Cross-genre image"},{"id":"B","text":"Stage symbol"},{"id":"C","text":"Personification"},{"id":"D","text":"Lyric voice"}],"answer":"B","explanation":"The concept is Stage symbol. It means An object on stage represents an additional theme or tension. An original example is: The table suggests negotiations not yet completed. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Comparing Drama and Poetry for Meaning\": The table suggests negotiations not yet completed?","options":[{"id":"A","text":"Stage symbol"},{"id":"B","text":"Cross-genre image"},{"id":"C","text":"Personification"},{"id":"D","text":"Lyric voice"}],"answer":"A","explanation":"The best answer is Stage symbol because An object on stage represents an additional theme or tension. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Comparing Drama and Poetry for Meaning\" at SSS2, which concept is defined as: A poetic speaker communicates attitude or reflection?","options":[{"id":"A","text":"Cross-genre image"},{"id":"B","text":"Personification"},{"id":"C","text":"Stage symbol"},{"id":"D","text":"Lyric voice"}],"answer":"D","explanation":"The concept is Lyric voice. It means A poetic speaker communicates attitude or reflection. An original example is: The poem''s observer describes waiting. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Comparing Drama and Poetry for Meaning\": The poem''s observer describes waiting?","options":[{"id":"A","text":"Cross-genre image"},{"id":"B","text":"Personification"},{"id":"C","text":"Lyric voice"},{"id":"D","text":"Stage symbol"}],"answer":"C","explanation":"The best answer is Lyric voice because A poetic speaker communicates attitude or reflection. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Comparing Drama and Poetry for Meaning\" at SSS2, which concept is defined as: A focused statement explains a shared effect and formal difference?","options":[{"id":"A","text":"Cross-genre image"},{"id":"B","text":"Comparative claim"},{"id":"C","text":"Personification"},{"id":"D","text":"Stage symbol"}],"answer":"B","explanation":"The concept is Comparative claim. It means A focused statement explains a shared effect and formal difference. An original example is: Both show absence but the play stages an unresolved dispute. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Comparing Drama and Poetry for Meaning\": Both show absence but the play stages an unresolved dispute?","options":[{"id":"A","text":"Comparative claim"},{"id":"B","text":"Cross-genre image"},{"id":"C","text":"Personification"},{"id":"D","text":"Stage symbol"}],"answer":"A","explanation":"The best answer is Comparative claim because A focused statement explains a shared effect and formal difference. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."}]},{"level":"SSS3","term":1,"seq":1,"name":"Reading Shakespearean Dramatic Language","intro":"Older English dramatic writing can contain unfamiliar diction and flexible word order. Rather than treating every unusual word as an obstacle, locate the speaker, audience, power relation and immediate choice. This module offers original examples; consult the school-approved 2026–2030 set play separately.","passage":"QUEEN: The tide returns, yet our envoy is not here. ADVISER: Majesty, the harbor sent a lantern signal. QUEEN: A light is not a promise. (She turns from the window.) ADVISER: Shall I summon the council?","worked":"The Queen challenges the adviser''s assumption. The lantern can indicate contact without guaranteeing good news. Addressing her as ''Majesty'' indicates court hierarchy. The lines are original practice, not quotations from Shakespeare.","concepts":[["Elevated diction","Formal or heightened language expresses status or rhetorical weight","The adviser addresses the ruler as Majesty"],["Dramatic address","Speech identifies who is being spoken to and the relation between people","The adviser requests permission from the Queen"],["Rhetorical contrast","Opposed images or propositions sharpen an argument","A light is not a promise rejects false certainty"],["Character authority","A person''s social power shapes who may make decisions","The Queen can summon or refuse the council"],["Scene interpretation","Meaning is built from dialogue and stage action together","Turning from the window signals a change of attention"]],"slug":"lit-sss3-t1-reading-shakespearean-dramatic-language","code":"G26LITSSS3T1U1","body":"# Reading Shakespearean Dramatic Language — SSS3 Literature in English, First Term\n\n## What you should achieve\nDefine and accurately apply five central literary concepts; use exact evidence from a new passage to support an interpretation; connect technique to its effect; and identify the limits of what the passage permits you to infer.\n\n## Conceptual foundation\nOlder English dramatic writing can contain unfamiliar diction and flexible word order. Rather than treating every unusual word as an obstacle, locate the speaker, audience, power relation and immediate choice. This module offers original examples; consult the school-approved 2026–2030 set play separately.\n\n**Source note:** The passage and exercises below are original THE GUIDE teaching examples. They are not passages from a historical WAEC, NECO or JAMB paper, and are not represented as quotations from copyrighted prescribed books. Read the school-approved books in full for set-text analysis.\n\n## New worked passage\n> QUEEN: The tide returns, yet our envoy is not here. ADVISER: Majesty, the harbor sent a lantern signal. QUEEN: A light is not a promise. (She turns from the window.) ADVISER: Shall I summon the council?\n\n## Interpretation: a model response\nThe Queen challenges the adviser''s assumption. The lantern can indicate contact without guaranteeing good news. Addressing her as ''Majesty'' indicates court hierarchy. The lines are original practice, not quotations from Shakespeare.\n\nRead the passage once for literal information, again to notice diction, structure, dialogue, imagery or action, and a third time to test a thesis against a precise textual clue. A justified interpretation is not simply a personal opinion: it has a claim, evidence and reasoning. Different careful readers may make different claims, but they must account for the same details.\n\n## Five important concepts\n### 1. Elevated diction\n**Meaning:** Formal or heightened language expresses status or rhetorical weight.\n**Original illustration:** The adviser addresses the ruler as Majesty.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 2. Dramatic address\n**Meaning:** Speech identifies who is being spoken to and the relation between people.\n**Original illustration:** The adviser requests permission from the Queen.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 3. Rhetorical contrast\n**Meaning:** Opposed images or propositions sharpen an argument.\n**Original illustration:** A light is not a promise rejects false certainty.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 4. Character authority\n**Meaning:** A person''s social power shapes who may make decisions.\n**Original illustration:** The Queen can summon or refuse the council.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 5. Scene interpretation\n**Meaning:** Meaning is built from dialogue and stage action together.\n**Original illustration:** Turning from the window signals a change of attention.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n## Method: move from detail to interpretation\n1. **Observe:** Identify who is speaking, what physically happens and which important detail stands out.\n2. **Classify:** Choose one relevant literary term. Do not force every device into the passage.\n3. **Evidence:** Quote a brief original phrase or describe a stage action exactly.\n4. **Reason:** Explain how that evidence affects characterisation, atmosphere, conflict, theme or audience knowledge.\n5. **Qualify:** Distinguish a well-supported reading from an assumption that the passage does not prove.\n\n## Guided application\nReturn to the original passage. State the central conflict or problem in one sentence. Choose two of the five concepts and write a separate evidence-based explanation for each. What does a careful audience know that a character may not know? If this question does not apply, explain why instead of inventing hidden facts.\n\n## Independent practice and rubric\nCreate a short original extract on a related situation, then write a 150–200 word close reading. For a ten-mark analytical paragraph, allocate 2 marks to a clear claim, 2 to accurate terminology, 3 to appropriate textual evidence and explanation, 2 to weighing a plausible alternative or limitation, and 1 to clear organisation. Your score should reward justified reasoning, not memorising one interpretation.\n\n## Common misconceptions\nAn original model excerpt is not a prescribed examination extract. A character''s words are not automatically an objective truth. A stage direction is not spoken dialogue. A metaphor is not literal proof of an event. A detailed explanation should show how the device works instead of merely naming it.\n\n## Check your own progress\nExplain each concept without looking at your flashcards. Attempt the accompanying ten original multiple-choice questions; review the reasoning after every incorrect answer. Compare your written response with the rubric rather than relying only on an MCQ score.","objectives":["Use accurate literary concepts in close reading","Ground arguments in exact words or stage actions","Evaluate alternative explanations responsibly"],"points":["Elevated diction: Formal or heightened language expresses status or rhetorical weight","Dramatic address: Speech identifies who is being spoken to and the relation between people","Rhetorical contrast: Opposed images or propositions sharpen an argument","Character authority: A person''s social power shapes who may make decisions","Scene interpretation: Meaning is built from dialogue and stage action together"],"cards":[{"front":"Define Elevated diction in Reading Shakespearean Dramatic Language.","back":"Formal or heightened language expresses status or rhetorical weight. Original illustration: The adviser addresses the ruler as Majesty.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Dramatic address in Reading Shakespearean Dramatic Language.","back":"Speech identifies who is being spoken to and the relation between people. Original illustration: The adviser requests permission from the Queen.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Rhetorical contrast in Reading Shakespearean Dramatic Language.","back":"Opposed images or propositions sharpen an argument. Original illustration: A light is not a promise rejects false certainty.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Character authority in Reading Shakespearean Dramatic Language.","back":"A person''s social power shapes who may make decisions. Original illustration: The Queen can summon or refuse the council.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Scene interpretation in Reading Shakespearean Dramatic Language.","back":"Meaning is built from dialogue and stage action together. Original illustration: Turning from the window signals a change of attention.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"How do you build a convincing interpretation of reading shakespearean dramatic language?","back":"State a focused claim, cite an exact textual detail, explain the effect, and separate solid evidence from plausible inference.","sourceKind":"original-literature-skills","difficulty":"medium"}],"questions":[{"question":"In \"Reading Shakespearean Dramatic Language\" at SSS3, which concept is defined as: Formal or heightened language expresses status or rhetorical weight?","options":[{"id":"A","text":"Dramatic address"},{"id":"B","text":"Rhetorical contrast"},{"id":"C","text":"Character authority"},{"id":"D","text":"Elevated diction"}],"answer":"D","explanation":"The concept is Elevated diction. It means Formal or heightened language expresses status or rhetorical weight. An original example is: The adviser addresses the ruler as Majesty. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Reading Shakespearean Dramatic Language\": The adviser addresses the ruler as Majesty?","options":[{"id":"A","text":"Dramatic address"},{"id":"B","text":"Rhetorical contrast"},{"id":"C","text":"Elevated diction"},{"id":"D","text":"Character authority"}],"answer":"C","explanation":"The best answer is Elevated diction because Formal or heightened language expresses status or rhetorical weight. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Reading Shakespearean Dramatic Language\" at SSS3, which concept is defined as: Speech identifies who is being spoken to and the relation between people?","options":[{"id":"A","text":"Elevated diction"},{"id":"B","text":"Dramatic address"},{"id":"C","text":"Rhetorical contrast"},{"id":"D","text":"Character authority"}],"answer":"B","explanation":"The concept is Dramatic address. It means Speech identifies who is being spoken to and the relation between people. An original example is: The adviser requests permission from the Queen. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Reading Shakespearean Dramatic Language\": The adviser requests permission from the Queen?","options":[{"id":"A","text":"Dramatic address"},{"id":"B","text":"Elevated diction"},{"id":"C","text":"Rhetorical contrast"},{"id":"D","text":"Character authority"}],"answer":"A","explanation":"The best answer is Dramatic address because Speech identifies who is being spoken to and the relation between people. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Reading Shakespearean Dramatic Language\" at SSS3, which concept is defined as: Opposed images or propositions sharpen an argument?","options":[{"id":"A","text":"Elevated diction"},{"id":"B","text":"Dramatic address"},{"id":"C","text":"Character authority"},{"id":"D","text":"Rhetorical contrast"}],"answer":"D","explanation":"The concept is Rhetorical contrast. It means Opposed images or propositions sharpen an argument. An original example is: A light is not a promise rejects false certainty. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Reading Shakespearean Dramatic Language\": A light is not a promise rejects false certainty?","options":[{"id":"A","text":"Elevated diction"},{"id":"B","text":"Dramatic address"},{"id":"C","text":"Rhetorical contrast"},{"id":"D","text":"Character authority"}],"answer":"C","explanation":"The best answer is Rhetorical contrast because Opposed images or propositions sharpen an argument. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Reading Shakespearean Dramatic Language\" at SSS3, which concept is defined as: A person''s social power shapes who may make decisions?","options":[{"id":"A","text":"Elevated diction"},{"id":"B","text":"Character authority"},{"id":"C","text":"Dramatic address"},{"id":"D","text":"Rhetorical contrast"}],"answer":"B","explanation":"The concept is Character authority. It means A person''s social power shapes who may make decisions. An original example is: The Queen can summon or refuse the council. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Reading Shakespearean Dramatic Language\": The Queen can summon or refuse the council?","options":[{"id":"A","text":"Character authority"},{"id":"B","text":"Elevated diction"},{"id":"C","text":"Dramatic address"},{"id":"D","text":"Rhetorical contrast"}],"answer":"A","explanation":"The best answer is Character authority because A person''s social power shapes who may make decisions. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Reading Shakespearean Dramatic Language\" at SSS3, which concept is defined as: Meaning is built from dialogue and stage action together?","options":[{"id":"A","text":"Elevated diction"},{"id":"B","text":"Dramatic address"},{"id":"C","text":"Rhetorical contrast"},{"id":"D","text":"Scene interpretation"}],"answer":"D","explanation":"The concept is Scene interpretation. It means Meaning is built from dialogue and stage action together. An original example is: Turning from the window signals a change of attention. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Reading Shakespearean Dramatic Language\": Turning from the window signals a change of attention?","options":[{"id":"A","text":"Elevated diction"},{"id":"B","text":"Dramatic address"},{"id":"C","text":"Scene interpretation"},{"id":"D","text":"Rhetorical contrast"}],"answer":"C","explanation":"The best answer is Scene interpretation because Meaning is built from dialogue and stage action together. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."}]},{"level":"SSS3","term":1,"seq":2,"name":"Tragedy and Competing Loyalties","intro":"Tragedy examines serious choices and their consequences. A protagonist may face tensions between personal affection, political duty and public reputation. Avoid reducing tragedy to ''everyone dies'' or labelling a character''s entire life from one action.","passage":"To protect his younger brother, the magistrate conceals a failed bridge inspection. A second flood damages homes. When the council asks for the report, he must decide whether to admit his part or permit another official to be blamed.","worked":"The core conflict joins personal loyalty to civic responsibility. The concealment produces consequences, but the passage does not state the eventual decision. A tragic reading examines how private choices scale into public harm.","concepts":[["Tragic conflict","A serious clash of values or responsibilities with high consequences","The magistrate must choose between family loyalty and public accountability"],["Hamartia","An error or misjudgment contributing to a tragic downfall","Concealing the bridge report creates danger"],["Reversal","A shift of fortune changes the protagonist''s circumstances","The magistrate''s apparent protection becomes public suspicion"],["Recognition","A character comes to understand a crucial truth","He realises the concealed report worsened the danger"],["Catharsis","A debated account of audience emotional clarification through tragedy","The story invites reflection on pity fear and responsibility"]],"slug":"lit-sss3-t1-tragedy-and-competing-loyalties","code":"G26LITSSS3T1U2","body":"# Tragedy and Competing Loyalties — SSS3 Literature in English, First Term\n\n## What you should achieve\nDefine and accurately apply five central literary concepts; use exact evidence from a new passage to support an interpretation; connect technique to its effect; and identify the limits of what the passage permits you to infer.\n\n## Conceptual foundation\nTragedy examines serious choices and their consequences. A protagonist may face tensions between personal affection, political duty and public reputation. Avoid reducing tragedy to ''everyone dies'' or labelling a character''s entire life from one action.\n\n**Source note:** The passage and exercises below are original THE GUIDE teaching examples. They are not passages from a historical WAEC, NECO or JAMB paper, and are not represented as quotations from copyrighted prescribed books. Read the school-approved books in full for set-text analysis.\n\n## New worked passage\n> To protect his younger brother, the magistrate conceals a failed bridge inspection. A second flood damages homes. When the council asks for the report, he must decide whether to admit his part or permit another official to be blamed.\n\n## Interpretation: a model response\nThe core conflict joins personal loyalty to civic responsibility. The concealment produces consequences, but the passage does not state the eventual decision. A tragic reading examines how private choices scale into public harm.\n\nRead the passage once for literal information, again to notice diction, structure, dialogue, imagery or action, and a third time to test a thesis against a precise textual clue. A justified interpretation is not simply a personal opinion: it has a claim, evidence and reasoning. Different careful readers may make different claims, but they must account for the same details.\n\n## Five important concepts\n### 1. Tragic conflict\n**Meaning:** A serious clash of values or responsibilities with high consequences.\n**Original illustration:** The magistrate must choose between family loyalty and public accountability.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 2. Hamartia\n**Meaning:** An error or misjudgment contributing to a tragic downfall.\n**Original illustration:** Concealing the bridge report creates danger.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 3. Reversal\n**Meaning:** A shift of fortune changes the protagonist''s circumstances.\n**Original illustration:** The magistrate''s apparent protection becomes public suspicion.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 4. Recognition\n**Meaning:** A character comes to understand a crucial truth.\n**Original illustration:** He realises the concealed report worsened the danger.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 5. Catharsis\n**Meaning:** A debated account of audience emotional clarification through tragedy.\n**Original illustration:** The story invites reflection on pity fear and responsibility.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n## Method: move from detail to interpretation\n1. **Observe:** Identify who is speaking, what physically happens and which important detail stands out.\n2. **Classify:** Choose one relevant literary term. Do not force every device into the passage.\n3. **Evidence:** Quote a brief original phrase or describe a stage action exactly.\n4. **Reason:** Explain how that evidence affects characterisation, atmosphere, conflict, theme or audience knowledge.\n5. **Qualify:** Distinguish a well-supported reading from an assumption that the passage does not prove.\n\n## Guided application\nReturn to the original passage. State the central conflict or problem in one sentence. Choose two of the five concepts and write a separate evidence-based explanation for each. What does a careful audience know that a character may not know? If this question does not apply, explain why instead of inventing hidden facts.\n\n## Independent practice and rubric\nCreate a short original extract on a related situation, then write a 150–200 word close reading. For a ten-mark analytical paragraph, allocate 2 marks to a clear claim, 2 to accurate terminology, 3 to appropriate textual evidence and explanation, 2 to weighing a plausible alternative or limitation, and 1 to clear organisation. Your score should reward justified reasoning, not memorising one interpretation.\n\n## Common misconceptions\nAn original model excerpt is not a prescribed examination extract. A character''s words are not automatically an objective truth. A stage direction is not spoken dialogue. A metaphor is not literal proof of an event. A detailed explanation should show how the device works instead of merely naming it.\n\n## Check your own progress\nExplain each concept without looking at your flashcards. Attempt the accompanying ten original multiple-choice questions; review the reasoning after every incorrect answer. Compare your written response with the rubric rather than relying only on an MCQ score.","objectives":["Use accurate literary concepts in close reading","Ground arguments in exact words or stage actions","Evaluate alternative explanations responsibly"],"points":["Tragic conflict: A serious clash of values or responsibilities with high consequences","Hamartia: An error or misjudgment contributing to a tragic downfall","Reversal: A shift of fortune changes the protagonist''s circumstances","Recognition: A character comes to understand a crucial truth","Catharsis: A debated account of audience emotional clarification through tragedy"],"cards":[{"front":"Define Tragic conflict in Tragedy and Competing Loyalties.","back":"A serious clash of values or responsibilities with high consequences. Original illustration: The magistrate must choose between family loyalty and public accountability.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Hamartia in Tragedy and Competing Loyalties.","back":"An error or misjudgment contributing to a tragic downfall. Original illustration: Concealing the bridge report creates danger.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Reversal in Tragedy and Competing Loyalties.","back":"A shift of fortune changes the protagonist''s circumstances. Original illustration: The magistrate''s apparent protection becomes public suspicion.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Recognition in Tragedy and Competing Loyalties.","back":"A character comes to understand a crucial truth. Original illustration: He realises the concealed report worsened the danger.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Catharsis in Tragedy and Competing Loyalties.","back":"A debated account of audience emotional clarification through tragedy. Original illustration: The story invites reflection on pity fear and responsibility.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"How do you build a convincing interpretation of tragedy and competing loyalties?","back":"State a focused claim, cite an exact textual detail, explain the effect, and separate solid evidence from plausible inference.","sourceKind":"original-literature-skills","difficulty":"medium"}],"questions":[{"question":"In \"Tragedy and Competing Loyalties\" at SSS3, which concept is defined as: A serious clash of values or responsibilities with high consequences?","options":[{"id":"A","text":"Hamartia"},{"id":"B","text":"Tragic conflict"},{"id":"C","text":"Reversal"},{"id":"D","text":"Recognition"}],"answer":"B","explanation":"The concept is Tragic conflict. It means A serious clash of values or responsibilities with high consequences. An original example is: The magistrate must choose between family loyalty and public accountability. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Tragedy and Competing Loyalties\": The magistrate must choose between family loyalty and public accountability?","options":[{"id":"A","text":"Tragic conflict"},{"id":"B","text":"Hamartia"},{"id":"C","text":"Reversal"},{"id":"D","text":"Recognition"}],"answer":"A","explanation":"The best answer is Tragic conflict because A serious clash of values or responsibilities with high consequences. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Tragedy and Competing Loyalties\" at SSS3, which concept is defined as: An error or misjudgment contributing to a tragic downfall?","options":[{"id":"A","text":"Tragic conflict"},{"id":"B","text":"Reversal"},{"id":"C","text":"Recognition"},{"id":"D","text":"Hamartia"}],"answer":"D","explanation":"The concept is Hamartia. It means An error or misjudgment contributing to a tragic downfall. An original example is: Concealing the bridge report creates danger. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Tragedy and Competing Loyalties\": Concealing the bridge report creates danger?","options":[{"id":"A","text":"Tragic conflict"},{"id":"B","text":"Reversal"},{"id":"C","text":"Hamartia"},{"id":"D","text":"Recognition"}],"answer":"C","explanation":"The best answer is Hamartia because An error or misjudgment contributing to a tragic downfall. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Tragedy and Competing Loyalties\" at SSS3, which concept is defined as: A shift of fortune changes the protagonist''s circumstances?","options":[{"id":"A","text":"Tragic conflict"},{"id":"B","text":"Reversal"},{"id":"C","text":"Hamartia"},{"id":"D","text":"Recognition"}],"answer":"B","explanation":"The concept is Reversal. It means A shift of fortune changes the protagonist''s circumstances. An original example is: The magistrate''s apparent protection becomes public suspicion. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Tragedy and Competing Loyalties\": The magistrate''s apparent protection becomes public suspicion?","options":[{"id":"A","text":"Reversal"},{"id":"B","text":"Tragic conflict"},{"id":"C","text":"Hamartia"},{"id":"D","text":"Recognition"}],"answer":"A","explanation":"The best answer is Reversal because A shift of fortune changes the protagonist''s circumstances. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Tragedy and Competing Loyalties\" at SSS3, which concept is defined as: A character comes to understand a crucial truth?","options":[{"id":"A","text":"Tragic conflict"},{"id":"B","text":"Hamartia"},{"id":"C","text":"Reversal"},{"id":"D","text":"Recognition"}],"answer":"D","explanation":"The concept is Recognition. It means A character comes to understand a crucial truth. An original example is: He realises the concealed report worsened the danger. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Tragedy and Competing Loyalties\": He realises the concealed report worsened the danger?","options":[{"id":"A","text":"Tragic conflict"},{"id":"B","text":"Hamartia"},{"id":"C","text":"Recognition"},{"id":"D","text":"Reversal"}],"answer":"C","explanation":"The best answer is Recognition because A character comes to understand a crucial truth. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Tragedy and Competing Loyalties\" at SSS3, which concept is defined as: A debated account of audience emotional clarification through tragedy?","options":[{"id":"A","text":"Tragic conflict"},{"id":"B","text":"Catharsis"},{"id":"C","text":"Hamartia"},{"id":"D","text":"Reversal"}],"answer":"B","explanation":"The concept is Catharsis. It means A debated account of audience emotional clarification through tragedy. An original example is: The story invites reflection on pity fear and responsibility. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Tragedy and Competing Loyalties\": The story invites reflection on pity fear and responsibility?","options":[{"id":"A","text":"Catharsis"},{"id":"B","text":"Tragic conflict"},{"id":"C","text":"Hamartia"},{"id":"D","text":"Reversal"}],"answer":"A","explanation":"The best answer is Catharsis because A debated account of audience emotional clarification through tragedy. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."}]},{"level":"SSS3","term":1,"seq":3,"name":"Complex Dramatic Characters","intro":"Strong dramatic analysis examines contradictions within a role. A character can be generous in private and oppressive in public. Identify what each action reveals and weigh evidence across scenes, especially when another character''s accusation may be biased.","passage":"(In private, the governor helps a farmer count his losses.) GOVERNOR: We must find seed for you. (At the council, she interrupts the same farmer.) GOVERNOR: The hearing is closed. He will not speak again.","worked":"The governor shows concern but also exercises exclusionary power. Both actions are in evidence. The dramatic contrast permits criticism without assuming that the earlier concern was entirely fraudulent.","concepts":[["Character complexity","A role possesses motives or qualities that may conflict","The governor helps privately but silences publicly"],["Public persona","The identity a character performs for an audience or institution","At the council she adopts a commanding voice"],["Dramatic contrast","Different actions highlight a contradiction or change","Compassion in private opposes exclusion in public"],["Relationship dynamics","Interactions reveal power trust rivalry or dependence","The farmer''s dependence affects how he answers the governor"],["Character arc","A pattern of change or consistency across many scenes","Later choices would show whether her approach to power changes"]],"slug":"lit-sss3-t1-complex-dramatic-characters","code":"G26LITSSS3T1U3","body":"# Complex Dramatic Characters — SSS3 Literature in English, First Term\n\n## What you should achieve\nDefine and accurately apply five central literary concepts; use exact evidence from a new passage to support an interpretation; connect technique to its effect; and identify the limits of what the passage permits you to infer.\n\n## Conceptual foundation\nStrong dramatic analysis examines contradictions within a role. A character can be generous in private and oppressive in public. Identify what each action reveals and weigh evidence across scenes, especially when another character''s accusation may be biased.\n\n**Source note:** The passage and exercises below are original THE GUIDE teaching examples. They are not passages from a historical WAEC, NECO or JAMB paper, and are not represented as quotations from copyrighted prescribed books. Read the school-approved books in full for set-text analysis.\n\n## New worked passage\n> (In private, the governor helps a farmer count his losses.) GOVERNOR: We must find seed for you. (At the council, she interrupts the same farmer.) GOVERNOR: The hearing is closed. He will not speak again.\n\n## Interpretation: a model response\nThe governor shows concern but also exercises exclusionary power. Both actions are in evidence. The dramatic contrast permits criticism without assuming that the earlier concern was entirely fraudulent.\n\nRead the passage once for literal information, again to notice diction, structure, dialogue, imagery or action, and a third time to test a thesis against a precise textual clue. A justified interpretation is not simply a personal opinion: it has a claim, evidence and reasoning. Different careful readers may make different claims, but they must account for the same details.\n\n## Five important concepts\n### 1. Character complexity\n**Meaning:** A role possesses motives or qualities that may conflict.\n**Original illustration:** The governor helps privately but silences publicly.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 2. Public persona\n**Meaning:** The identity a character performs for an audience or institution.\n**Original illustration:** At the council she adopts a commanding voice.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 3. Dramatic contrast\n**Meaning:** Different actions highlight a contradiction or change.\n**Original illustration:** Compassion in private opposes exclusion in public.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 4. Relationship dynamics\n**Meaning:** Interactions reveal power trust rivalry or dependence.\n**Original illustration:** The farmer''s dependence affects how he answers the governor.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 5. Character arc\n**Meaning:** A pattern of change or consistency across many scenes.\n**Original illustration:** Later choices would show whether her approach to power changes.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n## Method: move from detail to interpretation\n1. **Observe:** Identify who is speaking, what physically happens and which important detail stands out.\n2. **Classify:** Choose one relevant literary term. Do not force every device into the passage.\n3. **Evidence:** Quote a brief original phrase or describe a stage action exactly.\n4. **Reason:** Explain how that evidence affects characterisation, atmosphere, conflict, theme or audience knowledge.\n5. **Qualify:** Distinguish a well-supported reading from an assumption that the passage does not prove.\n\n## Guided application\nReturn to the original passage. State the central conflict or problem in one sentence. Choose two of the five concepts and write a separate evidence-based explanation for each. What does a careful audience know that a character may not know? If this question does not apply, explain why instead of inventing hidden facts.\n\n## Independent practice and rubric\nCreate a short original extract on a related situation, then write a 150–200 word close reading. For a ten-mark analytical paragraph, allocate 2 marks to a clear claim, 2 to accurate terminology, 3 to appropriate textual evidence and explanation, 2 to weighing a plausible alternative or limitation, and 1 to clear organisation. Your score should reward justified reasoning, not memorising one interpretation.\n\n## Common misconceptions\nAn original model excerpt is not a prescribed examination extract. A character''s words are not automatically an objective truth. A stage direction is not spoken dialogue. A metaphor is not literal proof of an event. A detailed explanation should show how the device works instead of merely naming it.\n\n## Check your own progress\nExplain each concept without looking at your flashcards. Attempt the accompanying ten original multiple-choice questions; review the reasoning after every incorrect answer. Compare your written response with the rubric rather than relying only on an MCQ score.","objectives":["Use accurate literary concepts in close reading","Ground arguments in exact words or stage actions","Evaluate alternative explanations responsibly"],"points":["Character complexity: A role possesses motives or qualities that may conflict","Public persona: The identity a character performs for an audience or institution","Dramatic contrast: Different actions highlight a contradiction or change","Relationship dynamics: Interactions reveal power trust rivalry or dependence","Character arc: A pattern of change or consistency across many scenes"],"cards":[{"front":"Define Character complexity in Complex Dramatic Characters.","back":"A role possesses motives or qualities that may conflict. Original illustration: The governor helps privately but silences publicly.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Public persona in Complex Dramatic Characters.","back":"The identity a character performs for an audience or institution. Original illustration: At the council she adopts a commanding voice.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Dramatic contrast in Complex Dramatic Characters.","back":"Different actions highlight a contradiction or change. Original illustration: Compassion in private opposes exclusion in public.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Relationship dynamics in Complex Dramatic Characters.","back":"Interactions reveal power trust rivalry or dependence. Original illustration: The farmer''s dependence affects how he answers the governor.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Character arc in Complex Dramatic Characters.","back":"A pattern of change or consistency across many scenes. Original illustration: Later choices would show whether her approach to power changes.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"How do you build a convincing interpretation of complex dramatic characters?","back":"State a focused claim, cite an exact textual detail, explain the effect, and separate solid evidence from plausible inference.","sourceKind":"original-literature-skills","difficulty":"medium"}],"questions":[{"question":"In \"Complex Dramatic Characters\" at SSS3, which concept is defined as: A role possesses motives or qualities that may conflict?","options":[{"id":"A","text":"Public persona"},{"id":"B","text":"Dramatic contrast"},{"id":"C","text":"Relationship dynamics"},{"id":"D","text":"Character complexity"}],"answer":"D","explanation":"The concept is Character complexity. It means A role possesses motives or qualities that may conflict. An original example is: The governor helps privately but silences publicly. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Complex Dramatic Characters\": The governor helps privately but silences publicly?","options":[{"id":"A","text":"Public persona"},{"id":"B","text":"Dramatic contrast"},{"id":"C","text":"Character complexity"},{"id":"D","text":"Relationship dynamics"}],"answer":"C","explanation":"The best answer is Character complexity because A role possesses motives or qualities that may conflict. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Complex Dramatic Characters\" at SSS3, which concept is defined as: The identity a character performs for an audience or institution?","options":[{"id":"A","text":"Character complexity"},{"id":"B","text":"Public persona"},{"id":"C","text":"Dramatic contrast"},{"id":"D","text":"Relationship dynamics"}],"answer":"B","explanation":"The concept is Public persona. It means The identity a character performs for an audience or institution. An original example is: At the council she adopts a commanding voice. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Complex Dramatic Characters\": At the council she adopts a commanding voice?","options":[{"id":"A","text":"Public persona"},{"id":"B","text":"Character complexity"},{"id":"C","text":"Dramatic contrast"},{"id":"D","text":"Relationship dynamics"}],"answer":"A","explanation":"The best answer is Public persona because The identity a character performs for an audience or institution. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Complex Dramatic Characters\" at SSS3, which concept is defined as: Different actions highlight a contradiction or change?","options":[{"id":"A","text":"Character complexity"},{"id":"B","text":"Public persona"},{"id":"C","text":"Relationship dynamics"},{"id":"D","text":"Dramatic contrast"}],"answer":"D","explanation":"The concept is Dramatic contrast. It means Different actions highlight a contradiction or change. An original example is: Compassion in private opposes exclusion in public. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Complex Dramatic Characters\": Compassion in private opposes exclusion in public?","options":[{"id":"A","text":"Character complexity"},{"id":"B","text":"Public persona"},{"id":"C","text":"Dramatic contrast"},{"id":"D","text":"Relationship dynamics"}],"answer":"C","explanation":"The best answer is Dramatic contrast because Different actions highlight a contradiction or change. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Complex Dramatic Characters\" at SSS3, which concept is defined as: Interactions reveal power trust rivalry or dependence?","options":[{"id":"A","text":"Character complexity"},{"id":"B","text":"Relationship dynamics"},{"id":"C","text":"Public persona"},{"id":"D","text":"Dramatic contrast"}],"answer":"B","explanation":"The concept is Relationship dynamics. It means Interactions reveal power trust rivalry or dependence. An original example is: The farmer''s dependence affects how he answers the governor. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Complex Dramatic Characters\": The farmer''s dependence affects how he answers the governor?","options":[{"id":"A","text":"Relationship dynamics"},{"id":"B","text":"Character complexity"},{"id":"C","text":"Public persona"},{"id":"D","text":"Dramatic contrast"}],"answer":"A","explanation":"The best answer is Relationship dynamics because Interactions reveal power trust rivalry or dependence. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Complex Dramatic Characters\" at SSS3, which concept is defined as: A pattern of change or consistency across many scenes?","options":[{"id":"A","text":"Character complexity"},{"id":"B","text":"Public persona"},{"id":"C","text":"Dramatic contrast"},{"id":"D","text":"Character arc"}],"answer":"D","explanation":"The concept is Character arc. It means A pattern of change or consistency across many scenes. An original example is: Later choices would show whether her approach to power changes. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Complex Dramatic Characters\": Later choices would show whether her approach to power changes?","options":[{"id":"A","text":"Character complexity"},{"id":"B","text":"Public persona"},{"id":"C","text":"Character arc"},{"id":"D","text":"Dramatic contrast"}],"answer":"C","explanation":"The best answer is Character arc because A pattern of change or consistency across many scenes. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."}]},{"level":"SSS3","term":1,"seq":4,"name":"Tragedy Comedy and Tragicomedy","intro":"Genres help describe broad patterns, but a comic exchange can occur inside a serious play. Identify plot trajectory, stakes and thematic handling across the whole text. Don''t classify a work from one laugh or loss.","passage":"At the town council, the clerk mistakes a goat''s vaccination certificate for a building permit. The room laughs. Minutes later officials learn that the unsigned bridge inspection has exposed travellers to danger.","worked":"The mistaken document offers comic relief without erasing the later serious conflict. The extract alone supports a mixture of tonal elements; the overall genre needs evidence from the play''s full structure.","concepts":[["Comedy","Drama frequently explores amusing incongruity social correction or misunderstanding","The clerk''s mistaken certificate produces laughter"],["Tragedy","Drama centres grave conflict suffering or irreversible consequences","Danger from the neglected bridge inspection raises serious stakes"],["Tragicomedy","A work combines substantial comic and tragic qualities","Laughter and public danger coexist in the council scene"],["Comic relief","A humorous moment briefly alters tension within serious action","The mistaken certificate lightens a tense debate"],["Genre judgement","Classification rests on sustained structure and effects rather than one incident","The whole play must be read before declaring tragedy"]],"slug":"lit-sss3-t1-tragedy-comedy-and-tragicomedy","code":"G26LITSSS3T1U4","body":"# Tragedy Comedy and Tragicomedy — SSS3 Literature in English, First Term\n\n## What you should achieve\nDefine and accurately apply five central literary concepts; use exact evidence from a new passage to support an interpretation; connect technique to its effect; and identify the limits of what the passage permits you to infer.\n\n## Conceptual foundation\nGenres help describe broad patterns, but a comic exchange can occur inside a serious play. Identify plot trajectory, stakes and thematic handling across the whole text. Don''t classify a work from one laugh or loss.\n\n**Source note:** The passage and exercises below are original THE GUIDE teaching examples. They are not passages from a historical WAEC, NECO or JAMB paper, and are not represented as quotations from copyrighted prescribed books. Read the school-approved books in full for set-text analysis.\n\n## New worked passage\n> At the town council, the clerk mistakes a goat''s vaccination certificate for a building permit. The room laughs. Minutes later officials learn that the unsigned bridge inspection has exposed travellers to danger.\n\n## Interpretation: a model response\nThe mistaken document offers comic relief without erasing the later serious conflict. The extract alone supports a mixture of tonal elements; the overall genre needs evidence from the play''s full structure.\n\nRead the passage once for literal information, again to notice diction, structure, dialogue, imagery or action, and a third time to test a thesis against a precise textual clue. A justified interpretation is not simply a personal opinion: it has a claim, evidence and reasoning. Different careful readers may make different claims, but they must account for the same details.\n\n## Five important concepts\n### 1. Comedy\n**Meaning:** Drama frequently explores amusing incongruity social correction or misunderstanding.\n**Original illustration:** The clerk''s mistaken certificate produces laughter.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 2. Tragedy\n**Meaning:** Drama centres grave conflict suffering or irreversible consequences.\n**Original illustration:** Danger from the neglected bridge inspection raises serious stakes.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 3. Tragicomedy\n**Meaning:** A work combines substantial comic and tragic qualities.\n**Original illustration:** Laughter and public danger coexist in the council scene.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 4. Comic relief\n**Meaning:** A humorous moment briefly alters tension within serious action.\n**Original illustration:** The mistaken certificate lightens a tense debate.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 5. Genre judgement\n**Meaning:** Classification rests on sustained structure and effects rather than one incident.\n**Original illustration:** The whole play must be read before declaring tragedy.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n## Method: move from detail to interpretation\n1. **Observe:** Identify who is speaking, what physically happens and which important detail stands out.\n2. **Classify:** Choose one relevant literary term. Do not force every device into the passage.\n3. **Evidence:** Quote a brief original phrase or describe a stage action exactly.\n4. **Reason:** Explain how that evidence affects characterisation, atmosphere, conflict, theme or audience knowledge.\n5. **Qualify:** Distinguish a well-supported reading from an assumption that the passage does not prove.\n\n## Guided application\nReturn to the original passage. State the central conflict or problem in one sentence. Choose two of the five concepts and write a separate evidence-based explanation for each. What does a careful audience know that a character may not know? If this question does not apply, explain why instead of inventing hidden facts.\n\n## Independent practice and rubric\nCreate a short original extract on a related situation, then write a 150–200 word close reading. For a ten-mark analytical paragraph, allocate 2 marks to a clear claim, 2 to accurate terminology, 3 to appropriate textual evidence and explanation, 2 to weighing a plausible alternative or limitation, and 1 to clear organisation. Your score should reward justified reasoning, not memorising one interpretation.\n\n## Common misconceptions\nAn original model excerpt is not a prescribed examination extract. A character''s words are not automatically an objective truth. A stage direction is not spoken dialogue. A metaphor is not literal proof of an event. A detailed explanation should show how the device works instead of merely naming it.\n\n## Check your own progress\nExplain each concept without looking at your flashcards. Attempt the accompanying ten original multiple-choice questions; review the reasoning after every incorrect answer. Compare your written response with the rubric rather than relying only on an MCQ score.","objectives":["Use accurate literary concepts in close reading","Ground arguments in exact words or stage actions","Evaluate alternative explanations responsibly"],"points":["Comedy: Drama frequently explores amusing incongruity social correction or misunderstanding","Tragedy: Drama centres grave conflict suffering or irreversible consequences","Tragicomedy: A work combines substantial comic and tragic qualities","Comic relief: A humorous moment briefly alters tension within serious action","Genre judgement: Classification rests on sustained structure and effects rather than one incident"],"cards":[{"front":"Define Comedy in Tragedy Comedy and Tragicomedy.","back":"Drama frequently explores amusing incongruity social correction or misunderstanding. Original illustration: The clerk''s mistaken certificate produces laughter.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Tragedy in Tragedy Comedy and Tragicomedy.","back":"Drama centres grave conflict suffering or irreversible consequences. Original illustration: Danger from the neglected bridge inspection raises serious stakes.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Tragicomedy in Tragedy Comedy and Tragicomedy.","back":"A work combines substantial comic and tragic qualities. Original illustration: Laughter and public danger coexist in the council scene.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Comic relief in Tragedy Comedy and Tragicomedy.","back":"A humorous moment briefly alters tension within serious action. Original illustration: The mistaken certificate lightens a tense debate.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Genre judgement in Tragedy Comedy and Tragicomedy.","back":"Classification rests on sustained structure and effects rather than one incident. Original illustration: The whole play must be read before declaring tragedy.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"How do you build a convincing interpretation of tragedy comedy and tragicomedy?","back":"State a focused claim, cite an exact textual detail, explain the effect, and separate solid evidence from plausible inference.","sourceKind":"original-literature-skills","difficulty":"medium"}],"questions":[{"question":"In \"Tragedy Comedy and Tragicomedy\" at SSS3, which concept is defined as: Drama frequently explores amusing incongruity social correction or misunderstanding?","options":[{"id":"A","text":"Tragedy"},{"id":"B","text":"Comedy"},{"id":"C","text":"Tragicomedy"},{"id":"D","text":"Comic relief"}],"answer":"B","explanation":"The concept is Comedy. It means Drama frequently explores amusing incongruity social correction or misunderstanding. An original example is: The clerk''s mistaken certificate produces laughter. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Tragedy Comedy and Tragicomedy\": The clerk''s mistaken certificate produces laughter?","options":[{"id":"A","text":"Comedy"},{"id":"B","text":"Tragedy"},{"id":"C","text":"Tragicomedy"},{"id":"D","text":"Comic relief"}],"answer":"A","explanation":"The best answer is Comedy because Drama frequently explores amusing incongruity social correction or misunderstanding. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Tragedy Comedy and Tragicomedy\" at SSS3, which concept is defined as: Drama centres grave conflict suffering or irreversible consequences?","options":[{"id":"A","text":"Comedy"},{"id":"B","text":"Tragicomedy"},{"id":"C","text":"Comic relief"},{"id":"D","text":"Tragedy"}],"answer":"D","explanation":"The concept is Tragedy. It means Drama centres grave conflict suffering or irreversible consequences. An original example is: Danger from the neglected bridge inspection raises serious stakes. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Tragedy Comedy and Tragicomedy\": Danger from the neglected bridge inspection raises serious stakes?","options":[{"id":"A","text":"Comedy"},{"id":"B","text":"Tragicomedy"},{"id":"C","text":"Tragedy"},{"id":"D","text":"Comic relief"}],"answer":"C","explanation":"The best answer is Tragedy because Drama centres grave conflict suffering or irreversible consequences. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Tragedy Comedy and Tragicomedy\" at SSS3, which concept is defined as: A work combines substantial comic and tragic qualities?","options":[{"id":"A","text":"Comedy"},{"id":"B","text":"Tragicomedy"},{"id":"C","text":"Tragedy"},{"id":"D","text":"Comic relief"}],"answer":"B","explanation":"The concept is Tragicomedy. It means A work combines substantial comic and tragic qualities. An original example is: Laughter and public danger coexist in the council scene. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Tragedy Comedy and Tragicomedy\": Laughter and public danger coexist in the council scene?","options":[{"id":"A","text":"Tragicomedy"},{"id":"B","text":"Comedy"},{"id":"C","text":"Tragedy"},{"id":"D","text":"Comic relief"}],"answer":"A","explanation":"The best answer is Tragicomedy because A work combines substantial comic and tragic qualities. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Tragedy Comedy and Tragicomedy\" at SSS3, which concept is defined as: A humorous moment briefly alters tension within serious action?","options":[{"id":"A","text":"Comedy"},{"id":"B","text":"Tragedy"},{"id":"C","text":"Tragicomedy"},{"id":"D","text":"Comic relief"}],"answer":"D","explanation":"The concept is Comic relief. It means A humorous moment briefly alters tension within serious action. An original example is: The mistaken certificate lightens a tense debate. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Tragedy Comedy and Tragicomedy\": The mistaken certificate lightens a tense debate?","options":[{"id":"A","text":"Comedy"},{"id":"B","text":"Tragedy"},{"id":"C","text":"Comic relief"},{"id":"D","text":"Tragicomedy"}],"answer":"C","explanation":"The best answer is Comic relief because A humorous moment briefly alters tension within serious action. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Tragedy Comedy and Tragicomedy\" at SSS3, which concept is defined as: Classification rests on sustained structure and effects rather than one incident?","options":[{"id":"A","text":"Comedy"},{"id":"B","text":"Genre judgement"},{"id":"C","text":"Tragedy"},{"id":"D","text":"Tragicomedy"}],"answer":"B","explanation":"The concept is Genre judgement. It means Classification rests on sustained structure and effects rather than one incident. An original example is: The whole play must be read before declaring tragedy. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Tragedy Comedy and Tragicomedy\": The whole play must be read before declaring tragedy?","options":[{"id":"A","text":"Genre judgement"},{"id":"B","text":"Comedy"},{"id":"C","text":"Tragedy"},{"id":"D","text":"Tragicomedy"}],"answer":"A","explanation":"The best answer is Genre judgement because Classification rests on sustained structure and effects rather than one incident. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."}]},{"level":"SSS3","term":1,"seq":5,"name":"Timed Drama Essay Techniques","intro":"Under exam conditions, a precise plan improves an answer more than an oversized plot summary. Students must distinguish the examination prompt''s command word, choose relevant scenes, present evidence and build a reasoned judgement. Use only confirmed quotations from the assigned text.","passage":"Essay prompt on this original scene: ''The committee has two doors. Everyone may speak, says the chair. One door is locked; the other leads through a private office. When the cleaner asks for entry, the clerk points to a sign: MEMBERS ONLY.'' Explain how the staging represents exclusion.","worked":"A thesis can argue that the chair''s inclusive words conflict with access restrictions. Evidence is the locked entrance and members-only sign. The analysis should connect words, stage design and unequal access rather than retelling the order of entrances.","concepts":[["Command word","A prompt verb signals the task expected in an essay","Discuss asks for developed examination of a claim"],["Thesis","A focused arguable position directly answers the question","The committee''s language hides practical exclusion"],["Scene evidence","A precise dialogue or action supports the line of argument","The sign limits entry to members"],["Analysis","Explanation connects form and evidence with significance","A locked door exposes the gap between words and practice"],["Time allocation","An exam plan balances reading outlining writing and checking","The student reserves minutes for a two-point plan and conclusion"]],"slug":"lit-sss3-t1-timed-drama-essay-techniques","code":"G26LITSSS3T1U5","body":"# Timed Drama Essay Techniques — SSS3 Literature in English, First Term\n\n## What you should achieve\nDefine and accurately apply five central literary concepts; use exact evidence from a new passage to support an interpretation; connect technique to its effect; and identify the limits of what the passage permits you to infer.\n\n## Conceptual foundation\nUnder exam conditions, a precise plan improves an answer more than an oversized plot summary. Students must distinguish the examination prompt''s command word, choose relevant scenes, present evidence and build a reasoned judgement. Use only confirmed quotations from the assigned text.\n\n**Source note:** The passage and exercises below are original THE GUIDE teaching examples. They are not passages from a historical WAEC, NECO or JAMB paper, and are not represented as quotations from copyrighted prescribed books. Read the school-approved books in full for set-text analysis.\n\n## New worked passage\n> Essay prompt on this original scene: ''The committee has two doors. Everyone may speak, says the chair. One door is locked; the other leads through a private office. When the cleaner asks for entry, the clerk points to a sign: MEMBERS ONLY.'' Explain how the staging represents exclusion.\n\n## Interpretation: a model response\nA thesis can argue that the chair''s inclusive words conflict with access restrictions. Evidence is the locked entrance and members-only sign. The analysis should connect words, stage design and unequal access rather than retelling the order of entrances.\n\nRead the passage once for literal information, again to notice diction, structure, dialogue, imagery or action, and a third time to test a thesis against a precise textual clue. A justified interpretation is not simply a personal opinion: it has a claim, evidence and reasoning. Different careful readers may make different claims, but they must account for the same details.\n\n## Five important concepts\n### 1. Command word\n**Meaning:** A prompt verb signals the task expected in an essay.\n**Original illustration:** Discuss asks for developed examination of a claim.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 2. Thesis\n**Meaning:** A focused arguable position directly answers the question.\n**Original illustration:** The committee''s language hides practical exclusion.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 3. Scene evidence\n**Meaning:** A precise dialogue or action supports the line of argument.\n**Original illustration:** The sign limits entry to members.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 4. Analysis\n**Meaning:** Explanation connects form and evidence with significance.\n**Original illustration:** A locked door exposes the gap between words and practice.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 5. Time allocation\n**Meaning:** An exam plan balances reading outlining writing and checking.\n**Original illustration:** The student reserves minutes for a two-point plan and conclusion.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n## Method: move from detail to interpretation\n1. **Observe:** Identify who is speaking, what physically happens and which important detail stands out.\n2. **Classify:** Choose one relevant literary term. Do not force every device into the passage.\n3. **Evidence:** Quote a brief original phrase or describe a stage action exactly.\n4. **Reason:** Explain how that evidence affects characterisation, atmosphere, conflict, theme or audience knowledge.\n5. **Qualify:** Distinguish a well-supported reading from an assumption that the passage does not prove.\n\n## Guided application\nReturn to the original passage. State the central conflict or problem in one sentence. Choose two of the five concepts and write a separate evidence-based explanation for each. What does a careful audience know that a character may not know? If this question does not apply, explain why instead of inventing hidden facts.\n\n## Independent practice and rubric\nCreate a short original extract on a related situation, then write a 150–200 word close reading. For a ten-mark analytical paragraph, allocate 2 marks to a clear claim, 2 to accurate terminology, 3 to appropriate textual evidence and explanation, 2 to weighing a plausible alternative or limitation, and 1 to clear organisation. Your score should reward justified reasoning, not memorising one interpretation.\n\n## Common misconceptions\nAn original model excerpt is not a prescribed examination extract. A character''s words are not automatically an objective truth. A stage direction is not spoken dialogue. A metaphor is not literal proof of an event. A detailed explanation should show how the device works instead of merely naming it.\n\n## Check your own progress\nExplain each concept without looking at your flashcards. Attempt the accompanying ten original multiple-choice questions; review the reasoning after every incorrect answer. Compare your written response with the rubric rather than relying only on an MCQ score.","objectives":["Use accurate literary concepts in close reading","Ground arguments in exact words or stage actions","Evaluate alternative explanations responsibly"],"points":["Command word: A prompt verb signals the task expected in an essay","Thesis: A focused arguable position directly answers the question","Scene evidence: A precise dialogue or action supports the line of argument","Analysis: Explanation connects form and evidence with significance","Time allocation: An exam plan balances reading outlining writing and checking"],"cards":[{"front":"Define Command word in Timed Drama Essay Techniques.","back":"A prompt verb signals the task expected in an essay. Original illustration: Discuss asks for developed examination of a claim.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Thesis in Timed Drama Essay Techniques.","back":"A focused arguable position directly answers the question. Original illustration: The committee''s language hides practical exclusion.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Scene evidence in Timed Drama Essay Techniques.","back":"A precise dialogue or action supports the line of argument. Original illustration: The sign limits entry to members.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Analysis in Timed Drama Essay Techniques.","back":"Explanation connects form and evidence with significance. Original illustration: A locked door exposes the gap between words and practice.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Time allocation in Timed Drama Essay Techniques.","back":"An exam plan balances reading outlining writing and checking. Original illustration: The student reserves minutes for a two-point plan and conclusion.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"How do you build a convincing interpretation of timed drama essay techniques?","back":"State a focused claim, cite an exact textual detail, explain the effect, and separate solid evidence from plausible inference.","sourceKind":"original-literature-skills","difficulty":"medium"}],"questions":[{"question":"In \"Timed Drama Essay Techniques\" at SSS3, which concept is defined as: A prompt verb signals the task expected in an essay?","options":[{"id":"A","text":"Thesis"},{"id":"B","text":"Scene evidence"},{"id":"C","text":"Analysis"},{"id":"D","text":"Command word"}],"answer":"D","explanation":"The concept is Command word. It means A prompt verb signals the task expected in an essay. An original example is: Discuss asks for developed examination of a claim. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Timed Drama Essay Techniques\": Discuss asks for developed examination of a claim?","options":[{"id":"A","text":"Thesis"},{"id":"B","text":"Scene evidence"},{"id":"C","text":"Command word"},{"id":"D","text":"Analysis"}],"answer":"C","explanation":"The best answer is Command word because A prompt verb signals the task expected in an essay. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Timed Drama Essay Techniques\" at SSS3, which concept is defined as: A focused arguable position directly answers the question?","options":[{"id":"A","text":"Command word"},{"id":"B","text":"Thesis"},{"id":"C","text":"Scene evidence"},{"id":"D","text":"Analysis"}],"answer":"B","explanation":"The concept is Thesis. It means A focused arguable position directly answers the question. An original example is: The committee''s language hides practical exclusion. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Timed Drama Essay Techniques\": The committee''s language hides practical exclusion?","options":[{"id":"A","text":"Thesis"},{"id":"B","text":"Command word"},{"id":"C","text":"Scene evidence"},{"id":"D","text":"Analysis"}],"answer":"A","explanation":"The best answer is Thesis because A focused arguable position directly answers the question. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Timed Drama Essay Techniques\" at SSS3, which concept is defined as: A precise dialogue or action supports the line of argument?","options":[{"id":"A","text":"Command word"},{"id":"B","text":"Thesis"},{"id":"C","text":"Analysis"},{"id":"D","text":"Scene evidence"}],"answer":"D","explanation":"The concept is Scene evidence. It means A precise dialogue or action supports the line of argument. An original example is: The sign limits entry to members. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Timed Drama Essay Techniques\": The sign limits entry to members?","options":[{"id":"A","text":"Command word"},{"id":"B","text":"Thesis"},{"id":"C","text":"Scene evidence"},{"id":"D","text":"Analysis"}],"answer":"C","explanation":"The best answer is Scene evidence because A precise dialogue or action supports the line of argument. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Timed Drama Essay Techniques\" at SSS3, which concept is defined as: Explanation connects form and evidence with significance?","options":[{"id":"A","text":"Command word"},{"id":"B","text":"Analysis"},{"id":"C","text":"Thesis"},{"id":"D","text":"Scene evidence"}],"answer":"B","explanation":"The concept is Analysis. It means Explanation connects form and evidence with significance. An original example is: A locked door exposes the gap between words and practice. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Timed Drama Essay Techniques\": A locked door exposes the gap between words and practice?","options":[{"id":"A","text":"Analysis"},{"id":"B","text":"Command word"},{"id":"C","text":"Thesis"},{"id":"D","text":"Scene evidence"}],"answer":"A","explanation":"The best answer is Analysis because Explanation connects form and evidence with significance. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Timed Drama Essay Techniques\" at SSS3, which concept is defined as: An exam plan balances reading outlining writing and checking?","options":[{"id":"A","text":"Command word"},{"id":"B","text":"Thesis"},{"id":"C","text":"Scene evidence"},{"id":"D","text":"Time allocation"}],"answer":"D","explanation":"The concept is Time allocation. It means An exam plan balances reading outlining writing and checking. An original example is: The student reserves minutes for a two-point plan and conclusion. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Timed Drama Essay Techniques\": The student reserves minutes for a two-point plan and conclusion?","options":[{"id":"A","text":"Command word"},{"id":"B","text":"Thesis"},{"id":"C","text":"Time allocation"},{"id":"D","text":"Scene evidence"}],"answer":"C","explanation":"The best answer is Time allocation because An exam plan balances reading outlining writing and checking. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."}]},{"level":"SSS3","term":2,"seq":1,"name":"Framing Narratives and Storytelling Roles","intro":"A frame narrative contains a second story told inside an outer story. Narrators can disagree or reinterpret events after years have passed. Compare the two telling situations before claiming that an embedded account is wholly factual.","passage":"At the reunion, an elderly teacher opens a box of letters. She reads a student''s account of the first flood, then tells the former pupils that her own memory differs. The chapter switches back to the student''s written account.","worked":"The reunion is an outer frame; the letter supplies an embedded narrative. The teacher''s disagreement creates a question of testimony rather than proof that either source is lying.","concepts":[["Frame narrative","An outer storytelling situation encloses another narrated account","The reunion contains the student''s letter"],["Embedded story","A story presented inside another narrative","The letter describes the earlier flood"],["Narrator reliability","A reader evaluates omissions limits and bias in a telling","Teacher and student remember the event differently"],["Temporal distance","Years between event and retelling shape memory or perspective","The teacher reflects long after the flood"],["Narrative authority","The apparent right to present a version as credible is tested","The teacher''s position does not guarantee accurate recall"]],"slug":"lit-sss3-t2-framing-narratives-and-storytelling-roles","code":"G26LITSSS3T2U1","body":"# Framing Narratives and Storytelling Roles — SSS3 Literature in English, Second Term\n\n## What you should achieve\nDefine and accurately apply five central literary concepts; use exact evidence from a new passage to support an interpretation; connect technique to its effect; and identify the limits of what the passage permits you to infer.\n\n## Conceptual foundation\nA frame narrative contains a second story told inside an outer story. Narrators can disagree or reinterpret events after years have passed. Compare the two telling situations before claiming that an embedded account is wholly factual.\n\n**Source note:** The passage and exercises below are original THE GUIDE teaching examples. They are not passages from a historical WAEC, NECO or JAMB paper, and are not represented as quotations from copyrighted prescribed books. Read the school-approved books in full for set-text analysis.\n\n## New worked passage\n> At the reunion, an elderly teacher opens a box of letters. She reads a student''s account of the first flood, then tells the former pupils that her own memory differs. The chapter switches back to the student''s written account.\n\n## Interpretation: a model response\nThe reunion is an outer frame; the letter supplies an embedded narrative. The teacher''s disagreement creates a question of testimony rather than proof that either source is lying.\n\nRead the passage once for literal information, again to notice diction, structure, dialogue, imagery or action, and a third time to test a thesis against a precise textual clue. A justified interpretation is not simply a personal opinion: it has a claim, evidence and reasoning. Different careful readers may make different claims, but they must account for the same details.\n\n## Five important concepts\n### 1. Frame narrative\n**Meaning:** An outer storytelling situation encloses another narrated account.\n**Original illustration:** The reunion contains the student''s letter.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 2. Embedded story\n**Meaning:** A story presented inside another narrative.\n**Original illustration:** The letter describes the earlier flood.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 3. Narrator reliability\n**Meaning:** A reader evaluates omissions limits and bias in a telling.\n**Original illustration:** Teacher and student remember the event differently.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 4. Temporal distance\n**Meaning:** Years between event and retelling shape memory or perspective.\n**Original illustration:** The teacher reflects long after the flood.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 5. Narrative authority\n**Meaning:** The apparent right to present a version as credible is tested.\n**Original illustration:** The teacher''s position does not guarantee accurate recall.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n## Method: move from detail to interpretation\n1. **Observe:** Identify who is speaking, what physically happens and which important detail stands out.\n2. **Classify:** Choose one relevant literary term. Do not force every device into the passage.\n3. **Evidence:** Quote a brief original phrase or describe a stage action exactly.\n4. **Reason:** Explain how that evidence affects characterisation, atmosphere, conflict, theme or audience knowledge.\n5. **Qualify:** Distinguish a well-supported reading from an assumption that the passage does not prove.\n\n## Guided application\nReturn to the original passage. State the central conflict or problem in one sentence. Choose two of the five concepts and write a separate evidence-based explanation for each. What does a careful audience know that a character may not know? If this question does not apply, explain why instead of inventing hidden facts.\n\n## Independent practice and rubric\nCreate a short original extract on a related situation, then write a 150–200 word close reading. For a ten-mark analytical paragraph, allocate 2 marks to a clear claim, 2 to accurate terminology, 3 to appropriate textual evidence and explanation, 2 to weighing a plausible alternative or limitation, and 1 to clear organisation. Your score should reward justified reasoning, not memorising one interpretation.\n\n## Common misconceptions\nAn original model excerpt is not a prescribed examination extract. A character''s words are not automatically an objective truth. A stage direction is not spoken dialogue. A metaphor is not literal proof of an event. A detailed explanation should show how the device works instead of merely naming it.\n\n## Check your own progress\nExplain each concept without looking at your flashcards. Attempt the accompanying ten original multiple-choice questions; review the reasoning after every incorrect answer. Compare your written response with the rubric rather than relying only on an MCQ score.","objectives":["Use accurate literary concepts in close reading","Ground arguments in exact words or stage actions","Evaluate alternative explanations responsibly"],"points":["Frame narrative: An outer storytelling situation encloses another narrated account","Embedded story: A story presented inside another narrative","Narrator reliability: A reader evaluates omissions limits and bias in a telling","Temporal distance: Years between event and retelling shape memory or perspective","Narrative authority: The apparent right to present a version as credible is tested"],"cards":[{"front":"Define Frame narrative in Framing Narratives and Storytelling Roles.","back":"An outer storytelling situation encloses another narrated account. Original illustration: The reunion contains the student''s letter.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Embedded story in Framing Narratives and Storytelling Roles.","back":"A story presented inside another narrative. Original illustration: The letter describes the earlier flood.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Narrator reliability in Framing Narratives and Storytelling Roles.","back":"A reader evaluates omissions limits and bias in a telling. Original illustration: Teacher and student remember the event differently.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Temporal distance in Framing Narratives and Storytelling Roles.","back":"Years between event and retelling shape memory or perspective. Original illustration: The teacher reflects long after the flood.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Narrative authority in Framing Narratives and Storytelling Roles.","back":"The apparent right to present a version as credible is tested. Original illustration: The teacher''s position does not guarantee accurate recall.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"How do you build a convincing interpretation of framing narratives and storytelling roles?","back":"State a focused claim, cite an exact textual detail, explain the effect, and separate solid evidence from plausible inference.","sourceKind":"original-literature-skills","difficulty":"medium"}],"questions":[{"question":"In \"Framing Narratives and Storytelling Roles\" at SSS3, which concept is defined as: An outer storytelling situation encloses another narrated account?","options":[{"id":"A","text":"Embedded story"},{"id":"B","text":"Frame narrative"},{"id":"C","text":"Narrator reliability"},{"id":"D","text":"Temporal distance"}],"answer":"B","explanation":"The concept is Frame narrative. It means An outer storytelling situation encloses another narrated account. An original example is: The reunion contains the student''s letter. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Framing Narratives and Storytelling Roles\": The reunion contains the student''s letter?","options":[{"id":"A","text":"Frame narrative"},{"id":"B","text":"Embedded story"},{"id":"C","text":"Narrator reliability"},{"id":"D","text":"Temporal distance"}],"answer":"A","explanation":"The best answer is Frame narrative because An outer storytelling situation encloses another narrated account. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Framing Narratives and Storytelling Roles\" at SSS3, which concept is defined as: A story presented inside another narrative?","options":[{"id":"A","text":"Frame narrative"},{"id":"B","text":"Narrator reliability"},{"id":"C","text":"Temporal distance"},{"id":"D","text":"Embedded story"}],"answer":"D","explanation":"The concept is Embedded story. It means A story presented inside another narrative. An original example is: The letter describes the earlier flood. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Framing Narratives and Storytelling Roles\": The letter describes the earlier flood?","options":[{"id":"A","text":"Frame narrative"},{"id":"B","text":"Narrator reliability"},{"id":"C","text":"Embedded story"},{"id":"D","text":"Temporal distance"}],"answer":"C","explanation":"The best answer is Embedded story because A story presented inside another narrative. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Framing Narratives and Storytelling Roles\" at SSS3, which concept is defined as: A reader evaluates omissions limits and bias in a telling?","options":[{"id":"A","text":"Frame narrative"},{"id":"B","text":"Narrator reliability"},{"id":"C","text":"Embedded story"},{"id":"D","text":"Temporal distance"}],"answer":"B","explanation":"The concept is Narrator reliability. It means A reader evaluates omissions limits and bias in a telling. An original example is: Teacher and student remember the event differently. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Framing Narratives and Storytelling Roles\": Teacher and student remember the event differently?","options":[{"id":"A","text":"Narrator reliability"},{"id":"B","text":"Frame narrative"},{"id":"C","text":"Embedded story"},{"id":"D","text":"Temporal distance"}],"answer":"A","explanation":"The best answer is Narrator reliability because A reader evaluates omissions limits and bias in a telling. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Framing Narratives and Storytelling Roles\" at SSS3, which concept is defined as: Years between event and retelling shape memory or perspective?","options":[{"id":"A","text":"Frame narrative"},{"id":"B","text":"Embedded story"},{"id":"C","text":"Narrator reliability"},{"id":"D","text":"Temporal distance"}],"answer":"D","explanation":"The concept is Temporal distance. It means Years between event and retelling shape memory or perspective. An original example is: The teacher reflects long after the flood. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Framing Narratives and Storytelling Roles\": The teacher reflects long after the flood?","options":[{"id":"A","text":"Frame narrative"},{"id":"B","text":"Embedded story"},{"id":"C","text":"Temporal distance"},{"id":"D","text":"Narrator reliability"}],"answer":"C","explanation":"The best answer is Temporal distance because Years between event and retelling shape memory or perspective. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Framing Narratives and Storytelling Roles\" at SSS3, which concept is defined as: The apparent right to present a version as credible is tested?","options":[{"id":"A","text":"Frame narrative"},{"id":"B","text":"Narrative authority"},{"id":"C","text":"Embedded story"},{"id":"D","text":"Narrator reliability"}],"answer":"B","explanation":"The concept is Narrative authority. It means The apparent right to present a version as credible is tested. An original example is: The teacher''s position does not guarantee accurate recall. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Framing Narratives and Storytelling Roles\": The teacher''s position does not guarantee accurate recall?","options":[{"id":"A","text":"Narrative authority"},{"id":"B","text":"Frame narrative"},{"id":"C","text":"Embedded story"},{"id":"D","text":"Narrator reliability"}],"answer":"A","explanation":"The best answer is Narrative authority because The apparent right to present a version as credible is tested. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."}]},{"level":"SSS3","term":2,"seq":2,"name":"Prose, Institutions and Social Critique","intro":"Prose often reveals institutions by showing their consequences for ordinary people. A responsible analysis identifies rules, the people affected and any alternative agency available. It does not leap from one fictional incident to claims about every real public service.","passage":"Residents queue before sunrise for flood assistance. A notice says applications close at noon, but the clerk''s office opens at eleven. Bola arrives with all required documents and leaves after an unexplained computer outage; another resident suggests writing a joint appeal.","worked":"The mismatch between deadline and opening time creates an access problem. Bola''s preparation and a proposed appeal complicate the story: individuals act responsibly despite procedural obstacles. The text does not identify who caused the outage.","concepts":[["Institutional critique","A narrative questions the fairness or consequences of organised rules","An application deadline conflicts with office hours"],["Bureaucratic obstacle","Administrative procedures delay or block a goal","A system outage interrupts the application"],["Collective action","Several characters work together to influence an outcome","Residents propose a shared appeal"],["Focalisation","Events are presented through a particular character''s knowledge","The scene closely follows Bola''s experience"],["Ethical inference","A conclusion about fairness follows from specific evidence","Hours and deadlines suggest unequal opportunity"]],"slug":"lit-sss3-t2-prose-institutions-and-social-critique","code":"G26LITSSS3T2U2","body":"# Prose, Institutions and Social Critique — SSS3 Literature in English, Second Term\n\n## What you should achieve\nDefine and accurately apply five central literary concepts; use exact evidence from a new passage to support an interpretation; connect technique to its effect; and identify the limits of what the passage permits you to infer.\n\n## Conceptual foundation\nProse often reveals institutions by showing their consequences for ordinary people. A responsible analysis identifies rules, the people affected and any alternative agency available. It does not leap from one fictional incident to claims about every real public service.\n\n**Source note:** The passage and exercises below are original THE GUIDE teaching examples. They are not passages from a historical WAEC, NECO or JAMB paper, and are not represented as quotations from copyrighted prescribed books. Read the school-approved books in full for set-text analysis.\n\n## New worked passage\n> Residents queue before sunrise for flood assistance. A notice says applications close at noon, but the clerk''s office opens at eleven. Bola arrives with all required documents and leaves after an unexplained computer outage; another resident suggests writing a joint appeal.\n\n## Interpretation: a model response\nThe mismatch between deadline and opening time creates an access problem. Bola''s preparation and a proposed appeal complicate the story: individuals act responsibly despite procedural obstacles. The text does not identify who caused the outage.\n\nRead the passage once for literal information, again to notice diction, structure, dialogue, imagery or action, and a third time to test a thesis against a precise textual clue. A justified interpretation is not simply a personal opinion: it has a claim, evidence and reasoning. Different careful readers may make different claims, but they must account for the same details.\n\n## Five important concepts\n### 1. Institutional critique\n**Meaning:** A narrative questions the fairness or consequences of organised rules.\n**Original illustration:** An application deadline conflicts with office hours.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 2. Bureaucratic obstacle\n**Meaning:** Administrative procedures delay or block a goal.\n**Original illustration:** A system outage interrupts the application.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 3. Collective action\n**Meaning:** Several characters work together to influence an outcome.\n**Original illustration:** Residents propose a shared appeal.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 4. Focalisation\n**Meaning:** Events are presented through a particular character''s knowledge.\n**Original illustration:** The scene closely follows Bola''s experience.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 5. Ethical inference\n**Meaning:** A conclusion about fairness follows from specific evidence.\n**Original illustration:** Hours and deadlines suggest unequal opportunity.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n## Method: move from detail to interpretation\n1. **Observe:** Identify who is speaking, what physically happens and which important detail stands out.\n2. **Classify:** Choose one relevant literary term. Do not force every device into the passage.\n3. **Evidence:** Quote a brief original phrase or describe a stage action exactly.\n4. **Reason:** Explain how that evidence affects characterisation, atmosphere, conflict, theme or audience knowledge.\n5. **Qualify:** Distinguish a well-supported reading from an assumption that the passage does not prove.\n\n## Guided application\nReturn to the original passage. State the central conflict or problem in one sentence. Choose two of the five concepts and write a separate evidence-based explanation for each. What does a careful audience know that a character may not know? If this question does not apply, explain why instead of inventing hidden facts.\n\n## Independent practice and rubric\nCreate a short original extract on a related situation, then write a 150–200 word close reading. For a ten-mark analytical paragraph, allocate 2 marks to a clear claim, 2 to accurate terminology, 3 to appropriate textual evidence and explanation, 2 to weighing a plausible alternative or limitation, and 1 to clear organisation. Your score should reward justified reasoning, not memorising one interpretation.\n\n## Common misconceptions\nAn original model excerpt is not a prescribed examination extract. A character''s words are not automatically an objective truth. A stage direction is not spoken dialogue. A metaphor is not literal proof of an event. A detailed explanation should show how the device works instead of merely naming it.\n\n## Check your own progress\nExplain each concept without looking at your flashcards. Attempt the accompanying ten original multiple-choice questions; review the reasoning after every incorrect answer. Compare your written response with the rubric rather than relying only on an MCQ score.","objectives":["Use accurate literary concepts in close reading","Ground arguments in exact words or stage actions","Evaluate alternative explanations responsibly"],"points":["Institutional critique: A narrative questions the fairness or consequences of organised rules","Bureaucratic obstacle: Administrative procedures delay or block a goal","Collective action: Several characters work together to influence an outcome","Focalisation: Events are presented through a particular character''s knowledge","Ethical inference: A conclusion about fairness follows from specific evidence"],"cards":[{"front":"Define Institutional critique in Prose, Institutions and Social Critique.","back":"A narrative questions the fairness or consequences of organised rules. Original illustration: An application deadline conflicts with office hours.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Bureaucratic obstacle in Prose, Institutions and Social Critique.","back":"Administrative procedures delay or block a goal. Original illustration: A system outage interrupts the application.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Collective action in Prose, Institutions and Social Critique.","back":"Several characters work together to influence an outcome. Original illustration: Residents propose a shared appeal.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Focalisation in Prose, Institutions and Social Critique.","back":"Events are presented through a particular character''s knowledge. Original illustration: The scene closely follows Bola''s experience.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Ethical inference in Prose, Institutions and Social Critique.","back":"A conclusion about fairness follows from specific evidence. Original illustration: Hours and deadlines suggest unequal opportunity.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"How do you build a convincing interpretation of prose, institutions and social critique?","back":"State a focused claim, cite an exact textual detail, explain the effect, and separate solid evidence from plausible inference.","sourceKind":"original-literature-skills","difficulty":"medium"}],"questions":[{"question":"In \"Prose, Institutions and Social Critique\" at SSS3, which concept is defined as: A narrative questions the fairness or consequences of organised rules?","options":[{"id":"A","text":"Bureaucratic obstacle"},{"id":"B","text":"Collective action"},{"id":"C","text":"Focalisation"},{"id":"D","text":"Institutional critique"}],"answer":"D","explanation":"The concept is Institutional critique. It means A narrative questions the fairness or consequences of organised rules. An original example is: An application deadline conflicts with office hours. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Prose, Institutions and Social Critique\": An application deadline conflicts with office hours?","options":[{"id":"A","text":"Bureaucratic obstacle"},{"id":"B","text":"Collective action"},{"id":"C","text":"Institutional critique"},{"id":"D","text":"Focalisation"}],"answer":"C","explanation":"The best answer is Institutional critique because A narrative questions the fairness or consequences of organised rules. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Prose, Institutions and Social Critique\" at SSS3, which concept is defined as: Administrative procedures delay or block a goal?","options":[{"id":"A","text":"Institutional critique"},{"id":"B","text":"Bureaucratic obstacle"},{"id":"C","text":"Collective action"},{"id":"D","text":"Focalisation"}],"answer":"B","explanation":"The concept is Bureaucratic obstacle. It means Administrative procedures delay or block a goal. An original example is: A system outage interrupts the application. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Prose, Institutions and Social Critique\": A system outage interrupts the application?","options":[{"id":"A","text":"Bureaucratic obstacle"},{"id":"B","text":"Institutional critique"},{"id":"C","text":"Collective action"},{"id":"D","text":"Focalisation"}],"answer":"A","explanation":"The best answer is Bureaucratic obstacle because Administrative procedures delay or block a goal. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Prose, Institutions and Social Critique\" at SSS3, which concept is defined as: Several characters work together to influence an outcome?","options":[{"id":"A","text":"Institutional critique"},{"id":"B","text":"Bureaucratic obstacle"},{"id":"C","text":"Focalisation"},{"id":"D","text":"Collective action"}],"answer":"D","explanation":"The concept is Collective action. It means Several characters work together to influence an outcome. An original example is: Residents propose a shared appeal. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Prose, Institutions and Social Critique\": Residents propose a shared appeal?","options":[{"id":"A","text":"Institutional critique"},{"id":"B","text":"Bureaucratic obstacle"},{"id":"C","text":"Collective action"},{"id":"D","text":"Focalisation"}],"answer":"C","explanation":"The best answer is Collective action because Several characters work together to influence an outcome. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Prose, Institutions and Social Critique\" at SSS3, which concept is defined as: Events are presented through a particular character''s knowledge?","options":[{"id":"A","text":"Institutional critique"},{"id":"B","text":"Focalisation"},{"id":"C","text":"Bureaucratic obstacle"},{"id":"D","text":"Collective action"}],"answer":"B","explanation":"The concept is Focalisation. It means Events are presented through a particular character''s knowledge. An original example is: The scene closely follows Bola''s experience. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Prose, Institutions and Social Critique\": The scene closely follows Bola''s experience?","options":[{"id":"A","text":"Focalisation"},{"id":"B","text":"Institutional critique"},{"id":"C","text":"Bureaucratic obstacle"},{"id":"D","text":"Collective action"}],"answer":"A","explanation":"The best answer is Focalisation because Events are presented through a particular character''s knowledge. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Prose, Institutions and Social Critique\" at SSS3, which concept is defined as: A conclusion about fairness follows from specific evidence?","options":[{"id":"A","text":"Institutional critique"},{"id":"B","text":"Bureaucratic obstacle"},{"id":"C","text":"Collective action"},{"id":"D","text":"Ethical inference"}],"answer":"D","explanation":"The concept is Ethical inference. It means A conclusion about fairness follows from specific evidence. An original example is: Hours and deadlines suggest unequal opportunity. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Prose, Institutions and Social Critique\": Hours and deadlines suggest unequal opportunity?","options":[{"id":"A","text":"Institutional critique"},{"id":"B","text":"Bureaucratic obstacle"},{"id":"C","text":"Ethical inference"},{"id":"D","text":"Collective action"}],"answer":"C","explanation":"The best answer is Ethical inference because A conclusion about fairness follows from specific evidence. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."}]},{"level":"SSS3","term":2,"seq":3,"name":"Character Arcs and Moral Ambiguity","intro":"A character arc traces change, stability or disillusion across narrative time. Moral ambiguity means actions support competing assessments. Avoid inventing redemption just because a character apologises once.","passage":"Before the drought, Segun ignored neighbours who asked for water. When his own tank ran dry, they helped him reach a community well. Months later he financed a shared pump but insisted his name be painted on it in large letters.","worked":"The pump suggests a practical positive change. The demand for recognition may also indicate vanity or a desire for accountability. A balanced answer recognises both possibilities and seeks later evidence.","concepts":[["Character arc","A pattern of development or sustained behaviour over time","Segun shifts from refusing help to funding a pump"],["Moral ambiguity","A choice permits different judgements supported by evidence","The generous gift also brings public praise"],["Redemption","A sustained effort to repair wrongs rather than a single declaration","Long-term support would better show Segun''s reform"],["Foil","A contrasting person highlights features of a central role","The neighbours help despite Segun''s earlier refusal"],["Motivation","A reason such as duty pride fear or affection shapes action","Segun might want both community water and public recognition"]],"slug":"lit-sss3-t2-character-arcs-and-moral-ambiguity","code":"G26LITSSS3T2U3","body":"# Character Arcs and Moral Ambiguity — SSS3 Literature in English, Second Term\n\n## What you should achieve\nDefine and accurately apply five central literary concepts; use exact evidence from a new passage to support an interpretation; connect technique to its effect; and identify the limits of what the passage permits you to infer.\n\n## Conceptual foundation\nA character arc traces change, stability or disillusion across narrative time. Moral ambiguity means actions support competing assessments. Avoid inventing redemption just because a character apologises once.\n\n**Source note:** The passage and exercises below are original THE GUIDE teaching examples. They are not passages from a historical WAEC, NECO or JAMB paper, and are not represented as quotations from copyrighted prescribed books. Read the school-approved books in full for set-text analysis.\n\n## New worked passage\n> Before the drought, Segun ignored neighbours who asked for water. When his own tank ran dry, they helped him reach a community well. Months later he financed a shared pump but insisted his name be painted on it in large letters.\n\n## Interpretation: a model response\nThe pump suggests a practical positive change. The demand for recognition may also indicate vanity or a desire for accountability. A balanced answer recognises both possibilities and seeks later evidence.\n\nRead the passage once for literal information, again to notice diction, structure, dialogue, imagery or action, and a third time to test a thesis against a precise textual clue. A justified interpretation is not simply a personal opinion: it has a claim, evidence and reasoning. Different careful readers may make different claims, but they must account for the same details.\n\n## Five important concepts\n### 1. Character arc\n**Meaning:** A pattern of development or sustained behaviour over time.\n**Original illustration:** Segun shifts from refusing help to funding a pump.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 2. Moral ambiguity\n**Meaning:** A choice permits different judgements supported by evidence.\n**Original illustration:** The generous gift also brings public praise.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 3. Redemption\n**Meaning:** A sustained effort to repair wrongs rather than a single declaration.\n**Original illustration:** Long-term support would better show Segun''s reform.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 4. Foil\n**Meaning:** A contrasting person highlights features of a central role.\n**Original illustration:** The neighbours help despite Segun''s earlier refusal.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 5. Motivation\n**Meaning:** A reason such as duty pride fear or affection shapes action.\n**Original illustration:** Segun might want both community water and public recognition.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n## Method: move from detail to interpretation\n1. **Observe:** Identify who is speaking, what physically happens and which important detail stands out.\n2. **Classify:** Choose one relevant literary term. Do not force every device into the passage.\n3. **Evidence:** Quote a brief original phrase or describe a stage action exactly.\n4. **Reason:** Explain how that evidence affects characterisation, atmosphere, conflict, theme or audience knowledge.\n5. **Qualify:** Distinguish a well-supported reading from an assumption that the passage does not prove.\n\n## Guided application\nReturn to the original passage. State the central conflict or problem in one sentence. Choose two of the five concepts and write a separate evidence-based explanation for each. What does a careful audience know that a character may not know? If this question does not apply, explain why instead of inventing hidden facts.\n\n## Independent practice and rubric\nCreate a short original extract on a related situation, then write a 150–200 word close reading. For a ten-mark analytical paragraph, allocate 2 marks to a clear claim, 2 to accurate terminology, 3 to appropriate textual evidence and explanation, 2 to weighing a plausible alternative or limitation, and 1 to clear organisation. Your score should reward justified reasoning, not memorising one interpretation.\n\n## Common misconceptions\nAn original model excerpt is not a prescribed examination extract. A character''s words are not automatically an objective truth. A stage direction is not spoken dialogue. A metaphor is not literal proof of an event. A detailed explanation should show how the device works instead of merely naming it.\n\n## Check your own progress\nExplain each concept without looking at your flashcards. Attempt the accompanying ten original multiple-choice questions; review the reasoning after every incorrect answer. Compare your written response with the rubric rather than relying only on an MCQ score.","objectives":["Use accurate literary concepts in close reading","Ground arguments in exact words or stage actions","Evaluate alternative explanations responsibly"],"points":["Character arc: A pattern of development or sustained behaviour over time","Moral ambiguity: A choice permits different judgements supported by evidence","Redemption: A sustained effort to repair wrongs rather than a single declaration","Foil: A contrasting person highlights features of a central role","Motivation: A reason such as duty pride fear or affection shapes action"],"cards":[{"front":"Define Character arc in Character Arcs and Moral Ambiguity.","back":"A pattern of development or sustained behaviour over time. Original illustration: Segun shifts from refusing help to funding a pump.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Moral ambiguity in Character Arcs and Moral Ambiguity.","back":"A choice permits different judgements supported by evidence. Original illustration: The generous gift also brings public praise.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Redemption in Character Arcs and Moral Ambiguity.","back":"A sustained effort to repair wrongs rather than a single declaration. Original illustration: Long-term support would better show Segun''s reform.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Foil in Character Arcs and Moral Ambiguity.","back":"A contrasting person highlights features of a central role. Original illustration: The neighbours help despite Segun''s earlier refusal.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Motivation in Character Arcs and Moral Ambiguity.","back":"A reason such as duty pride fear or affection shapes action. Original illustration: Segun might want both community water and public recognition.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"How do you build a convincing interpretation of character arcs and moral ambiguity?","back":"State a focused claim, cite an exact textual detail, explain the effect, and separate solid evidence from plausible inference.","sourceKind":"original-literature-skills","difficulty":"medium"}],"questions":[{"question":"In \"Character Arcs and Moral Ambiguity\" at SSS3, which concept is defined as: A pattern of development or sustained behaviour over time?","options":[{"id":"A","text":"Moral ambiguity"},{"id":"B","text":"Character arc"},{"id":"C","text":"Redemption"},{"id":"D","text":"Foil"}],"answer":"B","explanation":"The concept is Character arc. It means A pattern of development or sustained behaviour over time. An original example is: Segun shifts from refusing help to funding a pump. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Character Arcs and Moral Ambiguity\": Segun shifts from refusing help to funding a pump?","options":[{"id":"A","text":"Character arc"},{"id":"B","text":"Moral ambiguity"},{"id":"C","text":"Redemption"},{"id":"D","text":"Foil"}],"answer":"A","explanation":"The best answer is Character arc because A pattern of development or sustained behaviour over time. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Character Arcs and Moral Ambiguity\" at SSS3, which concept is defined as: A choice permits different judgements supported by evidence?","options":[{"id":"A","text":"Character arc"},{"id":"B","text":"Redemption"},{"id":"C","text":"Foil"},{"id":"D","text":"Moral ambiguity"}],"answer":"D","explanation":"The concept is Moral ambiguity. It means A choice permits different judgements supported by evidence. An original example is: The generous gift also brings public praise. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Character Arcs and Moral Ambiguity\": The generous gift also brings public praise?","options":[{"id":"A","text":"Character arc"},{"id":"B","text":"Redemption"},{"id":"C","text":"Moral ambiguity"},{"id":"D","text":"Foil"}],"answer":"C","explanation":"The best answer is Moral ambiguity because A choice permits different judgements supported by evidence. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Character Arcs and Moral Ambiguity\" at SSS3, which concept is defined as: A sustained effort to repair wrongs rather than a single declaration?","options":[{"id":"A","text":"Character arc"},{"id":"B","text":"Redemption"},{"id":"C","text":"Moral ambiguity"},{"id":"D","text":"Foil"}],"answer":"B","explanation":"The concept is Redemption. It means A sustained effort to repair wrongs rather than a single declaration. An original example is: Long-term support would better show Segun''s reform. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Character Arcs and Moral Ambiguity\": Long-term support would better show Segun''s reform?","options":[{"id":"A","text":"Redemption"},{"id":"B","text":"Character arc"},{"id":"C","text":"Moral ambiguity"},{"id":"D","text":"Foil"}],"answer":"A","explanation":"The best answer is Redemption because A sustained effort to repair wrongs rather than a single declaration. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Character Arcs and Moral Ambiguity\" at SSS3, which concept is defined as: A contrasting person highlights features of a central role?","options":[{"id":"A","text":"Character arc"},{"id":"B","text":"Moral ambiguity"},{"id":"C","text":"Redemption"},{"id":"D","text":"Foil"}],"answer":"D","explanation":"The concept is Foil. It means A contrasting person highlights features of a central role. An original example is: The neighbours help despite Segun''s earlier refusal. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Character Arcs and Moral Ambiguity\": The neighbours help despite Segun''s earlier refusal?","options":[{"id":"A","text":"Character arc"},{"id":"B","text":"Moral ambiguity"},{"id":"C","text":"Foil"},{"id":"D","text":"Redemption"}],"answer":"C","explanation":"The best answer is Foil because A contrasting person highlights features of a central role. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Character Arcs and Moral Ambiguity\" at SSS3, which concept is defined as: A reason such as duty pride fear or affection shapes action?","options":[{"id":"A","text":"Character arc"},{"id":"B","text":"Motivation"},{"id":"C","text":"Moral ambiguity"},{"id":"D","text":"Redemption"}],"answer":"B","explanation":"The concept is Motivation. It means A reason such as duty pride fear or affection shapes action. An original example is: Segun might want both community water and public recognition. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Character Arcs and Moral Ambiguity\": Segun might want both community water and public recognition?","options":[{"id":"A","text":"Motivation"},{"id":"B","text":"Character arc"},{"id":"C","text":"Moral ambiguity"},{"id":"D","text":"Redemption"}],"answer":"A","explanation":"The best answer is Motivation because A reason such as duty pride fear or affection shapes action. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."}]},{"level":"SSS3","term":2,"seq":4,"name":"Selecting and Explaining Prose Evidence","intro":"Accurate evidence is not the same as attaching an arbitrary quotation to a claim. Choose a line that bears on the question and discuss how word choice or narrative sequence supports your view. Short, correct citations are stronger than invented long quotations.","passage":"Original excerpt: ''Maro could not sign the notice. His hands were shaking after the hearing, but he placed the unsigned page beside the petition and invited the others to read it.''","worked":"The trembling suggests distress but does not identify a single cause. The public invitation signals openness to scrutiny; the unsigned notice may represent uncertainty. Explain each clue rather than claiming that Maro has confessed to wrongdoing.","concepts":[["Selective quotation","A brief exact phrase is chosen because it proves a relevant point","His hands were shaking supports distress"],["Paraphrase","A passage is restated accurately in new wording","Maro leaves the paper unsigned and shares it"],["Analytical inference","A conclusion is reasoned from details but not stated outright","His public gesture may suggest openness"],["Overclaim","An interpretation asserts more certainty than evidence permits","The trembling proves criminal guilt is unjustified"],["Integration","A quotation is woven into a sentence with explanation","The phrase unsigned page highlights the unresolved decision"]],"slug":"lit-sss3-t2-selecting-and-explaining-prose-evidence","code":"G26LITSSS3T2U4","body":"# Selecting and Explaining Prose Evidence — SSS3 Literature in English, Second Term\n\n## What you should achieve\nDefine and accurately apply five central literary concepts; use exact evidence from a new passage to support an interpretation; connect technique to its effect; and identify the limits of what the passage permits you to infer.\n\n## Conceptual foundation\nAccurate evidence is not the same as attaching an arbitrary quotation to a claim. Choose a line that bears on the question and discuss how word choice or narrative sequence supports your view. Short, correct citations are stronger than invented long quotations.\n\n**Source note:** The passage and exercises below are original THE GUIDE teaching examples. They are not passages from a historical WAEC, NECO or JAMB paper, and are not represented as quotations from copyrighted prescribed books. Read the school-approved books in full for set-text analysis.\n\n## New worked passage\n> Original excerpt: ''Maro could not sign the notice. His hands were shaking after the hearing, but he placed the unsigned page beside the petition and invited the others to read it.''\n\n## Interpretation: a model response\nThe trembling suggests distress but does not identify a single cause. The public invitation signals openness to scrutiny; the unsigned notice may represent uncertainty. Explain each clue rather than claiming that Maro has confessed to wrongdoing.\n\nRead the passage once for literal information, again to notice diction, structure, dialogue, imagery or action, and a third time to test a thesis against a precise textual clue. A justified interpretation is not simply a personal opinion: it has a claim, evidence and reasoning. Different careful readers may make different claims, but they must account for the same details.\n\n## Five important concepts\n### 1. Selective quotation\n**Meaning:** A brief exact phrase is chosen because it proves a relevant point.\n**Original illustration:** His hands were shaking supports distress.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 2. Paraphrase\n**Meaning:** A passage is restated accurately in new wording.\n**Original illustration:** Maro leaves the paper unsigned and shares it.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 3. Analytical inference\n**Meaning:** A conclusion is reasoned from details but not stated outright.\n**Original illustration:** His public gesture may suggest openness.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 4. Overclaim\n**Meaning:** An interpretation asserts more certainty than evidence permits.\n**Original illustration:** The trembling proves criminal guilt is unjustified.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 5. Integration\n**Meaning:** A quotation is woven into a sentence with explanation.\n**Original illustration:** The phrase unsigned page highlights the unresolved decision.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n## Method: move from detail to interpretation\n1. **Observe:** Identify who is speaking, what physically happens and which important detail stands out.\n2. **Classify:** Choose one relevant literary term. Do not force every device into the passage.\n3. **Evidence:** Quote a brief original phrase or describe a stage action exactly.\n4. **Reason:** Explain how that evidence affects characterisation, atmosphere, conflict, theme or audience knowledge.\n5. **Qualify:** Distinguish a well-supported reading from an assumption that the passage does not prove.\n\n## Guided application\nReturn to the original passage. State the central conflict or problem in one sentence. Choose two of the five concepts and write a separate evidence-based explanation for each. What does a careful audience know that a character may not know? If this question does not apply, explain why instead of inventing hidden facts.\n\n## Independent practice and rubric\nCreate a short original extract on a related situation, then write a 150–200 word close reading. For a ten-mark analytical paragraph, allocate 2 marks to a clear claim, 2 to accurate terminology, 3 to appropriate textual evidence and explanation, 2 to weighing a plausible alternative or limitation, and 1 to clear organisation. Your score should reward justified reasoning, not memorising one interpretation.\n\n## Common misconceptions\nAn original model excerpt is not a prescribed examination extract. A character''s words are not automatically an objective truth. A stage direction is not spoken dialogue. A metaphor is not literal proof of an event. A detailed explanation should show how the device works instead of merely naming it.\n\n## Check your own progress\nExplain each concept without looking at your flashcards. Attempt the accompanying ten original multiple-choice questions; review the reasoning after every incorrect answer. Compare your written response with the rubric rather than relying only on an MCQ score.","objectives":["Use accurate literary concepts in close reading","Ground arguments in exact words or stage actions","Evaluate alternative explanations responsibly"],"points":["Selective quotation: A brief exact phrase is chosen because it proves a relevant point","Paraphrase: A passage is restated accurately in new wording","Analytical inference: A conclusion is reasoned from details but not stated outright","Overclaim: An interpretation asserts more certainty than evidence permits","Integration: A quotation is woven into a sentence with explanation"],"cards":[{"front":"Define Selective quotation in Selecting and Explaining Prose Evidence.","back":"A brief exact phrase is chosen because it proves a relevant point. Original illustration: His hands were shaking supports distress.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Paraphrase in Selecting and Explaining Prose Evidence.","back":"A passage is restated accurately in new wording. Original illustration: Maro leaves the paper unsigned and shares it.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Analytical inference in Selecting and Explaining Prose Evidence.","back":"A conclusion is reasoned from details but not stated outright. Original illustration: His public gesture may suggest openness.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Overclaim in Selecting and Explaining Prose Evidence.","back":"An interpretation asserts more certainty than evidence permits. Original illustration: The trembling proves criminal guilt is unjustified.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Integration in Selecting and Explaining Prose Evidence.","back":"A quotation is woven into a sentence with explanation. Original illustration: The phrase unsigned page highlights the unresolved decision.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"How do you build a convincing interpretation of selecting and explaining prose evidence?","back":"State a focused claim, cite an exact textual detail, explain the effect, and separate solid evidence from plausible inference.","sourceKind":"original-literature-skills","difficulty":"medium"}],"questions":[{"question":"In \"Selecting and Explaining Prose Evidence\" at SSS3, which concept is defined as: A brief exact phrase is chosen because it proves a relevant point?","options":[{"id":"A","text":"Paraphrase"},{"id":"B","text":"Analytical inference"},{"id":"C","text":"Overclaim"},{"id":"D","text":"Selective quotation"}],"answer":"D","explanation":"The concept is Selective quotation. It means A brief exact phrase is chosen because it proves a relevant point. An original example is: His hands were shaking supports distress. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Selecting and Explaining Prose Evidence\": His hands were shaking supports distress?","options":[{"id":"A","text":"Paraphrase"},{"id":"B","text":"Analytical inference"},{"id":"C","text":"Selective quotation"},{"id":"D","text":"Overclaim"}],"answer":"C","explanation":"The best answer is Selective quotation because A brief exact phrase is chosen because it proves a relevant point. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Selecting and Explaining Prose Evidence\" at SSS3, which concept is defined as: A passage is restated accurately in new wording?","options":[{"id":"A","text":"Selective quotation"},{"id":"B","text":"Paraphrase"},{"id":"C","text":"Analytical inference"},{"id":"D","text":"Overclaim"}],"answer":"B","explanation":"The concept is Paraphrase. It means A passage is restated accurately in new wording. An original example is: Maro leaves the paper unsigned and shares it. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Selecting and Explaining Prose Evidence\": Maro leaves the paper unsigned and shares it?","options":[{"id":"A","text":"Paraphrase"},{"id":"B","text":"Selective quotation"},{"id":"C","text":"Analytical inference"},{"id":"D","text":"Overclaim"}],"answer":"A","explanation":"The best answer is Paraphrase because A passage is restated accurately in new wording. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Selecting and Explaining Prose Evidence\" at SSS3, which concept is defined as: A conclusion is reasoned from details but not stated outright?","options":[{"id":"A","text":"Selective quotation"},{"id":"B","text":"Paraphrase"},{"id":"C","text":"Overclaim"},{"id":"D","text":"Analytical inference"}],"answer":"D","explanation":"The concept is Analytical inference. It means A conclusion is reasoned from details but not stated outright. An original example is: His public gesture may suggest openness. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Selecting and Explaining Prose Evidence\": His public gesture may suggest openness?","options":[{"id":"A","text":"Selective quotation"},{"id":"B","text":"Paraphrase"},{"id":"C","text":"Analytical inference"},{"id":"D","text":"Overclaim"}],"answer":"C","explanation":"The best answer is Analytical inference because A conclusion is reasoned from details but not stated outright. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Selecting and Explaining Prose Evidence\" at SSS3, which concept is defined as: An interpretation asserts more certainty than evidence permits?","options":[{"id":"A","text":"Selective quotation"},{"id":"B","text":"Overclaim"},{"id":"C","text":"Paraphrase"},{"id":"D","text":"Analytical inference"}],"answer":"B","explanation":"The concept is Overclaim. It means An interpretation asserts more certainty than evidence permits. An original example is: The trembling proves criminal guilt is unjustified. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Selecting and Explaining Prose Evidence\": The trembling proves criminal guilt is unjustified?","options":[{"id":"A","text":"Overclaim"},{"id":"B","text":"Selective quotation"},{"id":"C","text":"Paraphrase"},{"id":"D","text":"Analytical inference"}],"answer":"A","explanation":"The best answer is Overclaim because An interpretation asserts more certainty than evidence permits. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Selecting and Explaining Prose Evidence\" at SSS3, which concept is defined as: A quotation is woven into a sentence with explanation?","options":[{"id":"A","text":"Selective quotation"},{"id":"B","text":"Paraphrase"},{"id":"C","text":"Analytical inference"},{"id":"D","text":"Integration"}],"answer":"D","explanation":"The concept is Integration. It means A quotation is woven into a sentence with explanation. An original example is: The phrase unsigned page highlights the unresolved decision. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Selecting and Explaining Prose Evidence\": The phrase unsigned page highlights the unresolved decision?","options":[{"id":"A","text":"Selective quotation"},{"id":"B","text":"Paraphrase"},{"id":"C","text":"Integration"},{"id":"D","text":"Analytical inference"}],"answer":"C","explanation":"The best answer is Integration because A quotation is woven into a sentence with explanation. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."}]},{"level":"SSS3","term":2,"seq":5,"name":"Open Endings and Reader Responsibility","intro":"An open ending leaves important outcomes unresolved. This can invite reflection or foreground uncertainty rather than signal that the author forgot to finish. Evaluate which questions remain and which facts have already been settled.","passage":"By sunset, the missing register lay on the headteacher''s table. No one had admitted taking it. The students left the room with two conflicting explanations, while the caretaker quietly turned out the lights.","worked":"The register is recovered but responsibility remains uncertain. The caretaker''s silence is not an implicit confession. A thoughtful reader distinguishes closure of one practical problem from continued interpretive openness.","concepts":[["Open ending","A narrative finishes while key outcomes or explanations remain unsettled","The register is found but its movement is unexplained"],["Partial closure","Some conflicts resolve even while others remain","The school recovers the register"],["Narrative gap","A missing piece of information demands careful inference","No witness confirms who moved the register"],["Reader participation","The text invites audiences to weigh evidence and alternatives","Two rival explanations remain possible"],["Ambiguous gesture","An action supports multiple meanings without proving one","The caretaker quietly switches off the lights"]],"slug":"lit-sss3-t2-open-endings-and-reader-responsibility","code":"G26LITSSS3T2U5","body":"# Open Endings and Reader Responsibility — SSS3 Literature in English, Second Term\n\n## What you should achieve\nDefine and accurately apply five central literary concepts; use exact evidence from a new passage to support an interpretation; connect technique to its effect; and identify the limits of what the passage permits you to infer.\n\n## Conceptual foundation\nAn open ending leaves important outcomes unresolved. This can invite reflection or foreground uncertainty rather than signal that the author forgot to finish. Evaluate which questions remain and which facts have already been settled.\n\n**Source note:** The passage and exercises below are original THE GUIDE teaching examples. They are not passages from a historical WAEC, NECO or JAMB paper, and are not represented as quotations from copyrighted prescribed books. Read the school-approved books in full for set-text analysis.\n\n## New worked passage\n> By sunset, the missing register lay on the headteacher''s table. No one had admitted taking it. The students left the room with two conflicting explanations, while the caretaker quietly turned out the lights.\n\n## Interpretation: a model response\nThe register is recovered but responsibility remains uncertain. The caretaker''s silence is not an implicit confession. A thoughtful reader distinguishes closure of one practical problem from continued interpretive openness.\n\nRead the passage once for literal information, again to notice diction, structure, dialogue, imagery or action, and a third time to test a thesis against a precise textual clue. A justified interpretation is not simply a personal opinion: it has a claim, evidence and reasoning. Different careful readers may make different claims, but they must account for the same details.\n\n## Five important concepts\n### 1. Open ending\n**Meaning:** A narrative finishes while key outcomes or explanations remain unsettled.\n**Original illustration:** The register is found but its movement is unexplained.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 2. Partial closure\n**Meaning:** Some conflicts resolve even while others remain.\n**Original illustration:** The school recovers the register.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 3. Narrative gap\n**Meaning:** A missing piece of information demands careful inference.\n**Original illustration:** No witness confirms who moved the register.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 4. Reader participation\n**Meaning:** The text invites audiences to weigh evidence and alternatives.\n**Original illustration:** Two rival explanations remain possible.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 5. Ambiguous gesture\n**Meaning:** An action supports multiple meanings without proving one.\n**Original illustration:** The caretaker quietly switches off the lights.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n## Method: move from detail to interpretation\n1. **Observe:** Identify who is speaking, what physically happens and which important detail stands out.\n2. **Classify:** Choose one relevant literary term. Do not force every device into the passage.\n3. **Evidence:** Quote a brief original phrase or describe a stage action exactly.\n4. **Reason:** Explain how that evidence affects characterisation, atmosphere, conflict, theme or audience knowledge.\n5. **Qualify:** Distinguish a well-supported reading from an assumption that the passage does not prove.\n\n## Guided application\nReturn to the original passage. State the central conflict or problem in one sentence. Choose two of the five concepts and write a separate evidence-based explanation for each. What does a careful audience know that a character may not know? If this question does not apply, explain why instead of inventing hidden facts.\n\n## Independent practice and rubric\nCreate a short original extract on a related situation, then write a 150–200 word close reading. For a ten-mark analytical paragraph, allocate 2 marks to a clear claim, 2 to accurate terminology, 3 to appropriate textual evidence and explanation, 2 to weighing a plausible alternative or limitation, and 1 to clear organisation. Your score should reward justified reasoning, not memorising one interpretation.\n\n## Common misconceptions\nAn original model excerpt is not a prescribed examination extract. A character''s words are not automatically an objective truth. A stage direction is not spoken dialogue. A metaphor is not literal proof of an event. A detailed explanation should show how the device works instead of merely naming it.\n\n## Check your own progress\nExplain each concept without looking at your flashcards. Attempt the accompanying ten original multiple-choice questions; review the reasoning after every incorrect answer. Compare your written response with the rubric rather than relying only on an MCQ score.","objectives":["Use accurate literary concepts in close reading","Ground arguments in exact words or stage actions","Evaluate alternative explanations responsibly"],"points":["Open ending: A narrative finishes while key outcomes or explanations remain unsettled","Partial closure: Some conflicts resolve even while others remain","Narrative gap: A missing piece of information demands careful inference","Reader participation: The text invites audiences to weigh evidence and alternatives","Ambiguous gesture: An action supports multiple meanings without proving one"],"cards":[{"front":"Define Open ending in Open Endings and Reader Responsibility.","back":"A narrative finishes while key outcomes or explanations remain unsettled. Original illustration: The register is found but its movement is unexplained.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Partial closure in Open Endings and Reader Responsibility.","back":"Some conflicts resolve even while others remain. Original illustration: The school recovers the register.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Narrative gap in Open Endings and Reader Responsibility.","back":"A missing piece of information demands careful inference. Original illustration: No witness confirms who moved the register.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Reader participation in Open Endings and Reader Responsibility.","back":"The text invites audiences to weigh evidence and alternatives. Original illustration: Two rival explanations remain possible.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Ambiguous gesture in Open Endings and Reader Responsibility.","back":"An action supports multiple meanings without proving one. Original illustration: The caretaker quietly switches off the lights.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"How do you build a convincing interpretation of open endings and reader responsibility?","back":"State a focused claim, cite an exact textual detail, explain the effect, and separate solid evidence from plausible inference.","sourceKind":"original-literature-skills","difficulty":"medium"}],"questions":[{"question":"In \"Open Endings and Reader Responsibility\" at SSS3, which concept is defined as: A narrative finishes while key outcomes or explanations remain unsettled?","options":[{"id":"A","text":"Partial closure"},{"id":"B","text":"Open ending"},{"id":"C","text":"Narrative gap"},{"id":"D","text":"Reader participation"}],"answer":"B","explanation":"The concept is Open ending. It means A narrative finishes while key outcomes or explanations remain unsettled. An original example is: The register is found but its movement is unexplained. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Open Endings and Reader Responsibility\": The register is found but its movement is unexplained?","options":[{"id":"A","text":"Open ending"},{"id":"B","text":"Partial closure"},{"id":"C","text":"Narrative gap"},{"id":"D","text":"Reader participation"}],"answer":"A","explanation":"The best answer is Open ending because A narrative finishes while key outcomes or explanations remain unsettled. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Open Endings and Reader Responsibility\" at SSS3, which concept is defined as: Some conflicts resolve even while others remain?","options":[{"id":"A","text":"Open ending"},{"id":"B","text":"Narrative gap"},{"id":"C","text":"Reader participation"},{"id":"D","text":"Partial closure"}],"answer":"D","explanation":"The concept is Partial closure. It means Some conflicts resolve even while others remain. An original example is: The school recovers the register. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Open Endings and Reader Responsibility\": The school recovers the register?","options":[{"id":"A","text":"Open ending"},{"id":"B","text":"Narrative gap"},{"id":"C","text":"Partial closure"},{"id":"D","text":"Reader participation"}],"answer":"C","explanation":"The best answer is Partial closure because Some conflicts resolve even while others remain. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Open Endings and Reader Responsibility\" at SSS3, which concept is defined as: A missing piece of information demands careful inference?","options":[{"id":"A","text":"Open ending"},{"id":"B","text":"Narrative gap"},{"id":"C","text":"Partial closure"},{"id":"D","text":"Reader participation"}],"answer":"B","explanation":"The concept is Narrative gap. It means A missing piece of information demands careful inference. An original example is: No witness confirms who moved the register. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Open Endings and Reader Responsibility\": No witness confirms who moved the register?","options":[{"id":"A","text":"Narrative gap"},{"id":"B","text":"Open ending"},{"id":"C","text":"Partial closure"},{"id":"D","text":"Reader participation"}],"answer":"A","explanation":"The best answer is Narrative gap because A missing piece of information demands careful inference. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Open Endings and Reader Responsibility\" at SSS3, which concept is defined as: The text invites audiences to weigh evidence and alternatives?","options":[{"id":"A","text":"Open ending"},{"id":"B","text":"Partial closure"},{"id":"C","text":"Narrative gap"},{"id":"D","text":"Reader participation"}],"answer":"D","explanation":"The concept is Reader participation. It means The text invites audiences to weigh evidence and alternatives. An original example is: Two rival explanations remain possible. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Open Endings and Reader Responsibility\": Two rival explanations remain possible?","options":[{"id":"A","text":"Open ending"},{"id":"B","text":"Partial closure"},{"id":"C","text":"Reader participation"},{"id":"D","text":"Narrative gap"}],"answer":"C","explanation":"The best answer is Reader participation because The text invites audiences to weigh evidence and alternatives. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Open Endings and Reader Responsibility\" at SSS3, which concept is defined as: An action supports multiple meanings without proving one?","options":[{"id":"A","text":"Open ending"},{"id":"B","text":"Ambiguous gesture"},{"id":"C","text":"Partial closure"},{"id":"D","text":"Narrative gap"}],"answer":"B","explanation":"The concept is Ambiguous gesture. It means An action supports multiple meanings without proving one. An original example is: The caretaker quietly switches off the lights. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Open Endings and Reader Responsibility\": The caretaker quietly switches off the lights?","options":[{"id":"A","text":"Ambiguous gesture"},{"id":"B","text":"Open ending"},{"id":"C","text":"Partial closure"},{"id":"D","text":"Narrative gap"}],"answer":"A","explanation":"The best answer is Ambiguous gesture because An action supports multiple meanings without proving one. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."}]},{"level":"SSS3","term":3,"seq":1,"name":"Unseen Poetry: First Reading to Analysis","intro":"An unseen poem should be approached in passes: grasp the literal situation, identify speaker and movement, then analyse language. Do not label every image symbolic before establishing its place in the scene.","passage":"At dawn the ferry whistle woke the lane. / I folded yesterday beneath my coat. / The river carried neither blame nor name; / It only held the shadow of our boat.","worked":"A ferry departure is a literal event; folding ''yesterday'' is figurative language suggesting a desire to carry or contain memory. ''Neither blame nor name'' might suggest refusal to judge. Multiple readings remain possible.","concepts":[["Literal reading","Identify what physically happens in a text before interpretation","The ferry leaves at dawn"],["Figurative reading","Language suggests meaning beyond literal facts","I folded yesterday suggests packing away memories"],["Speaker","The poem''s speaking voice need not be identical to the poet","An I-voice observes the departure"],["Imagery","Sensory language gives readers a concrete impression","The ferry whistle creates an audible scene"],["Qualification","A precise answer marks what remains only plausible","The poem suggests rather than proves reconciliation"]],"slug":"lit-sss3-t3-unseen-poetry-first-reading-to-analysis","code":"G26LITSSS3T3U1","body":"# Unseen Poetry: First Reading to Analysis — SSS3 Literature in English, Third Term\n\n## What you should achieve\nDefine and accurately apply five central literary concepts; use exact evidence from a new passage to support an interpretation; connect technique to its effect; and identify the limits of what the passage permits you to infer.\n\n## Conceptual foundation\nAn unseen poem should be approached in passes: grasp the literal situation, identify speaker and movement, then analyse language. Do not label every image symbolic before establishing its place in the scene.\n\n**Source note:** The passage and exercises below are original THE GUIDE teaching examples. They are not passages from a historical WAEC, NECO or JAMB paper, and are not represented as quotations from copyrighted prescribed books. Read the school-approved books in full for set-text analysis.\n\n## New worked passage\n> At dawn the ferry whistle woke the lane. / I folded yesterday beneath my coat. / The river carried neither blame nor name; / It only held the shadow of our boat.\n\n## Interpretation: a model response\nA ferry departure is a literal event; folding ''yesterday'' is figurative language suggesting a desire to carry or contain memory. ''Neither blame nor name'' might suggest refusal to judge. Multiple readings remain possible.\n\nRead the passage once for literal information, again to notice diction, structure, dialogue, imagery or action, and a third time to test a thesis against a precise textual clue. A justified interpretation is not simply a personal opinion: it has a claim, evidence and reasoning. Different careful readers may make different claims, but they must account for the same details.\n\n## Five important concepts\n### 1. Literal reading\n**Meaning:** Identify what physically happens in a text before interpretation.\n**Original illustration:** The ferry leaves at dawn.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 2. Figurative reading\n**Meaning:** Language suggests meaning beyond literal facts.\n**Original illustration:** I folded yesterday suggests packing away memories.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 3. Speaker\n**Meaning:** The poem''s speaking voice need not be identical to the poet.\n**Original illustration:** An I-voice observes the departure.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 4. Imagery\n**Meaning:** Sensory language gives readers a concrete impression.\n**Original illustration:** The ferry whistle creates an audible scene.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 5. Qualification\n**Meaning:** A precise answer marks what remains only plausible.\n**Original illustration:** The poem suggests rather than proves reconciliation.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n## Method: move from detail to interpretation\n1. **Observe:** Identify who is speaking, what physically happens and which important detail stands out.\n2. **Classify:** Choose one relevant literary term. Do not force every device into the passage.\n3. **Evidence:** Quote a brief original phrase or describe a stage action exactly.\n4. **Reason:** Explain how that evidence affects characterisation, atmosphere, conflict, theme or audience knowledge.\n5. **Qualify:** Distinguish a well-supported reading from an assumption that the passage does not prove.\n\n## Guided application\nReturn to the original passage. State the central conflict or problem in one sentence. Choose two of the five concepts and write a separate evidence-based explanation for each. What does a careful audience know that a character may not know? If this question does not apply, explain why instead of inventing hidden facts.\n\n## Independent practice and rubric\nCreate a short original extract on a related situation, then write a 150–200 word close reading. For a ten-mark analytical paragraph, allocate 2 marks to a clear claim, 2 to accurate terminology, 3 to appropriate textual evidence and explanation, 2 to weighing a plausible alternative or limitation, and 1 to clear organisation. Your score should reward justified reasoning, not memorising one interpretation.\n\n## Common misconceptions\nAn original model excerpt is not a prescribed examination extract. A character''s words are not automatically an objective truth. A stage direction is not spoken dialogue. A metaphor is not literal proof of an event. A detailed explanation should show how the device works instead of merely naming it.\n\n## Check your own progress\nExplain each concept without looking at your flashcards. Attempt the accompanying ten original multiple-choice questions; review the reasoning after every incorrect answer. Compare your written response with the rubric rather than relying only on an MCQ score.","objectives":["Use accurate literary concepts in close reading","Ground arguments in exact words or stage actions","Evaluate alternative explanations responsibly"],"points":["Literal reading: Identify what physically happens in a text before interpretation","Figurative reading: Language suggests meaning beyond literal facts","Speaker: The poem''s speaking voice need not be identical to the poet","Imagery: Sensory language gives readers a concrete impression","Qualification: A precise answer marks what remains only plausible"],"cards":[{"front":"Define Literal reading in Unseen Poetry: First Reading to Analysis.","back":"Identify what physically happens in a text before interpretation. Original illustration: The ferry leaves at dawn.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Figurative reading in Unseen Poetry: First Reading to Analysis.","back":"Language suggests meaning beyond literal facts. Original illustration: I folded yesterday suggests packing away memories.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Speaker in Unseen Poetry: First Reading to Analysis.","back":"The poem''s speaking voice need not be identical to the poet. Original illustration: An I-voice observes the departure.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Imagery in Unseen Poetry: First Reading to Analysis.","back":"Sensory language gives readers a concrete impression. Original illustration: The ferry whistle creates an audible scene.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Qualification in Unseen Poetry: First Reading to Analysis.","back":"A precise answer marks what remains only plausible. Original illustration: The poem suggests rather than proves reconciliation.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"How do you build a convincing interpretation of unseen poetry: first reading to analysis?","back":"State a focused claim, cite an exact textual detail, explain the effect, and separate solid evidence from plausible inference.","sourceKind":"original-literature-skills","difficulty":"medium"}],"questions":[{"question":"In \"Unseen Poetry: First Reading to Analysis\" at SSS3, which concept is defined as: Identify what physically happens in a text before interpretation?","options":[{"id":"A","text":"Figurative reading"},{"id":"B","text":"Speaker"},{"id":"C","text":"Imagery"},{"id":"D","text":"Literal reading"}],"answer":"D","explanation":"The concept is Literal reading. It means Identify what physically happens in a text before interpretation. An original example is: The ferry leaves at dawn. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Unseen Poetry: First Reading to Analysis\": The ferry leaves at dawn?","options":[{"id":"A","text":"Figurative reading"},{"id":"B","text":"Speaker"},{"id":"C","text":"Literal reading"},{"id":"D","text":"Imagery"}],"answer":"C","explanation":"The best answer is Literal reading because Identify what physically happens in a text before interpretation. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Unseen Poetry: First Reading to Analysis\" at SSS3, which concept is defined as: Language suggests meaning beyond literal facts?","options":[{"id":"A","text":"Literal reading"},{"id":"B","text":"Figurative reading"},{"id":"C","text":"Speaker"},{"id":"D","text":"Imagery"}],"answer":"B","explanation":"The concept is Figurative reading. It means Language suggests meaning beyond literal facts. An original example is: I folded yesterday suggests packing away memories. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Unseen Poetry: First Reading to Analysis\": I folded yesterday suggests packing away memories?","options":[{"id":"A","text":"Figurative reading"},{"id":"B","text":"Literal reading"},{"id":"C","text":"Speaker"},{"id":"D","text":"Imagery"}],"answer":"A","explanation":"The best answer is Figurative reading because Language suggests meaning beyond literal facts. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Unseen Poetry: First Reading to Analysis\" at SSS3, which concept is defined as: The poem''s speaking voice need not be identical to the poet?","options":[{"id":"A","text":"Literal reading"},{"id":"B","text":"Figurative reading"},{"id":"C","text":"Imagery"},{"id":"D","text":"Speaker"}],"answer":"D","explanation":"The concept is Speaker. It means The poem''s speaking voice need not be identical to the poet. An original example is: An I-voice observes the departure. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Unseen Poetry: First Reading to Analysis\": An I-voice observes the departure?","options":[{"id":"A","text":"Literal reading"},{"id":"B","text":"Figurative reading"},{"id":"C","text":"Speaker"},{"id":"D","text":"Imagery"}],"answer":"C","explanation":"The best answer is Speaker because The poem''s speaking voice need not be identical to the poet. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Unseen Poetry: First Reading to Analysis\" at SSS3, which concept is defined as: Sensory language gives readers a concrete impression?","options":[{"id":"A","text":"Literal reading"},{"id":"B","text":"Imagery"},{"id":"C","text":"Figurative reading"},{"id":"D","text":"Speaker"}],"answer":"B","explanation":"The concept is Imagery. It means Sensory language gives readers a concrete impression. An original example is: The ferry whistle creates an audible scene. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Unseen Poetry: First Reading to Analysis\": The ferry whistle creates an audible scene?","options":[{"id":"A","text":"Imagery"},{"id":"B","text":"Literal reading"},{"id":"C","text":"Figurative reading"},{"id":"D","text":"Speaker"}],"answer":"A","explanation":"The best answer is Imagery because Sensory language gives readers a concrete impression. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Unseen Poetry: First Reading to Analysis\" at SSS3, which concept is defined as: A precise answer marks what remains only plausible?","options":[{"id":"A","text":"Literal reading"},{"id":"B","text":"Figurative reading"},{"id":"C","text":"Speaker"},{"id":"D","text":"Qualification"}],"answer":"D","explanation":"The concept is Qualification. It means A precise answer marks what remains only plausible. An original example is: The poem suggests rather than proves reconciliation. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Unseen Poetry: First Reading to Analysis\": The poem suggests rather than proves reconciliation?","options":[{"id":"A","text":"Literal reading"},{"id":"B","text":"Figurative reading"},{"id":"C","text":"Qualification"},{"id":"D","text":"Speaker"}],"answer":"C","explanation":"The best answer is Qualification because A precise answer marks what remains only plausible. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."}]},{"level":"SSS3","term":3,"seq":2,"name":"Sound Form and Verse Movement","intro":"Compare alliteration, assonance, end-stopping and enjambment by listening to their actual effects. A line break may delay a phrase, while a full stop can interrupt movement. Avoid assigning rhyme by spelling alone.","passage":"The slow sail tilted past the pier / And lifted shadows from the sand. / I paused because the shore was near; / Then felt a lantern touch my hand.","worked":"The /s/ at the beginning of slow and sail offers alliteration. Pier and near share an end sound. The second line completes the motion begun in the first, while the third line introduces a pause.","concepts":[["End rhyme","Matching sounds occur at line ends","Pier and near rhyme"],["Alliteration","Nearby stressed words repeat initial consonant sounds","Slow sail uses repeated initial s"],["Enjambment","A thought crosses a line break without a full syntactic stop","The motion continues from the first to second line"],["End-stopped line","A completed phrase or punctuation closes the line''s movement","The third line ends with a semicolon"],["Rhythm","A patterned movement of stresses syllables or pauses shapes reading","The short third line break invites hesitation"]],"slug":"lit-sss3-t3-sound-form-and-verse-movement","code":"G26LITSSS3T3U2","body":"# Sound Form and Verse Movement — SSS3 Literature in English, Third Term\n\n## What you should achieve\nDefine and accurately apply five central literary concepts; use exact evidence from a new passage to support an interpretation; connect technique to its effect; and identify the limits of what the passage permits you to infer.\n\n## Conceptual foundation\nCompare alliteration, assonance, end-stopping and enjambment by listening to their actual effects. A line break may delay a phrase, while a full stop can interrupt movement. Avoid assigning rhyme by spelling alone.\n\n**Source note:** The passage and exercises below are original THE GUIDE teaching examples. They are not passages from a historical WAEC, NECO or JAMB paper, and are not represented as quotations from copyrighted prescribed books. Read the school-approved books in full for set-text analysis.\n\n## New worked passage\n> The slow sail tilted past the pier / And lifted shadows from the sand. / I paused because the shore was near; / Then felt a lantern touch my hand.\n\n## Interpretation: a model response\nThe /s/ at the beginning of slow and sail offers alliteration. Pier and near share an end sound. The second line completes the motion begun in the first, while the third line introduces a pause.\n\nRead the passage once for literal information, again to notice diction, structure, dialogue, imagery or action, and a third time to test a thesis against a precise textual clue. A justified interpretation is not simply a personal opinion: it has a claim, evidence and reasoning. Different careful readers may make different claims, but they must account for the same details.\n\n## Five important concepts\n### 1. End rhyme\n**Meaning:** Matching sounds occur at line ends.\n**Original illustration:** Pier and near rhyme.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 2. Alliteration\n**Meaning:** Nearby stressed words repeat initial consonant sounds.\n**Original illustration:** Slow sail uses repeated initial s.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 3. Enjambment\n**Meaning:** A thought crosses a line break without a full syntactic stop.\n**Original illustration:** The motion continues from the first to second line.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 4. End-stopped line\n**Meaning:** A completed phrase or punctuation closes the line''s movement.\n**Original illustration:** The third line ends with a semicolon.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 5. Rhythm\n**Meaning:** A patterned movement of stresses syllables or pauses shapes reading.\n**Original illustration:** The short third line break invites hesitation.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n## Method: move from detail to interpretation\n1. **Observe:** Identify who is speaking, what physically happens and which important detail stands out.\n2. **Classify:** Choose one relevant literary term. Do not force every device into the passage.\n3. **Evidence:** Quote a brief original phrase or describe a stage action exactly.\n4. **Reason:** Explain how that evidence affects characterisation, atmosphere, conflict, theme or audience knowledge.\n5. **Qualify:** Distinguish a well-supported reading from an assumption that the passage does not prove.\n\n## Guided application\nReturn to the original passage. State the central conflict or problem in one sentence. Choose two of the five concepts and write a separate evidence-based explanation for each. What does a careful audience know that a character may not know? If this question does not apply, explain why instead of inventing hidden facts.\n\n## Independent practice and rubric\nCreate a short original extract on a related situation, then write a 150–200 word close reading. For a ten-mark analytical paragraph, allocate 2 marks to a clear claim, 2 to accurate terminology, 3 to appropriate textual evidence and explanation, 2 to weighing a plausible alternative or limitation, and 1 to clear organisation. Your score should reward justified reasoning, not memorising one interpretation.\n\n## Common misconceptions\nAn original model excerpt is not a prescribed examination extract. A character''s words are not automatically an objective truth. A stage direction is not spoken dialogue. A metaphor is not literal proof of an event. A detailed explanation should show how the device works instead of merely naming it.\n\n## Check your own progress\nExplain each concept without looking at your flashcards. Attempt the accompanying ten original multiple-choice questions; review the reasoning after every incorrect answer. Compare your written response with the rubric rather than relying only on an MCQ score.","objectives":["Use accurate literary concepts in close reading","Ground arguments in exact words or stage actions","Evaluate alternative explanations responsibly"],"points":["End rhyme: Matching sounds occur at line ends","Alliteration: Nearby stressed words repeat initial consonant sounds","Enjambment: A thought crosses a line break without a full syntactic stop","End-stopped line: A completed phrase or punctuation closes the line''s movement","Rhythm: A patterned movement of stresses syllables or pauses shapes reading"],"cards":[{"front":"Define End rhyme in Sound Form and Verse Movement.","back":"Matching sounds occur at line ends. Original illustration: Pier and near rhyme.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Alliteration in Sound Form and Verse Movement.","back":"Nearby stressed words repeat initial consonant sounds. Original illustration: Slow sail uses repeated initial s.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Enjambment in Sound Form and Verse Movement.","back":"A thought crosses a line break without a full syntactic stop. Original illustration: The motion continues from the first to second line.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define End-stopped line in Sound Form and Verse Movement.","back":"A completed phrase or punctuation closes the line''s movement. Original illustration: The third line ends with a semicolon.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Rhythm in Sound Form and Verse Movement.","back":"A patterned movement of stresses syllables or pauses shapes reading. Original illustration: The short third line break invites hesitation.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"How do you build a convincing interpretation of sound form and verse movement?","back":"State a focused claim, cite an exact textual detail, explain the effect, and separate solid evidence from plausible inference.","sourceKind":"original-literature-skills","difficulty":"medium"}],"questions":[{"question":"In \"Sound Form and Verse Movement\" at SSS3, which concept is defined as: Matching sounds occur at line ends?","options":[{"id":"A","text":"Alliteration"},{"id":"B","text":"End rhyme"},{"id":"C","text":"Enjambment"},{"id":"D","text":"End-stopped line"}],"answer":"B","explanation":"The concept is End rhyme. It means Matching sounds occur at line ends. An original example is: Pier and near rhyme. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Sound Form and Verse Movement\": Pier and near rhyme?","options":[{"id":"A","text":"End rhyme"},{"id":"B","text":"Alliteration"},{"id":"C","text":"Enjambment"},{"id":"D","text":"End-stopped line"}],"answer":"A","explanation":"The best answer is End rhyme because Matching sounds occur at line ends. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Sound Form and Verse Movement\" at SSS3, which concept is defined as: Nearby stressed words repeat initial consonant sounds?","options":[{"id":"A","text":"End rhyme"},{"id":"B","text":"Enjambment"},{"id":"C","text":"End-stopped line"},{"id":"D","text":"Alliteration"}],"answer":"D","explanation":"The concept is Alliteration. It means Nearby stressed words repeat initial consonant sounds. An original example is: Slow sail uses repeated initial s. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Sound Form and Verse Movement\": Slow sail uses repeated initial s?","options":[{"id":"A","text":"End rhyme"},{"id":"B","text":"Enjambment"},{"id":"C","text":"Alliteration"},{"id":"D","text":"End-stopped line"}],"answer":"C","explanation":"The best answer is Alliteration because Nearby stressed words repeat initial consonant sounds. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Sound Form and Verse Movement\" at SSS3, which concept is defined as: A thought crosses a line break without a full syntactic stop?","options":[{"id":"A","text":"End rhyme"},{"id":"B","text":"Enjambment"},{"id":"C","text":"Alliteration"},{"id":"D","text":"End-stopped line"}],"answer":"B","explanation":"The concept is Enjambment. It means A thought crosses a line break without a full syntactic stop. An original example is: The motion continues from the first to second line. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Sound Form and Verse Movement\": The motion continues from the first to second line?","options":[{"id":"A","text":"Enjambment"},{"id":"B","text":"End rhyme"},{"id":"C","text":"Alliteration"},{"id":"D","text":"End-stopped line"}],"answer":"A","explanation":"The best answer is Enjambment because A thought crosses a line break without a full syntactic stop. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Sound Form and Verse Movement\" at SSS3, which concept is defined as: A completed phrase or punctuation closes the line''s movement?","options":[{"id":"A","text":"End rhyme"},{"id":"B","text":"Alliteration"},{"id":"C","text":"Enjambment"},{"id":"D","text":"End-stopped line"}],"answer":"D","explanation":"The concept is End-stopped line. It means A completed phrase or punctuation closes the line''s movement. An original example is: The third line ends with a semicolon. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Sound Form and Verse Movement\": The third line ends with a semicolon?","options":[{"id":"A","text":"End rhyme"},{"id":"B","text":"Alliteration"},{"id":"C","text":"End-stopped line"},{"id":"D","text":"Enjambment"}],"answer":"C","explanation":"The best answer is End-stopped line because A completed phrase or punctuation closes the line''s movement. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Sound Form and Verse Movement\" at SSS3, which concept is defined as: A patterned movement of stresses syllables or pauses shapes reading?","options":[{"id":"A","text":"End rhyme"},{"id":"B","text":"Rhythm"},{"id":"C","text":"Alliteration"},{"id":"D","text":"Enjambment"}],"answer":"B","explanation":"The concept is Rhythm. It means A patterned movement of stresses syllables or pauses shapes reading. An original example is: The short third line break invites hesitation. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Sound Form and Verse Movement\": The short third line break invites hesitation?","options":[{"id":"A","text":"Rhythm"},{"id":"B","text":"End rhyme"},{"id":"C","text":"Alliteration"},{"id":"D","text":"Enjambment"}],"answer":"A","explanation":"The best answer is Rhythm because A patterned movement of stresses syllables or pauses shapes reading. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."}]},{"level":"SSS3","term":3,"seq":3,"name":"Comparative Unseen Poetry","intro":"An advanced comparison should identify a shared concern and compare the particular techniques used to convey it. A good answer moves between texts rather than writing unrelated mini-essays.","passage":"Poem A: ''I kept the gate ajar through winter rain; / Perhaps an absent friend would cross the lane.'' Poem B: ''The door was sealed against the evening storm; / Inside we worked to keep the children warm.''","worked":"Both poems concern boundaries and protection. An open gate in A may indicate hope or vulnerability, whereas B''s sealed door suggests shelter or exclusion. Diction and context determine a defended reading.","concepts":[["Shared theme","A common concern provides a useful comparison question","Both poems examine protection and waiting"],["Contrastive diction","Different word choices create opposed shades of meaning","Ajar contrasts with sealed"],["Structural comparison","The order or form of ideas is compared across texts","A hopes for arrival while B describes present action"],["Nuance","A careful answer acknowledges mixed implications","A closed door can protect and exclude"],["Integrated paragraph","Evidence from both poems is linked within one claim","The two doors frame distinct responses to uncertainty"]],"slug":"lit-sss3-t3-comparative-unseen-poetry","code":"G26LITSSS3T3U3","body":"# Comparative Unseen Poetry — SSS3 Literature in English, Third Term\n\n## What you should achieve\nDefine and accurately apply five central literary concepts; use exact evidence from a new passage to support an interpretation; connect technique to its effect; and identify the limits of what the passage permits you to infer.\n\n## Conceptual foundation\nAn advanced comparison should identify a shared concern and compare the particular techniques used to convey it. A good answer moves between texts rather than writing unrelated mini-essays.\n\n**Source note:** The passage and exercises below are original THE GUIDE teaching examples. They are not passages from a historical WAEC, NECO or JAMB paper, and are not represented as quotations from copyrighted prescribed books. Read the school-approved books in full for set-text analysis.\n\n## New worked passage\n> Poem A: ''I kept the gate ajar through winter rain; / Perhaps an absent friend would cross the lane.'' Poem B: ''The door was sealed against the evening storm; / Inside we worked to keep the children warm.''\n\n## Interpretation: a model response\nBoth poems concern boundaries and protection. An open gate in A may indicate hope or vulnerability, whereas B''s sealed door suggests shelter or exclusion. Diction and context determine a defended reading.\n\nRead the passage once for literal information, again to notice diction, structure, dialogue, imagery or action, and a third time to test a thesis against a precise textual clue. A justified interpretation is not simply a personal opinion: it has a claim, evidence and reasoning. Different careful readers may make different claims, but they must account for the same details.\n\n## Five important concepts\n### 1. Shared theme\n**Meaning:** A common concern provides a useful comparison question.\n**Original illustration:** Both poems examine protection and waiting.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 2. Contrastive diction\n**Meaning:** Different word choices create opposed shades of meaning.\n**Original illustration:** Ajar contrasts with sealed.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 3. Structural comparison\n**Meaning:** The order or form of ideas is compared across texts.\n**Original illustration:** A hopes for arrival while B describes present action.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 4. Nuance\n**Meaning:** A careful answer acknowledges mixed implications.\n**Original illustration:** A closed door can protect and exclude.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 5. Integrated paragraph\n**Meaning:** Evidence from both poems is linked within one claim.\n**Original illustration:** The two doors frame distinct responses to uncertainty.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n## Method: move from detail to interpretation\n1. **Observe:** Identify who is speaking, what physically happens and which important detail stands out.\n2. **Classify:** Choose one relevant literary term. Do not force every device into the passage.\n3. **Evidence:** Quote a brief original phrase or describe a stage action exactly.\n4. **Reason:** Explain how that evidence affects characterisation, atmosphere, conflict, theme or audience knowledge.\n5. **Qualify:** Distinguish a well-supported reading from an assumption that the passage does not prove.\n\n## Guided application\nReturn to the original passage. State the central conflict or problem in one sentence. Choose two of the five concepts and write a separate evidence-based explanation for each. What does a careful audience know that a character may not know? If this question does not apply, explain why instead of inventing hidden facts.\n\n## Independent practice and rubric\nCreate a short original extract on a related situation, then write a 150–200 word close reading. For a ten-mark analytical paragraph, allocate 2 marks to a clear claim, 2 to accurate terminology, 3 to appropriate textual evidence and explanation, 2 to weighing a plausible alternative or limitation, and 1 to clear organisation. Your score should reward justified reasoning, not memorising one interpretation.\n\n## Common misconceptions\nAn original model excerpt is not a prescribed examination extract. A character''s words are not automatically an objective truth. A stage direction is not spoken dialogue. A metaphor is not literal proof of an event. A detailed explanation should show how the device works instead of merely naming it.\n\n## Check your own progress\nExplain each concept without looking at your flashcards. Attempt the accompanying ten original multiple-choice questions; review the reasoning after every incorrect answer. Compare your written response with the rubric rather than relying only on an MCQ score.","objectives":["Use accurate literary concepts in close reading","Ground arguments in exact words or stage actions","Evaluate alternative explanations responsibly"],"points":["Shared theme: A common concern provides a useful comparison question","Contrastive diction: Different word choices create opposed shades of meaning","Structural comparison: The order or form of ideas is compared across texts","Nuance: A careful answer acknowledges mixed implications","Integrated paragraph: Evidence from both poems is linked within one claim"],"cards":[{"front":"Define Shared theme in Comparative Unseen Poetry.","back":"A common concern provides a useful comparison question. Original illustration: Both poems examine protection and waiting.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Contrastive diction in Comparative Unseen Poetry.","back":"Different word choices create opposed shades of meaning. Original illustration: Ajar contrasts with sealed.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Structural comparison in Comparative Unseen Poetry.","back":"The order or form of ideas is compared across texts. Original illustration: A hopes for arrival while B describes present action.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Nuance in Comparative Unseen Poetry.","back":"A careful answer acknowledges mixed implications. Original illustration: A closed door can protect and exclude.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Integrated paragraph in Comparative Unseen Poetry.","back":"Evidence from both poems is linked within one claim. Original illustration: The two doors frame distinct responses to uncertainty.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"How do you build a convincing interpretation of comparative unseen poetry?","back":"State a focused claim, cite an exact textual detail, explain the effect, and separate solid evidence from plausible inference.","sourceKind":"original-literature-skills","difficulty":"medium"}],"questions":[{"question":"In \"Comparative Unseen Poetry\" at SSS3, which concept is defined as: A common concern provides a useful comparison question?","options":[{"id":"A","text":"Contrastive diction"},{"id":"B","text":"Structural comparison"},{"id":"C","text":"Nuance"},{"id":"D","text":"Shared theme"}],"answer":"D","explanation":"The concept is Shared theme. It means A common concern provides a useful comparison question. An original example is: Both poems examine protection and waiting. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Comparative Unseen Poetry\": Both poems examine protection and waiting?","options":[{"id":"A","text":"Contrastive diction"},{"id":"B","text":"Structural comparison"},{"id":"C","text":"Shared theme"},{"id":"D","text":"Nuance"}],"answer":"C","explanation":"The best answer is Shared theme because A common concern provides a useful comparison question. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Comparative Unseen Poetry\" at SSS3, which concept is defined as: Different word choices create opposed shades of meaning?","options":[{"id":"A","text":"Shared theme"},{"id":"B","text":"Contrastive diction"},{"id":"C","text":"Structural comparison"},{"id":"D","text":"Nuance"}],"answer":"B","explanation":"The concept is Contrastive diction. It means Different word choices create opposed shades of meaning. An original example is: Ajar contrasts with sealed. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Comparative Unseen Poetry\": Ajar contrasts with sealed?","options":[{"id":"A","text":"Contrastive diction"},{"id":"B","text":"Shared theme"},{"id":"C","text":"Structural comparison"},{"id":"D","text":"Nuance"}],"answer":"A","explanation":"The best answer is Contrastive diction because Different word choices create opposed shades of meaning. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Comparative Unseen Poetry\" at SSS3, which concept is defined as: The order or form of ideas is compared across texts?","options":[{"id":"A","text":"Shared theme"},{"id":"B","text":"Contrastive diction"},{"id":"C","text":"Nuance"},{"id":"D","text":"Structural comparison"}],"answer":"D","explanation":"The concept is Structural comparison. It means The order or form of ideas is compared across texts. An original example is: A hopes for arrival while B describes present action. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Comparative Unseen Poetry\": A hopes for arrival while B describes present action?","options":[{"id":"A","text":"Shared theme"},{"id":"B","text":"Contrastive diction"},{"id":"C","text":"Structural comparison"},{"id":"D","text":"Nuance"}],"answer":"C","explanation":"The best answer is Structural comparison because The order or form of ideas is compared across texts. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Comparative Unseen Poetry\" at SSS3, which concept is defined as: A careful answer acknowledges mixed implications?","options":[{"id":"A","text":"Shared theme"},{"id":"B","text":"Nuance"},{"id":"C","text":"Contrastive diction"},{"id":"D","text":"Structural comparison"}],"answer":"B","explanation":"The concept is Nuance. It means A careful answer acknowledges mixed implications. An original example is: A closed door can protect and exclude. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Comparative Unseen Poetry\": A closed door can protect and exclude?","options":[{"id":"A","text":"Nuance"},{"id":"B","text":"Shared theme"},{"id":"C","text":"Contrastive diction"},{"id":"D","text":"Structural comparison"}],"answer":"A","explanation":"The best answer is Nuance because A careful answer acknowledges mixed implications. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Comparative Unseen Poetry\" at SSS3, which concept is defined as: Evidence from both poems is linked within one claim?","options":[{"id":"A","text":"Shared theme"},{"id":"B","text":"Contrastive diction"},{"id":"C","text":"Structural comparison"},{"id":"D","text":"Integrated paragraph"}],"answer":"D","explanation":"The concept is Integrated paragraph. It means Evidence from both poems is linked within one claim. An original example is: The two doors frame distinct responses to uncertainty. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Comparative Unseen Poetry\": The two doors frame distinct responses to uncertainty?","options":[{"id":"A","text":"Shared theme"},{"id":"B","text":"Contrastive diction"},{"id":"C","text":"Integrated paragraph"},{"id":"D","text":"Structural comparison"}],"answer":"C","explanation":"The best answer is Integrated paragraph because Evidence from both poems is linked within one claim. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."}]},{"level":"SSS3","term":3,"seq":4,"name":"Integrated Literature Examination Revision","intro":"Revision is strongest when students practise retrieving concepts, applying them to unseen material and correcting errors. Separate historical paper practice from newly authored exercises and verify every quotation or textual claim about a prescribed work.","passage":"A revision group studies an invented passage: ''The town''s bell rang for the meeting, but the doors stayed shut. From the square the learners read the sign announcing that the hall belonged to everyone.''","worked":"The mismatch between the claim of shared ownership and inaccessible doors offers evidence of institutional irony. A competent response names the contrast, quotes a short line and explains the implication, without asserting a real council policy.","concepts":[["Retrieval practice","Recall concepts from memory before checking notes","The student defines dramatic irony without prompts"],["Application","A concept is used to explain fresh textual evidence","The closed door is compared to the claim of shared access"],["Error review","An incorrect answer is analysed to locate its reasoning flaw","A learner revises a mistaken definition of tone"],["Timed outline","A small argument plan is produced under a realistic limit","Three claims are drafted before writing an essay"],["Provenance check","The source and status of a question or quotation are verified","Original practice is never labelled an official past paper"]],"slug":"lit-sss3-t3-integrated-literature-examination-revision","code":"G26LITSSS3T3U4","body":"# Integrated Literature Examination Revision — SSS3 Literature in English, Third Term\n\n## What you should achieve\nDefine and accurately apply five central literary concepts; use exact evidence from a new passage to support an interpretation; connect technique to its effect; and identify the limits of what the passage permits you to infer.\n\n## Conceptual foundation\nRevision is strongest when students practise retrieving concepts, applying them to unseen material and correcting errors. Separate historical paper practice from newly authored exercises and verify every quotation or textual claim about a prescribed work.\n\n**Source note:** The passage and exercises below are original THE GUIDE teaching examples. They are not passages from a historical WAEC, NECO or JAMB paper, and are not represented as quotations from copyrighted prescribed books. Read the school-approved books in full for set-text analysis.\n\n## New worked passage\n> A revision group studies an invented passage: ''The town''s bell rang for the meeting, but the doors stayed shut. From the square the learners read the sign announcing that the hall belonged to everyone.''\n\n## Interpretation: a model response\nThe mismatch between the claim of shared ownership and inaccessible doors offers evidence of institutional irony. A competent response names the contrast, quotes a short line and explains the implication, without asserting a real council policy.\n\nRead the passage once for literal information, again to notice diction, structure, dialogue, imagery or action, and a third time to test a thesis against a precise textual clue. A justified interpretation is not simply a personal opinion: it has a claim, evidence and reasoning. Different careful readers may make different claims, but they must account for the same details.\n\n## Five important concepts\n### 1. Retrieval practice\n**Meaning:** Recall concepts from memory before checking notes.\n**Original illustration:** The student defines dramatic irony without prompts.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 2. Application\n**Meaning:** A concept is used to explain fresh textual evidence.\n**Original illustration:** The closed door is compared to the claim of shared access.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 3. Error review\n**Meaning:** An incorrect answer is analysed to locate its reasoning flaw.\n**Original illustration:** A learner revises a mistaken definition of tone.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 4. Timed outline\n**Meaning:** A small argument plan is produced under a realistic limit.\n**Original illustration:** Three claims are drafted before writing an essay.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 5. Provenance check\n**Meaning:** The source and status of a question or quotation are verified.\n**Original illustration:** Original practice is never labelled an official past paper.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n## Method: move from detail to interpretation\n1. **Observe:** Identify who is speaking, what physically happens and which important detail stands out.\n2. **Classify:** Choose one relevant literary term. Do not force every device into the passage.\n3. **Evidence:** Quote a brief original phrase or describe a stage action exactly.\n4. **Reason:** Explain how that evidence affects characterisation, atmosphere, conflict, theme or audience knowledge.\n5. **Qualify:** Distinguish a well-supported reading from an assumption that the passage does not prove.\n\n## Guided application\nReturn to the original passage. State the central conflict or problem in one sentence. Choose two of the five concepts and write a separate evidence-based explanation for each. What does a careful audience know that a character may not know? If this question does not apply, explain why instead of inventing hidden facts.\n\n## Independent practice and rubric\nCreate a short original extract on a related situation, then write a 150–200 word close reading. For a ten-mark analytical paragraph, allocate 2 marks to a clear claim, 2 to accurate terminology, 3 to appropriate textual evidence and explanation, 2 to weighing a plausible alternative or limitation, and 1 to clear organisation. Your score should reward justified reasoning, not memorising one interpretation.\n\n## Common misconceptions\nAn original model excerpt is not a prescribed examination extract. A character''s words are not automatically an objective truth. A stage direction is not spoken dialogue. A metaphor is not literal proof of an event. A detailed explanation should show how the device works instead of merely naming it.\n\n## Check your own progress\nExplain each concept without looking at your flashcards. Attempt the accompanying ten original multiple-choice questions; review the reasoning after every incorrect answer. Compare your written response with the rubric rather than relying only on an MCQ score.","objectives":["Use accurate literary concepts in close reading","Ground arguments in exact words or stage actions","Evaluate alternative explanations responsibly"],"points":["Retrieval practice: Recall concepts from memory before checking notes","Application: A concept is used to explain fresh textual evidence","Error review: An incorrect answer is analysed to locate its reasoning flaw","Timed outline: A small argument plan is produced under a realistic limit","Provenance check: The source and status of a question or quotation are verified"],"cards":[{"front":"Define Retrieval practice in Integrated Literature Examination Revision.","back":"Recall concepts from memory before checking notes. Original illustration: The student defines dramatic irony without prompts.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Application in Integrated Literature Examination Revision.","back":"A concept is used to explain fresh textual evidence. Original illustration: The closed door is compared to the claim of shared access.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Error review in Integrated Literature Examination Revision.","back":"An incorrect answer is analysed to locate its reasoning flaw. Original illustration: A learner revises a mistaken definition of tone.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Timed outline in Integrated Literature Examination Revision.","back":"A small argument plan is produced under a realistic limit. Original illustration: Three claims are drafted before writing an essay.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Provenance check in Integrated Literature Examination Revision.","back":"The source and status of a question or quotation are verified. Original illustration: Original practice is never labelled an official past paper.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"How do you build a convincing interpretation of integrated literature examination revision?","back":"State a focused claim, cite an exact textual detail, explain the effect, and separate solid evidence from plausible inference.","sourceKind":"original-literature-skills","difficulty":"medium"}],"questions":[{"question":"In \"Integrated Literature Examination Revision\" at SSS3, which concept is defined as: Recall concepts from memory before checking notes?","options":[{"id":"A","text":"Application"},{"id":"B","text":"Retrieval practice"},{"id":"C","text":"Error review"},{"id":"D","text":"Timed outline"}],"answer":"B","explanation":"The concept is Retrieval practice. It means Recall concepts from memory before checking notes. An original example is: The student defines dramatic irony without prompts. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Integrated Literature Examination Revision\": The student defines dramatic irony without prompts?","options":[{"id":"A","text":"Retrieval practice"},{"id":"B","text":"Application"},{"id":"C","text":"Error review"},{"id":"D","text":"Timed outline"}],"answer":"A","explanation":"The best answer is Retrieval practice because Recall concepts from memory before checking notes. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Integrated Literature Examination Revision\" at SSS3, which concept is defined as: A concept is used to explain fresh textual evidence?","options":[{"id":"A","text":"Retrieval practice"},{"id":"B","text":"Error review"},{"id":"C","text":"Timed outline"},{"id":"D","text":"Application"}],"answer":"D","explanation":"The concept is Application. It means A concept is used to explain fresh textual evidence. An original example is: The closed door is compared to the claim of shared access. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Integrated Literature Examination Revision\": The closed door is compared to the claim of shared access?","options":[{"id":"A","text":"Retrieval practice"},{"id":"B","text":"Error review"},{"id":"C","text":"Application"},{"id":"D","text":"Timed outline"}],"answer":"C","explanation":"The best answer is Application because A concept is used to explain fresh textual evidence. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Integrated Literature Examination Revision\" at SSS3, which concept is defined as: An incorrect answer is analysed to locate its reasoning flaw?","options":[{"id":"A","text":"Retrieval practice"},{"id":"B","text":"Error review"},{"id":"C","text":"Application"},{"id":"D","text":"Timed outline"}],"answer":"B","explanation":"The concept is Error review. It means An incorrect answer is analysed to locate its reasoning flaw. An original example is: A learner revises a mistaken definition of tone. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Integrated Literature Examination Revision\": A learner revises a mistaken definition of tone?","options":[{"id":"A","text":"Error review"},{"id":"B","text":"Retrieval practice"},{"id":"C","text":"Application"},{"id":"D","text":"Timed outline"}],"answer":"A","explanation":"The best answer is Error review because An incorrect answer is analysed to locate its reasoning flaw. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Integrated Literature Examination Revision\" at SSS3, which concept is defined as: A small argument plan is produced under a realistic limit?","options":[{"id":"A","text":"Retrieval practice"},{"id":"B","text":"Application"},{"id":"C","text":"Error review"},{"id":"D","text":"Timed outline"}],"answer":"D","explanation":"The concept is Timed outline. It means A small argument plan is produced under a realistic limit. An original example is: Three claims are drafted before writing an essay. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Integrated Literature Examination Revision\": Three claims are drafted before writing an essay?","options":[{"id":"A","text":"Retrieval practice"},{"id":"B","text":"Application"},{"id":"C","text":"Timed outline"},{"id":"D","text":"Error review"}],"answer":"C","explanation":"The best answer is Timed outline because A small argument plan is produced under a realistic limit. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Integrated Literature Examination Revision\" at SSS3, which concept is defined as: The source and status of a question or quotation are verified?","options":[{"id":"A","text":"Retrieval practice"},{"id":"B","text":"Provenance check"},{"id":"C","text":"Application"},{"id":"D","text":"Error review"}],"answer":"B","explanation":"The concept is Provenance check. It means The source and status of a question or quotation are verified. An original example is: Original practice is never labelled an official past paper. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Integrated Literature Examination Revision\": Original practice is never labelled an official past paper?","options":[{"id":"A","text":"Provenance check"},{"id":"B","text":"Retrieval practice"},{"id":"C","text":"Application"},{"id":"D","text":"Error review"}],"answer":"A","explanation":"The best answer is Provenance check because The source and status of a question or quotation are verified. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."}]},{"level":"SSS3","term":3,"seq":5,"name":"Responsible Set-Text Analysis and Source Accuracy","intro":"A Literature guide should help learners analyse prescribed texts without inventing plots, quotations or examination status. Official set-text lists change over time; obtain the currently approved book before naming its characters or claiming an event happened.","passage":"A student reads a classroom handout with the heading ''Exam 2026'' and a passage attributed to an unknown poet. The student compares it with the school''s authorised text list and finds no matching title. Rather than memorising the passage as official, the student labels it practice and asks the teacher to confirm the source.","worked":"The scenario models source caution, not suspicion of every resource. Lack of a matching title is not proof the passage is fraudulent, but it prevents confident claims that it is officially prescribed.","concepts":[["Prescribed text","A work formally selected on an authorised reading list for a defined examination cycle","The student confirms the title against the current list"],["Authentic quotation","Exact words are verified from the actual text before citation","The learner checks line wording in a legitimate edition"],["Practice provenance","Authored or generated exercises are correctly identified as practice","An invented passage is marked original revision"],["Source triangulation","Independent reliable records are compared before making a factual claim","The teacher and approved reading list clarify text status"],["Ethical attribution","A writer or publisher is credited and words are not falsely assigned","Unknown lines are not named as a published poet''s work"]],"slug":"lit-sss3-t3-responsible-set-text-analysis-and-source-accuracy","code":"G26LITSSS3T3U5","body":"# Responsible Set-Text Analysis and Source Accuracy — SSS3 Literature in English, Third Term\n\n## What you should achieve\nDefine and accurately apply five central literary concepts; use exact evidence from a new passage to support an interpretation; connect technique to its effect; and identify the limits of what the passage permits you to infer.\n\n## Conceptual foundation\nA Literature guide should help learners analyse prescribed texts without inventing plots, quotations or examination status. Official set-text lists change over time; obtain the currently approved book before naming its characters or claiming an event happened.\n\n**Source note:** The passage and exercises below are original THE GUIDE teaching examples. They are not passages from a historical WAEC, NECO or JAMB paper, and are not represented as quotations from copyrighted prescribed books. Read the school-approved books in full for set-text analysis.\n\n## New worked passage\n> A student reads a classroom handout with the heading ''Exam 2026'' and a passage attributed to an unknown poet. The student compares it with the school''s authorised text list and finds no matching title. Rather than memorising the passage as official, the student labels it practice and asks the teacher to confirm the source.\n\n## Interpretation: a model response\nThe scenario models source caution, not suspicion of every resource. Lack of a matching title is not proof the passage is fraudulent, but it prevents confident claims that it is officially prescribed.\n\nRead the passage once for literal information, again to notice diction, structure, dialogue, imagery or action, and a third time to test a thesis against a precise textual clue. A justified interpretation is not simply a personal opinion: it has a claim, evidence and reasoning. Different careful readers may make different claims, but they must account for the same details.\n\n## Five important concepts\n### 1. Prescribed text\n**Meaning:** A work formally selected on an authorised reading list for a defined examination cycle.\n**Original illustration:** The student confirms the title against the current list.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 2. Authentic quotation\n**Meaning:** Exact words are verified from the actual text before citation.\n**Original illustration:** The learner checks line wording in a legitimate edition.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 3. Practice provenance\n**Meaning:** Authored or generated exercises are correctly identified as practice.\n**Original illustration:** An invented passage is marked original revision.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 4. Source triangulation\n**Meaning:** Independent reliable records are compared before making a factual claim.\n**Original illustration:** The teacher and approved reading list clarify text status.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n### 5. Ethical attribution\n**Meaning:** A writer or publisher is credited and words are not falsely assigned.\n**Original illustration:** Unknown lines are not named as a published poet''s work.\n**How to use it:** Locate the exact wording or action that fits this concept. Explain why it is an example, then state what effect it has in this literary situation. Avoid giving an isolated definition when the assessment asks you to analyse a passage.\n\n## Method: move from detail to interpretation\n1. **Observe:** Identify who is speaking, what physically happens and which important detail stands out.\n2. **Classify:** Choose one relevant literary term. Do not force every device into the passage.\n3. **Evidence:** Quote a brief original phrase or describe a stage action exactly.\n4. **Reason:** Explain how that evidence affects characterisation, atmosphere, conflict, theme or audience knowledge.\n5. **Qualify:** Distinguish a well-supported reading from an assumption that the passage does not prove.\n\n## Guided application\nReturn to the original passage. State the central conflict or problem in one sentence. Choose two of the five concepts and write a separate evidence-based explanation for each. What does a careful audience know that a character may not know? If this question does not apply, explain why instead of inventing hidden facts.\n\n## Independent practice and rubric\nCreate a short original extract on a related situation, then write a 150–200 word close reading. For a ten-mark analytical paragraph, allocate 2 marks to a clear claim, 2 to accurate terminology, 3 to appropriate textual evidence and explanation, 2 to weighing a plausible alternative or limitation, and 1 to clear organisation. Your score should reward justified reasoning, not memorising one interpretation.\n\n## Common misconceptions\nAn original model excerpt is not a prescribed examination extract. A character''s words are not automatically an objective truth. A stage direction is not spoken dialogue. A metaphor is not literal proof of an event. A detailed explanation should show how the device works instead of merely naming it.\n\n## Check your own progress\nExplain each concept without looking at your flashcards. Attempt the accompanying ten original multiple-choice questions; review the reasoning after every incorrect answer. Compare your written response with the rubric rather than relying only on an MCQ score.","objectives":["Use accurate literary concepts in close reading","Ground arguments in exact words or stage actions","Evaluate alternative explanations responsibly"],"points":["Prescribed text: A work formally selected on an authorised reading list for a defined examination cycle","Authentic quotation: Exact words are verified from the actual text before citation","Practice provenance: Authored or generated exercises are correctly identified as practice","Source triangulation: Independent reliable records are compared before making a factual claim","Ethical attribution: A writer or publisher is credited and words are not falsely assigned"],"cards":[{"front":"Define Prescribed text in Responsible Set-Text Analysis and Source Accuracy.","back":"A work formally selected on an authorised reading list for a defined examination cycle. Original illustration: The student confirms the title against the current list.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Authentic quotation in Responsible Set-Text Analysis and Source Accuracy.","back":"Exact words are verified from the actual text before citation. Original illustration: The learner checks line wording in a legitimate edition.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Practice provenance in Responsible Set-Text Analysis and Source Accuracy.","back":"Authored or generated exercises are correctly identified as practice. Original illustration: An invented passage is marked original revision.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Source triangulation in Responsible Set-Text Analysis and Source Accuracy.","back":"Independent reliable records are compared before making a factual claim. Original illustration: The teacher and approved reading list clarify text status.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"Define Ethical attribution in Responsible Set-Text Analysis and Source Accuracy.","back":"A writer or publisher is credited and words are not falsely assigned. Original illustration: Unknown lines are not named as a published poet''s work.","sourceKind":"original-literature-skills","difficulty":"medium"},{"front":"How do you build a convincing interpretation of responsible set-text analysis and source accuracy?","back":"State a focused claim, cite an exact textual detail, explain the effect, and separate solid evidence from plausible inference.","sourceKind":"original-literature-skills","difficulty":"medium"}],"questions":[{"question":"In \"Responsible Set-Text Analysis and Source Accuracy\" at SSS3, which concept is defined as: A work formally selected on an authorised reading list for a defined examination cycle?","options":[{"id":"A","text":"Authentic quotation"},{"id":"B","text":"Practice provenance"},{"id":"C","text":"Source triangulation"},{"id":"D","text":"Prescribed text"}],"answer":"D","explanation":"The concept is Prescribed text. It means A work formally selected on an authorised reading list for a defined examination cycle. An original example is: The student confirms the title against the current list. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Responsible Set-Text Analysis and Source Accuracy\": The student confirms the title against the current list?","options":[{"id":"A","text":"Authentic quotation"},{"id":"B","text":"Practice provenance"},{"id":"C","text":"Prescribed text"},{"id":"D","text":"Source triangulation"}],"answer":"C","explanation":"The best answer is Prescribed text because A work formally selected on an authorised reading list for a defined examination cycle. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Responsible Set-Text Analysis and Source Accuracy\" at SSS3, which concept is defined as: Exact words are verified from the actual text before citation?","options":[{"id":"A","text":"Prescribed text"},{"id":"B","text":"Authentic quotation"},{"id":"C","text":"Practice provenance"},{"id":"D","text":"Source triangulation"}],"answer":"B","explanation":"The concept is Authentic quotation. It means Exact words are verified from the actual text before citation. An original example is: The learner checks line wording in a legitimate edition. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Responsible Set-Text Analysis and Source Accuracy\": The learner checks line wording in a legitimate edition?","options":[{"id":"A","text":"Authentic quotation"},{"id":"B","text":"Prescribed text"},{"id":"C","text":"Practice provenance"},{"id":"D","text":"Source triangulation"}],"answer":"A","explanation":"The best answer is Authentic quotation because Exact words are verified from the actual text before citation. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Responsible Set-Text Analysis and Source Accuracy\" at SSS3, which concept is defined as: Authored or generated exercises are correctly identified as practice?","options":[{"id":"A","text":"Prescribed text"},{"id":"B","text":"Authentic quotation"},{"id":"C","text":"Source triangulation"},{"id":"D","text":"Practice provenance"}],"answer":"D","explanation":"The concept is Practice provenance. It means Authored or generated exercises are correctly identified as practice. An original example is: An invented passage is marked original revision. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Responsible Set-Text Analysis and Source Accuracy\": An invented passage is marked original revision?","options":[{"id":"A","text":"Prescribed text"},{"id":"B","text":"Authentic quotation"},{"id":"C","text":"Practice provenance"},{"id":"D","text":"Source triangulation"}],"answer":"C","explanation":"The best answer is Practice provenance because Authored or generated exercises are correctly identified as practice. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Responsible Set-Text Analysis and Source Accuracy\" at SSS3, which concept is defined as: Independent reliable records are compared before making a factual claim?","options":[{"id":"A","text":"Prescribed text"},{"id":"B","text":"Source triangulation"},{"id":"C","text":"Authentic quotation"},{"id":"D","text":"Practice provenance"}],"answer":"B","explanation":"The concept is Source triangulation. It means Independent reliable records are compared before making a factual claim. An original example is: The teacher and approved reading list clarify text status. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Responsible Set-Text Analysis and Source Accuracy\": The teacher and approved reading list clarify text status?","options":[{"id":"A","text":"Source triangulation"},{"id":"B","text":"Prescribed text"},{"id":"C","text":"Authentic quotation"},{"id":"D","text":"Practice provenance"}],"answer":"A","explanation":"The best answer is Source triangulation because Independent reliable records are compared before making a factual claim. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."},{"question":"In \"Responsible Set-Text Analysis and Source Accuracy\" at SSS3, which concept is defined as: A writer or publisher is credited and words are not falsely assigned?","options":[{"id":"A","text":"Prescribed text"},{"id":"B","text":"Authentic quotation"},{"id":"C","text":"Practice provenance"},{"id":"D","text":"Ethical attribution"}],"answer":"D","explanation":"The concept is Ethical attribution. It means A writer or publisher is credited and words are not falsely assigned. An original example is: Unknown lines are not named as a published poet''s work. This checks literary skills rather than reproducing a past examination question."},{"question":"Which literary concept is most clearly shown by this original illustration in \"Responsible Set-Text Analysis and Source Accuracy\": Unknown lines are not named as a published poet''s work?","options":[{"id":"A","text":"Prescribed text"},{"id":"B","text":"Authentic quotation"},{"id":"C","text":"Ethical attribution"},{"id":"D","text":"Practice provenance"}],"answer":"C","explanation":"The best answer is Ethical attribution because A writer or publisher is credited and words are not falsely assigned. Explain how the quoted detail illustrates this meaning; the other labels do not describe this particular effect."}]}]'::jsonb) AS x(level text,term int,seq int,name text,slug text,code text,body text,objectives jsonb,points jsonb,cards jsonb,questions jsonb);
CREATE TEMP TABLE literature_cohorts ON COMMIT DROP AS
SELECT cl.id class_id,cl.name class_name,cl.code class_code,tm.id term_id,tm.name term_name,u.level,u.term,
lower(cl.code)||'-lit-'||case u.term when 1 then 'first' when 2 then 'second' else 'third' end||'-term' course_slug
FROM (SELECT DISTINCT level,term FROM new_lit_units) u
JOIN public.classes cl ON cl.code IN (u.level||'-A',u.level||'-B')
JOIN public.terms tm ON tm.code='TERM-'||u.term::text;
DO $guard$ BEGIN
IF (SELECT count(*) FROM literature_cohorts)<>8 THEN RAISE EXCEPTION 'Expected eight class and term combinations'; END IF;
IF (SELECT count(*) FROM new_lit_units)<>20 THEN RAISE EXCEPTION 'Literature module batch incomplete'; END IF;
IF NOT EXISTS(SELECT 1 FROM public.subjects WHERE id='1d31ff41-d2f4-48f6-b473-5d2c0d52dcfc' AND name='Literature in English')
THEN RAISE EXCEPTION 'Literature subject changed'; END IF;
END $guard$;
INSERT INTO public.courses(id,subject_id,class_id,term_id,title,slug,short_description,full_description,difficulty,status,is_free,price,lesson_count,total_duration_hours,published_at,created_at,updated_at)
SELECT gen_random_uuid(),'1d31ff41-d2f4-48f6-b473-5d2c0d52dcfc',k.class_id,k.term_id,
'Literature in English - '||k.class_name||' - '||k.term_name,k.course_slug,
'Original Literature close-reading courses with source-aware interpretation and detailed practice.',
'Study prose, drama and poetry using original model passages, explained concepts, analysis rubrics and dedicated flashcard questions. Actual approved set texts should be read independently.',
'intermediate','published',true,0,0,4,now(),now(),now()
FROM literature_cohorts k
WHERE NOT EXISTS(SELECT 1 FROM public.courses c WHERE c.subject_id='1d31ff41-d2f4-48f6-b473-5d2c0d52dcfc' AND c.class_id=k.class_id AND c.term_id=k.term_id)
ON CONFLICT(slug) DO NOTHING;
INSERT INTO public.course_sections(id,course_id,title,description,order_index,is_active,created_at,updated_at)
SELECT gen_random_uuid(),c.id,k.term_name||' Lessons','Original Literature study and assessment',1,true,now(),now()
FROM literature_cohorts k JOIN public.courses c ON c.slug=k.course_slug
WHERE NOT EXISTS(SELECT 1 FROM public.course_sections cs WHERE cs.course_id=c.id);
INSERT INTO public.topics(id,subject_id,class_id,term_id,name,code,description,learning_objectives,order_index,estimated_hours,is_active,created_at,updated_at)
SELECT gen_random_uuid(),c.subject_id,c.class_id,c.term_id,u.name,u.code,
'Original literary-skills unit: '||u.name,u.objectives,u.seq,1,true,now(),now()
FROM literature_cohorts k JOIN public.courses c ON c.slug=k.course_slug
JOIN new_lit_units u ON u.level=k.level AND u.term=k.term
WHERE NOT EXISTS(SELECT 1 FROM public.topics t WHERE t.class_id=c.class_id AND t.subject_id=c.subject_id AND t.term_id=c.term_id AND lower(btrim(t.name))=lower(btrim(u.name)))
ON CONFLICT(subject_id,class_id,term_id,code) DO NOTHING;
INSERT INTO public.lessons(id,course_id,section_id,topic_id,title,slug,description,learning_objectives,content_type,written_content,key_points,order_index,is_free,is_published,estimated_minutes,teaching_version,content_quality,created_at,updated_at)
SELECT gen_random_uuid(),c.id,(SELECT cs.id FROM public.course_sections cs WHERE cs.course_id=c.id AND cs.is_active ORDER BY cs.order_index LIMIT 1),
t.id,u.level||' Literature: '||u.name,u.slug,
'Detailed original model passage, critical reading guidance, worked solution and independent formative assessment.',
u.objectives,'text',u.body,u.points,u.seq,true,true,35,3,'ready',now(),now()
FROM literature_cohorts k JOIN public.courses c ON c.slug=k.course_slug
JOIN new_lit_units u ON u.level=k.level AND u.term=k.term
JOIN public.topics t ON t.class_id=c.class_id AND t.subject_id=c.subject_id AND t.term_id=c.term_id AND lower(btrim(t.name))=lower(btrim(u.name))
WHERE NOT EXISTS(SELECT 1 FROM public.lessons l WHERE l.course_id=c.id
AND (l.topic_id=t.id OR l.slug=u.slug OR regexp_replace(lower(l.title),'[^a-z0-9]+','','g')=regexp_replace(lower(u.level||' Literature: '||u.name),'[^a-z0-9]+','','g')))
ON CONFLICT(course_id,slug) DO NOTHING;
INSERT INTO public.flashcards(id,course_id,lesson_id,topic_id,subject_id,title,description,cards,mode,is_public,created_at,updated_at)
SELECT gen_random_uuid(),l.course_id,l.id,l.topic_id,c.subject_id,u.level||' Literature: '||u.name,'Original concept recall deck',
u.cards,'curriculum-prebuilt',true,now(),now()
FROM literature_cohorts k JOIN public.courses c ON c.slug=k.course_slug
JOIN new_lit_units u ON u.level=k.level AND u.term=k.term
JOIN public.lessons l ON l.course_id=c.id AND l.slug=u.slug
WHERE NOT EXISTS(SELECT 1 FROM public.flashcards f WHERE f.lesson_id=l.id AND f.is_public AND f.created_by IS NULL AND f.mode='curriculum-prebuilt')
ON CONFLICT DO NOTHING;
INSERT INTO public.questions(id,subject_id,topic_id,class_id,question_type,question_text,options,correct_answer,explanation,difficulty,marks,source,exam_name,tags,is_active,created_at,updated_at)
SELECT gen_random_uuid(),c.subject_id,l.topic_id,c.class_id,'mcq',q->>'question',q->'options',to_jsonb(q->>'answer'),q->>'explanation','medium',1,
'THE GUIDE Original Literature Practice','Literature Skills and Close Reading Practice',
jsonb_build_array('original-literature','2026-skill-expansion','lesson:'||l.id::text),true,now(),now()
FROM literature_cohorts k JOIN public.courses c ON c.slug=k.course_slug
JOIN new_lit_units u ON u.level=k.level AND u.term=k.term
JOIN public.lessons l ON l.course_id=c.id AND l.slug=u.slug
CROSS JOIN LATERAL jsonb_array_elements(u.questions) q
WHERE jsonb_array_length(q->'options')=4
AND NOT EXISTS(SELECT 1 FROM public.questions q0 WHERE q0.topic_id=l.topic_id AND q0.is_active
AND regexp_replace(lower(btrim(q0.question_text)),'[^a-z0-9]+','','g')=regexp_replace(lower(btrim(q->>'question')),'[^a-z0-9]+','','g'));
UPDATE public.courses c SET lesson_count=(SELECT count(*) FROM public.lessons l WHERE l.course_id=c.id AND l.is_published),updated_at=now()
WHERE c.slug IN(SELECT course_slug FROM literature_cohorts);
COMMIT;